-- 0020_company_tax_id.sql
-- ---------------------------------------------------------------------------
-- The company's NPWP (tax ID), supplied by the company owner on 2026-10-30 from the NPWP card of PT Satu Arah International.
-- It is printed in the header and in the issuer block of every generated document (invoice, receipt, price agreement letter...).
-- An NPWP that the administrator has already entered is preserved.
INSERT INTO settings (key, value, updated_at)
VALUES ('tax_id', '1000 0000 1178 2812', NOW())
ON CONFLICT (key) DO UPDATE
  SET value = EXCLUDED.value, updated_at = NOW()
  WHERE settings.value IS NULL OR BTRIM(settings.value) = '';

-- ---------------------------------------------------------------------------
-- 0021_prepayment_receipts.sql
-- ---------------------------------------------------------------------------
-- A pre-payment receipt is created with every invoice. Many customers need a receipt, stamped with an e-meterai when the
-- amount is above IDR 5,000,000 (or in a foreign currency), before their own finance team releases the payment. It is
-- issued BEFORE the money arrives, states that it is no proof of payment, and is separate from the official payment
-- receipt (table `receipts`), which is still issued only after Finance has confirmed cleared funds.
-- One live (not void) per invoice; a voided one can be replaced. Status: draft (invoice not issued yet) -> pending_stamp (waiting for the manual e-meterai) or issued -> void.
-- RLS is enabled with no policies, so the Supabase Data API cannot read it.
CREATE TABLE IF NOT EXISTS prepayment_receipts (
  id                       SERIAL PRIMARY KEY,
  number                   VARCHAR(70)  NOT NULL UNIQUE,
  invoice_id               INTEGER      NOT NULL REFERENCES invoices (id),
  status                   VARCHAR(20)  NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'pending_stamp', 'issued', 'void')),
  currency                 VARCHAR(3)   NOT NULL,
  amount_minor             BIGINT       NOT NULL CHECK (amount_minor > 0),
  stamp_required           BOOLEAN      NOT NULL DEFAULT FALSE,
  stamp_storage_key        VARCHAR(500),
  stamp_sha256             VARCHAR(64),
  stamp_provider_reference VARCHAR(160),
  stamp_uploaded_at        TIMESTAMPTZ,
  stamp_uploaded_by        INTEGER REFERENCES users (id),
  created_at               TIMESTAMPTZ  NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS ux_prepayment_receipts_live ON prepayment_receipts (invoice_id) WHERE status <> 'void';
CREATE INDEX IF NOT EXISTS ix_prepayment_receipts_status ON prepayment_receipts (status, stamp_required);
ALTER TABLE prepayment_receipts ENABLE ROW LEVEL SECURITY;
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN
    REVOKE ALL ON TABLE prepayment_receipts FROM anon;
    REVOKE ALL ON SEQUENCE prepayment_receipts_id_seq FROM anon;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN
    REVOKE ALL ON TABLE prepayment_receipts FROM authenticated;
    REVOKE ALL ON SEQUENCE prepayment_receipts_id_seq FROM authenticated;
  END IF;
END $$;

-- The email that carries the pre-payment receipt to the customer (starts switched off like every other notification).
INSERT INTO email_templates (key, subject, html) VALUES
  ('prepayment_receipt_customer', $vora$VORA pre-payment receipt $document_number$vora$, $vora$<p>Dear $customer_name,</p><p>Please find attached the pre-payment receipt <strong>$document_number</strong> for invoice <strong>$invoice_number</strong>, prepared for your internal payment process.</p><p>It is not proof that payment has been made: VORA issues the official payment receipt once the funds are credited to its bank account. Verify the document through the QR code or <a href="$verify_url">online verification</a>.</p><p>VORA | Freight & Logistics</p>$vora$)
ON CONFLICT (key) DO NOTHING;
INSERT INTO email_rules (key, enabled) VALUES
  ('prepayment_receipt_customer', FALSE)
ON CONFLICT (key) DO NOTHING;

-- ---------------------------------------------------------------------------
-- 0022_general_documents.sql
-- ---------------------------------------------------------------------------
-- General documents: letters, billing letters, statements, powers of attorney, certification and assignment letters, certificates.
-- One table for all of them. What differs between the types (the form, the wording, the layout) lives in the application
-- (src/content/document-types.ts); `fields` holds what was typed, `kind` says which type it is. Every document has a number
-- (KIND-VORA-OWNER-YYYYMM-RANDOM5, the owner being the customer it is for or the company itself) and a QR verification link.
-- Status: draft (editable) -> issued (frozen) -> void. RLS is enabled with no policies, so the Supabase Data API cannot read it.
CREATE TABLE IF NOT EXISTS documents (
  id            SERIAL PRIMARY KEY,
  number        VARCHAR(70)  NOT NULL UNIQUE,
  kind          VARCHAR(30)  NOT NULL,
  language      VARCHAR(2)   NOT NULL DEFAULT 'id' CHECK (language IN ('id', 'en')),
  status        VARCHAR(10)  NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'issued', 'void')),
  customer_id   INTEGER REFERENCES customers (id),
  subject       VARCHAR(240) NOT NULL DEFAULT '',
  recipient     VARCHAR(240) NOT NULL DEFAULT '',
  document_date VARCHAR(10)  NOT NULL,                  -- YYYY-MM-DD, like every other date the documents carry
  fields        JSONB        NOT NULL DEFAULT '{}'::jsonb,
  created_by    INTEGER REFERENCES users (id),
  issued_by     INTEGER REFERENCES users (id),
  created_at    TIMESTAMPTZ  NOT NULL DEFAULT now(),
  updated_at    TIMESTAMPTZ  NOT NULL DEFAULT now(),
  issued_at     TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS ix_documents_kind_status ON documents (kind, status);
CREATE INDEX IF NOT EXISTS ix_documents_customer ON documents (customer_id);
ALTER TABLE documents ENABLE ROW LEVEL SECURITY;
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN
    REVOKE ALL ON TABLE documents FROM anon;
    REVOKE ALL ON SEQUENCE documents_id_seq FROM anon;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN
    REVOKE ALL ON TABLE documents FROM authenticated;
    REVOKE ALL ON SEQUENCE documents_id_seq FROM authenticated;
  END IF;
END $$;

-- ---------------------------------------------------------------------------
-- 0023_supabase_auth.sql
-- ---------------------------------------------------------------------------
-- Sign-in moves to Supabase Auth. Passwords, sessions, password reset and rate limits are Supabase's; this database keeps only WHO MAY USE THE PORTAL.
--
--   public.users stays the membership table (id, email, role, active) so every audit trail and "confirmed by / issued by" column that points
--   at users(id) keeps working. It gains `auth_user_id`, the link to auth.users. A person can sign in only when a Supabase Auth account exists AND
--   a row here links to it with role = 'admin' and active = true. The role is never read from Supabase user metadata (users can edit their own),
--   and there is no sign-up path in the application: a person who merely registers in Supabase Auth has no row here and no access.
--   public.users is not reachable through the Data API (RLS on, no policies, no grants to anon/authenticated).
--
-- First administrator, from the Supabase Dashboard:  Authentication > Users > Add user (email + password, tick "Auto Confirm User"), then in the
-- SQL Editor:   select public.promote_admin('you@company.com');
--
-- The link of a quotation-approval address used to be derived from SESSION_SECRET. With no application secret in the environment any more it
-- is derived from a random value generated here, once per database (table app_secrets; also locked from the Data API).
ALTER TABLE users ADD COLUMN IF NOT EXISTS auth_user_id UUID;
CREATE UNIQUE INDEX IF NOT EXISTS ux_users_auth_user_id ON users (auth_user_id) WHERE auth_user_id IS NOT NULL;
ALTER TABLE users ALTER COLUMN password_hash DROP NOT NULL;     -- passwords now live in Supabase Auth; old hashes of earlier accounts stay only as history

CREATE TABLE IF NOT EXISTS app_secrets (
  key        VARCHAR(60) PRIMARY KEY,
  value      TEXT        NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
INSERT INTO app_secrets (key, value)
  VALUES ('approval_link', replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', ''))
  ON CONFLICT (key) DO NOTHING;
ALTER TABLE app_secrets ENABLE ROW LEVEL SECURITY;

-- Grants an existing Supabase Auth account access to the portal. Run it in the SQL Editor (it runs as the project owner).
-- SECURITY DEFINER with a fixed search_path; not executable by anon or authenticated, so it cannot be called through the Data API.
CREATE OR REPLACE FUNCTION public.promote_admin(p_email text) RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth, pg_temp AS $fn$
DECLARE
  v_email text := lower(btrim(p_email));
  v_uid   uuid;
BEGIN
  IF v_email IS NULL OR v_email = '' THEN RAISE EXCEPTION 'An email address is required'; END IF;
  SELECT id INTO v_uid FROM auth.users WHERE lower(email) = v_email AND deleted_at IS NULL;
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'No Supabase Auth account with the email %. Create it first in Authentication > Users.', v_email;
  END IF;
  INSERT INTO public.users (email, auth_user_id, role, active) VALUES (v_email, v_uid, 'admin', TRUE)
    ON CONFLICT (email) DO UPDATE SET auth_user_id = EXCLUDED.auth_user_id, role = 'admin', active = TRUE;
  INSERT INTO public.audit_logs (actor_id, verb, object_type, object_id, summary)
    SELECT NULL, 'promote-admin', 'user', u.id, v_email FROM public.users u WHERE u.email = v_email;
  RETURN 'Admin access granted to ' || v_email;
END
$fn$;

-- Takes the access away at once (the account is refused on its next request); the Supabase Auth account itself is untouched.
CREATE OR REPLACE FUNCTION public.deactivate_admin(p_email text) RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $fn$
DECLARE
  v_email text := lower(btrim(p_email));
  v_id    integer;
BEGIN
  UPDATE public.users SET active = FALSE WHERE email = v_email RETURNING id INTO v_id;
  IF v_id IS NULL THEN RAISE EXCEPTION 'No portal account with the email %', v_email; END IF;
  INSERT INTO public.audit_logs (actor_id, verb, object_type, object_id, summary) VALUES (NULL, 'deactivate-admin', 'user', v_id, v_email);
  RETURN 'Access removed for ' || v_email;
END
$fn$;

DO $$
BEGIN
  REVOKE ALL ON FUNCTION public.promote_admin(text), public.deactivate_admin(text) FROM PUBLIC;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN
    REVOKE ALL ON FUNCTION public.promote_admin(text), public.deactivate_admin(text) FROM anon;
    REVOKE ALL ON TABLE app_secrets FROM anon;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN
    REVOKE ALL ON FUNCTION public.promote_admin(text), public.deactivate_admin(text) FROM authenticated;
    REVOKE ALL ON TABLE app_secrets FROM authenticated;
  END IF;
END $$;

-- ---------------------------------------------------------------------------
-- 0024_data_api.sql
-- ---------------------------------------------------------------------------
-- The database functions behind the Supabase Data API.
--
-- The application no longer opens a database connection of its own (no DATABASE_URL). It talks to the database through supabase-js with the
-- project's secret key (server side only): plain reads and writes use the table endpoints, and every operation that must stay consistent across
-- several statements is ONE function call here, so it is ONE transaction (PostgREST runs each call in its own).
--
-- Security of every function in this file
--   * Callable only by `service_role` (the secret key). EXECUTE is revoked from PUBLIC, anon and authenticated, and default privileges are
--     changed so a function added later is closed too. Nobody holding the publishable key, and nobody signed in, can call any of them.
--   * SECURITY INVOKER: a function runs with the caller's own rights (service_role), never with more, so it cannot be used to climb to the
--     rights of its owner. Because nothing here is SECURITY DEFINER, RLS and grants apply exactly as they do to direct table access.
--   * `search_path` is pinned (public, pg_temp) on every function, so a look-alike object in another schema cannot take over a name.
--   * Business refusals are raised with SQLSTATE `VRnnn` (nnn = the HTTP-like status, e.g. VR409 "already confirmed"); the application turns
--     them into form messages. Anything else is an unexpected failure and is reported as one.
--   * Row locks are taken in one fixed order everywhere (invoice, then payment, then receipt), numbers are allocated under a transaction-scoped
--     advisory lock and backed by unique indexes, and every state change writes its audit row in the same transaction.
--
-- What stays in the application: parsing and validating what a person typed, money arithmetic, PDF inspection, file storage and the rendering
-- and queuing of email. The functions re-check everything a concurrent request could have changed (state, balances, existence).

-- ============================================================================
-- Helpers
-- ============================================================================
CREATE OR REPLACE FUNCTION vr_fail(p_status integer, p_message text) RETURNS void
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
BEGIN
  RAISE EXCEPTION '%', p_message USING ERRCODE = 'VR' || lpad(p_status::text, 3, '0');
END
$fn$;

-- "Today" on a document is the date in Jakarta, not in UTC.
CREATE OR REPLACE FUNCTION vr_today() RETURNS text
LANGUAGE sql STABLE SET search_path = public, pg_temp AS $fn$
  SELECT to_char(now() AT TIME ZONE 'Asia/Jakarta', 'YYYY-MM-DD')
$fn$;

CREATE OR REPLACE FUNCTION vr_audit(p_actor integer, p_verb text, p_type text, p_id integer, p_summary text DEFAULT '') RETURNS void
LANGUAGE sql SET search_path = public, pg_temp AS $fn$
  INSERT INTO audit_logs (actor_id, verb, object_type, object_id, summary) VALUES (p_actor, p_verb, p_type, p_id, left(coalesce(p_summary, ''), 1000))
$fn$;

-- Stable, random per-customer / per-lead reference (C or L + 10 hex). Never derived from a name or an email.
-- `public_code IS NULL` in the UPDATE makes concurrent allocators converge on whichever code was stored first.
CREATE OR REPLACE FUNCTION vr_public_code(p_table text, p_id integer) RETURNS text
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE
  v_prefix text; v_existing text; v_candidate text; v_stored text; v_taken boolean; v_n bigint; i integer;
BEGIN
  IF p_table = 'customers' THEN v_prefix := 'C'; ELSIF p_table = 'leads' THEN v_prefix := 'L'; ELSE RAISE EXCEPTION 'Unsupported owner table'; END IF;
  EXECUTE format('SELECT count(*), max(public_code) FROM %I WHERE id = $1', p_table) INTO v_n, v_existing USING p_id;      -- EXECUTE does not set FOUND
  IF v_n = 0 THEN RAISE EXCEPTION 'Owner not found'; END IF;
  IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  FOR i IN 1..60 LOOP
    v_candidate := v_prefix || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 10));
    EXECUTE format('SELECT EXISTS (SELECT 1 FROM %I WHERE public_code = $1)', p_table) INTO v_taken USING v_candidate;
    CONTINUE WHEN v_taken;
    v_stored := NULL;
    EXECUTE format('UPDATE %I SET public_code = $1 WHERE id = $2 AND public_code IS NULL RETURNING public_code', p_table) INTO v_stored USING v_candidate, p_id;
    IF v_stored IS NOT NULL THEN RETURN v_stored; END IF;
    EXECUTE format('SELECT public_code FROM %I WHERE id = $1', p_table) INTO v_existing USING p_id;
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END LOOP;
  RAISE EXCEPTION 'Cannot allocate a unique owner code';
END
$fn$;

-- The company's own code (V + 10 hex): the owner of documents that are not for one customer. Stored once in the settings.
CREATE OR REPLACE FUNCTION vr_company_code() RETURNS text
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_code text;
BEGIN
  SELECT value INTO v_code FROM settings WHERE key = 'company_code';
  IF v_code ~ '^V[A-F0-9]{10}$' THEN RETURN v_code; END IF;
  INSERT INTO settings (key, value, updated_at) VALUES ('company_code', 'V' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 10)), now())
    ON CONFLICT (key) DO NOTHING;
  SELECT value INTO v_code FROM settings WHERE key = 'company_code';
  IF v_code IS NULL OR v_code !~ '^V[A-F0-9]{10}$' THEN RAISE EXCEPTION 'Cannot allocate the company code'; END IF;
  RETURN v_code;
END
$fn$;

-- KIND-VORA-OWNER-YYYYMM-RANDOM5. The last five digits are random, not a running counter. A transaction-scoped advisory lock serialises
-- allocation per (kind, owner, month); the unique index on the column stays the ultimate guard. Call it in the transaction that inserts the row.
CREATE OR REPLACE FUNCTION vr_next_number(p_kind text, p_owner text, p_date text DEFAULT NULL) RETURNS text
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE
  v_kind text := upper(p_kind); v_table text; v_column text; v_day text := coalesce(p_date, vr_today()); v_scope text; v_candidate text; v_taken boolean; i integer;
BEGIN
  v_table := CASE v_kind WHEN 'INV' THEN 'invoices' WHEN 'RCP' THEN 'receipts' WHEN 'PPR' THEN 'prepayment_receipts' WHEN 'QUO' THEN 'quotations'
                         WHEN 'RFQ' THEN 'leads' WHEN 'INQ' THEN 'leads' WHEN 'DLV' THEN 'deliveries' ELSE 'documents' END;
  v_column := CASE v_table WHEN 'leads' THEN 'reference' ELSE 'number' END;
  IF v_table = 'documents' AND v_kind !~ '^[A-Z]{2,4}$' THEN RAISE EXCEPTION 'Unsupported document kind'; END IF;
  IF p_owner IS NULL OR p_owner !~ '^[CLV][A-F0-9]{10}$' THEN RAISE EXCEPTION 'Invalid owner code'; END IF;
  IF v_day !~ '^\d{4}-\d{2}-\d{2}' THEN RAISE EXCEPTION 'Invalid date'; END IF;
  v_scope := v_kind || '-VORA-' || p_owner || '-' || substr(v_day, 1, 4) || substr(v_day, 6, 2) || '-';
  PERFORM pg_advisory_xact_lock(hashtext(v_scope));
  FOR i IN 1..160 LOOP
    v_candidate := v_scope || lpad(((('x' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 7))::bit(28)::integer) % 100000)::text, 5, '0');
    EXECUTE format('SELECT EXISTS (SELECT 1 FROM %I WHERE %I = $1)', v_table, v_column) INTO v_taken USING v_candidate;
    IF NOT v_taken THEN RETURN v_candidate; END IF;
  END LOOP;
  RAISE EXCEPTION 'Could not allocate a unique five-digit document number';
END
$fn$;

-- Opaque public token for a QR code: 36 random bytes, URL-safe base64. Only its SHA-256 is needed for lookup; the token is kept to print the URL.
CREATE OR REPLACE FUNCTION vr_create_verification(p_kind text, p_document integer) RETURNS text
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_token text;
BEGIN
  v_token := translate(encode(substring(decode(replace(gen_random_uuid()::text || gen_random_uuid()::text || gen_random_uuid()::text, '-', ''), 'hex') FROM 1 FOR 36), 'base64'), '+/=', '-_');
  INSERT INTO document_verification_tokens (token, token_hash, kind, document_id) VALUES (v_token, encode(sha256(convert_to(v_token, 'UTF8')), 'hex'), p_kind, p_document);
  RETURN v_token;
END
$fn$;

-- A frozen copy of a bank account, kept by invoices and payments so later edits never alter issued documents.
CREATE OR REPLACE FUNCTION vr_bank_snapshot(p_bank bank_accounts) RETURNS jsonb
LANGUAGE sql IMMUTABLE SET search_path = public, pg_temp AS $fn$
  SELECT jsonb_build_object('bank_name', coalesce(p_bank.bank_name, ''), 'account_number', coalesce(p_bank.account_number, ''), 'account_holder', coalesce(p_bank.account_holder, ''),
                            'currency', coalesce(p_bank.currency, ''), 'branch', coalesce(p_bank.branch, ''), 'swift_code', coalesce(p_bank.swift_code, ''))
$fn$;

-- Recomputes balance and status from the confirmed payments. A payment total above the invoice is a hard error.
CREATE OR REPLACE FUNCTION vr_recompute_outstanding(p_invoice integer, OUT o_outstanding bigint, OUT o_status text) RETURNS record
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_total bigint; v_status text; v_paid bigint;
BEGIN
  SELECT i.total_minor, i.status INTO v_total, v_status FROM invoices i WHERE i.id = p_invoice;
  SELECT coalesce(sum(p.amount_minor), 0)::bigint INTO v_paid FROM payments p WHERE p.invoice_id = p_invoice AND p.status = 'recorded';
  IF v_paid > v_total THEN PERFORM vr_fail(409, 'Confirmed payments exceed the invoice total'); END IF;
  o_outstanding := v_total - v_paid;
  o_status := CASE WHEN v_status = 'void' THEN 'void' WHEN o_outstanding = 0 THEN 'paid' WHEN v_paid > 0 THEN 'partially_paid' ELSE 'issued' END;
  UPDATE invoices SET outstanding_minor = o_outstanding, status = o_status WHERE id = p_invoice;
END
$fn$;

-- The pre-payment receipt made together with an invoice (a draft until the invoice is issued). Nothing is owed on a zero invoice.
CREATE OR REPLACE FUNCTION vr_create_prepayment(p_invoice integer, p_customer integer, p_currency text, p_total bigint, p_issued_at text, p_stamp_required boolean) RETURNS integer
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_number text; v_id integer;
BEGIN
  IF p_total <= 0 THEN RETURN NULL; END IF;
  v_number := vr_next_number('PPR', vr_public_code('customers', p_customer), p_issued_at);
  INSERT INTO prepayment_receipts (number, invoice_id, status, currency, amount_minor, stamp_required) VALUES (v_number, p_invoice, 'draft', p_currency, p_total, p_stamp_required) RETURNING id INTO v_id;
  PERFORM vr_create_verification('prepayment', v_id);
  RETURN v_id;
END
$fn$;

-- The invoice is issued: a receipt that needs no stamp is released now, the others wait for their e-meterai.
CREATE OR REPLACE FUNCTION vr_release_prepayment(p_invoice integer) RETURNS void
LANGUAGE sql SET search_path = public, pg_temp AS $fn$
  UPDATE prepayment_receipts SET status = CASE WHEN stamp_required THEN 'pending_stamp' ELSE 'issued' END WHERE invoice_id = p_invoice AND status = 'draft'
$fn$;

-- The invoice is void: its pre-payment receipt and its QR link go with it.
CREATE OR REPLACE FUNCTION vr_void_prepayments_of(p_invoice integer) RETURNS void
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
BEGIN
  UPDATE document_verification_tokens SET revoked = TRUE WHERE kind = 'prepayment' AND document_id IN (SELECT id FROM prepayment_receipts WHERE invoice_id = p_invoice);
  UPDATE prepayment_receipts SET status = 'void' WHERE invoice_id = p_invoice AND status <> 'void';
END
$fn$;

-- ============================================================================
-- Customers and bank accounts
-- ============================================================================
-- Creates or updates a customer (p_id NULL = create). The permanent owner code, used in every document number, is allocated once.
-- p: name, email, address, tax_id, currency, terms_days (already validated by the application).
CREATE OR REPLACE FUNCTION customer_save(p_actor integer, p_id integer, p jsonb) RETURNS integer
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_id integer := p_id; v_currency text; v_used bigint;
BEGIN
  IF p_id IS NOT NULL THEN
    SELECT currency INTO v_currency FROM customers WHERE id = p_id FOR UPDATE;
    IF NOT FOUND THEN PERFORM vr_fail(404, 'Customer not found'); END IF;
    IF v_currency <> p->>'currency' THEN
      SELECT (SELECT count(*) FROM invoices WHERE customer_id = p_id) + (SELECT count(*) FROM quotations WHERE customer_id = p_id) INTO v_used;
      IF v_used > 0 THEN PERFORM vr_fail(409, 'Currency cannot change on a customer that already has quotations or invoices'); END IF;
    END IF;
    UPDATE customers SET name = p->>'name', email = p->>'email', address = p->>'address', tax_id = p->>'tax_id', currency = p->>'currency', terms_days = (p->>'terms_days')::integer WHERE id = p_id;
  ELSE
    INSERT INTO customers (name, email, phone, address, tax_id, currency, terms_days)
      VALUES (p->>'name', p->>'email', '', p->>'address', p->>'tax_id', p->>'currency', (p->>'terms_days')::integer) RETURNING id INTO v_id;
  END IF;
  PERFORM vr_public_code('customers', v_id);
  PERFORM vr_audit(p_actor, 'upsert', 'customer', v_id, p->>'name');
  RETURN v_id;
END
$fn$;

-- p: bank_name, account_number, account_holder, currency, branch, swift_code, notes, make_default
CREATE OR REPLACE FUNCTION bank_create(p_actor integer, p jsonb) RETURNS integer
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_currency text := p->>'currency'; v_primary boolean; v_position integer; v_id integer;
BEGIN
  -- One preferred account per currency: the first account for a currency is preferred automatically.
  PERFORM pg_advisory_xact_lock(hashtext('bank-accounts-' || v_currency));
  v_primary := coalesce((p->>'make_default')::boolean, FALSE)
               OR (SELECT count(*) FROM bank_accounts WHERE currency = v_currency AND is_default AND active) = 0;
  IF v_primary THEN UPDATE bank_accounts SET is_default = FALSE WHERE currency = v_currency AND is_default; END IF;
  SELECT count(*)::integer + 1 INTO v_position FROM bank_accounts;
  INSERT INTO bank_accounts (bank_name, account_number, account_holder, currency, branch, swift_code, notes, active, is_default, position)
    VALUES (p->>'bank_name', p->>'account_number', p->>'account_holder', v_currency, p->>'branch', p->>'swift_code', p->>'notes', TRUE, v_primary, v_position) RETURNING id INTO v_id;
  PERFORM vr_audit(p_actor, 'create', 'bank-account', v_id, (p->>'bank_name') || ' / ' || v_currency);
  RETURN v_id;
END
$fn$;

CREATE OR REPLACE FUNCTION bank_update(p_actor integer, p_id integer, p_action text, p jsonb DEFAULT NULL) RETURNS void
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_bank bank_accounts%ROWTYPE; v_takeover boolean;
BEGIN
  SELECT * INTO v_bank FROM bank_accounts WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN PERFORM vr_fail(404, 'Bank account not found'); END IF;
  IF p_action = 'default' THEN
    IF NOT v_bank.active THEN PERFORM vr_fail(409, 'An inactive account cannot be the preferred account'); END IF;
    UPDATE bank_accounts SET is_default = FALSE WHERE currency = v_bank.currency AND is_default AND id <> p_id;
    UPDATE bank_accounts SET is_default = TRUE, updated_at = now() WHERE id = p_id;
  ELSIF p_action = 'disable' THEN
    UPDATE bank_accounts SET active = FALSE, is_default = FALSE, updated_at = now() WHERE id = p_id;
  ELSIF p_action = 'enable' THEN
    v_takeover := NOT EXISTS (SELECT 1 FROM bank_accounts WHERE currency = v_bank.currency AND is_default AND active AND id <> p_id);
    UPDATE bank_accounts SET active = TRUE, is_default = v_takeover, updated_at = now() WHERE id = p_id;
  ELSIF p_action = 'save' THEN
    IF p IS NULL THEN PERFORM vr_fail(422, 'Invalid bank details'); END IF;
    UPDATE bank_accounts SET bank_name = p->>'bank_name', account_number = p->>'account_number', account_holder = p->>'account_holder',
           branch = p->>'branch', swift_code = p->>'swift_code', notes = p->>'notes', updated_at = now() WHERE id = p_id;
  ELSE
    PERFORM vr_fail(422, 'Invalid action');
  END IF;
  PERFORM vr_audit(p_actor, p_action, 'bank-account', p_id, v_bank.bank_name);
END
$fn$;

-- ============================================================================
-- Invoices and their pre-payment receipts
-- ============================================================================
-- p: customer_id, currency, issued_at, due_at, po_number, shipment_reference, service_mode, origin, destination, transport_document_ref, notes,
--    tax_percent, withholding_percent, discount_minor, subtotal_minor, tax_minor, withholding_minor, total_minor, bank_ids[], stamp_required,
--    items[{description, unit, quantity, price_minor, amount_minor}]
CREATE OR REPLACE FUNCTION invoice_create(p_actor integer, p jsonb) RETURNS integer
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE
  v_cust customers%ROWTYPE; v_ids integer[]; v_bank bank_accounts%ROWTYPE; v_default integer; v_number text; v_id integer; v_bank_id integer; v_pos integer := 0; v_item jsonb;
BEGIN
  SELECT * INTO v_cust FROM customers WHERE id = (p->>'customer_id')::integer;
  IF NOT FOUND THEN PERFORM vr_fail(422, 'Select an existing customer'); END IF;
  IF v_cust.currency <> p->>'currency' THEN PERFORM vr_fail(409, 'The customer''s currency changed while the invoice was being prepared: try again'); END IF;
  SELECT coalesce(array_agg(t.value::integer ORDER BY t.ord), '{}') INTO v_ids FROM jsonb_array_elements_text(coalesce(p->'bank_ids', '[]'::jsonb)) WITH ORDINALITY AS t(value, ord);
  IF cardinality(v_ids) = 0 THEN
    SELECT id INTO v_default FROM bank_accounts WHERE currency = v_cust.currency AND active AND is_default;
    IF FOUND THEN v_ids := ARRAY[v_default]; END IF;
  END IF;
  FOREACH v_bank_id IN ARRAY v_ids LOOP
    SELECT * INTO v_bank FROM bank_accounts WHERE id = v_bank_id;
    IF NOT FOUND OR NOT v_bank.active OR v_bank.currency <> v_cust.currency THEN PERFORM vr_fail(422, 'Only active bank accounts in the invoice currency can be selected'); END IF;
  END LOOP;

  v_number := vr_next_number('INV', vr_public_code('customers', v_cust.id), p->>'issued_at');
  INSERT INTO invoices (number, customer_id, status, currency, issued_at, due_at, po_number, shipment_reference, service_mode, origin, destination,
      transport_document_ref, notes, tax_percent, withholding_percent, discount_minor, subtotal_minor, tax_minor, withholding_minor, total_minor, outstanding_minor)
    VALUES (v_number, v_cust.id, 'draft', v_cust.currency, p->>'issued_at', p->>'due_at', p->>'po_number', p->>'shipment_reference', p->>'service_mode', p->>'origin', p->>'destination',
      p->>'transport_document_ref', p->>'notes', p->>'tax_percent', p->>'withholding_percent', (p->>'discount_minor')::bigint, (p->>'subtotal_minor')::bigint, (p->>'tax_minor')::bigint,
      (p->>'withholding_minor')::bigint, (p->>'total_minor')::bigint, (p->>'total_minor')::bigint) RETURNING id INTO v_id;
  FOREACH v_bank_id IN ARRAY v_ids LOOP
    SELECT * INTO v_bank FROM bank_accounts WHERE id = v_bank_id;
    INSERT INTO invoice_bank_instructions (invoice_id, bank_account_id, bank_name, account_number, account_holder, currency, branch, swift_code, position)
      VALUES (v_id, v_bank.id, v_bank.bank_name, v_bank.account_number, v_bank.account_holder, v_bank.currency, v_bank.branch, v_bank.swift_code, v_pos);
    v_pos := v_pos + 1;
  END LOOP;
  FOR v_item IN SELECT * FROM jsonb_array_elements(p->'items') LOOP
    INSERT INTO invoice_items (invoice_id, description, unit, quantity, price_minor, amount_minor)
      VALUES (v_id, v_item->>'description', v_item->>'unit', v_item->>'quantity', (v_item->>'price_minor')::bigint, (v_item->>'amount_minor')::bigint);
  END LOOP;
  PERFORM vr_create_verification('invoice', v_id);
  -- Every invoice comes with its pre-payment receipt (a draft until the invoice is issued).
  PERFORM vr_create_prepayment(v_id, v_cust.id, v_cust.currency, (p->>'total_minor')::bigint, p->>'issued_at', coalesce((p->>'stamp_required')::boolean, FALSE));
  PERFORM vr_audit(p_actor, 'create', 'invoice', v_id, v_number);
  RETURN v_id;
END
$fn$;

-- issue: draft -> issued. void: only while nothing has been confirmed; open payment claims are cancelled with it.
CREATE OR REPLACE FUNCTION invoice_set_status(p_actor integer, p_id integer, p_action text) RETURNS void
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_inv invoices%ROWTYPE; v_cancelled integer;
BEGIN
  SELECT * INTO v_inv FROM invoices WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN PERFORM vr_fail(404, 'Invoice not found'); END IF;
  IF p_action = 'issue' AND v_inv.status = 'draft' THEN
    UPDATE invoices SET status = 'issued' WHERE id = p_id;
    PERFORM vr_release_prepayment(p_id);
  ELSIF p_action = 'void' AND v_inv.status NOT IN ('void', 'paid', 'partially_paid') THEN
    UPDATE invoices SET status = 'void' WHERE id = p_id;
    UPDATE document_verification_tokens SET revoked = TRUE WHERE kind = 'invoice' AND document_id = p_id;
    PERFORM vr_void_prepayments_of(p_id);
    WITH c AS (UPDATE payments SET status = 'cancelled' WHERE invoice_id = p_id AND status = 'pending_confirmation' RETURNING id) SELECT count(*) INTO v_cancelled FROM c;
    IF v_cancelled > 0 THEN PERFORM vr_audit(p_actor, 'cancel-unconfirmed-payment', 'invoice', p_id, v_cancelled || ' open payment claim(s) cancelled with the void'); END IF;
  ELSE
    PERFORM vr_fail(409, 'Invalid state change. Reverse confirmed payments (void their receipts) before voiding an invoice');
  END IF;
  PERFORM vr_audit(p_actor, p_action, 'invoice', p_id, v_inv.number);
END
$fn$;

-- For an invoice that has none: made before pre-payment receipts existed, or whose receipt was voided. Only while nothing has been paid.
CREATE OR REPLACE FUNCTION prepayment_ensure(p_actor integer, p_invoice integer, p_stamp_required boolean) RETURNS integer
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_inv invoices%ROWTYPE; v_id integer;
BEGIN
  SELECT * INTO v_inv FROM invoices WHERE id = p_invoice FOR UPDATE;
  IF NOT FOUND THEN PERFORM vr_fail(404, 'Invoice not found'); END IF;
  IF v_inv.status NOT IN ('draft', 'issued') THEN PERFORM vr_fail(409, 'A pre-payment receipt can only be made for an invoice that is unpaid and not void'); END IF;
  IF EXISTS (SELECT 1 FROM prepayment_receipts WHERE invoice_id = p_invoice AND status <> 'void') THEN PERFORM vr_fail(409, 'This invoice already has a pre-payment receipt'); END IF;
  v_id := vr_create_prepayment(p_invoice, v_inv.customer_id, v_inv.currency, v_inv.total_minor, v_inv.issued_at, p_stamp_required);
  IF v_id IS NULL THEN PERFORM vr_fail(409, 'The invoice total is zero: there is nothing to receive'); END IF;
  IF v_inv.status = 'issued' THEN PERFORM vr_release_prepayment(p_invoice); END IF;
  PERFORM vr_audit(p_actor, 'create', 'prepayment-receipt', v_id, 'Invoice ' || v_inv.number);
  RETURN v_id;
END
$fn$;

-- The stamped PDF was checked and stored by the application; this records it, but only if the receipt is still waiting for it.
CREATE OR REPLACE FUNCTION prepayment_stamp_commit(p_actor integer, p_id integer, p_key text, p_sha256 text, p_reference text) RETURNS void
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_row prepayment_receipts%ROWTYPE;
BEGIN
  SELECT * INTO v_row FROM prepayment_receipts WHERE id = p_id FOR UPDATE;
  IF NOT FOUND OR v_row.status <> 'pending_stamp' OR NOT v_row.stamp_required THEN PERFORM vr_fail(409, 'This pre-payment receipt is not waiting for a manual e-meterai'); END IF;
  UPDATE prepayment_receipts SET stamp_storage_key = p_key, stamp_sha256 = p_sha256, stamp_uploaded_at = now(), stamp_uploaded_by = p_actor, stamp_provider_reference = p_reference, status = 'issued' WHERE id = p_id;
  PERFORM vr_audit(p_actor, 'stamp-upload', 'prepayment-receipt', p_id, 'Official e-meterai reference: ' || p_reference || '; sha256: ' || p_sha256);
END
$fn$;

CREATE OR REPLACE FUNCTION prepayment_void(p_actor integer, p_id integer) RETURNS void
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_row prepayment_receipts%ROWTYPE;
BEGIN
  SELECT * INTO v_row FROM prepayment_receipts WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN PERFORM vr_fail(404, 'Pre-payment receipt not found'); END IF;
  IF v_row.status = 'void' THEN PERFORM vr_fail(409, 'The pre-payment receipt is already void'); END IF;
  UPDATE prepayment_receipts SET status = 'void' WHERE id = p_id;
  UPDATE document_verification_tokens SET revoked = TRUE WHERE kind = 'prepayment' AND document_id = p_id;
  PERFORM vr_audit(p_actor, 'void', 'prepayment-receipt', p_id, v_row.number);
END
$fn$;

-- ============================================================================
-- Payments and official receipts
-- ============================================================================
-- Records a payment CLAIM. Nothing is credited: the invoice balance stays unchanged and no receipt exists until Finance confirms the money
-- reached the bank. Open claims reserve part of the balance, so two people cannot claim the same money twice.
CREATE OR REPLACE FUNCTION payment_record(p_actor integer, p_invoice integer, p_amount bigint, p_date text, p_method text, p_reference text, p_bank integer) RETURNS integer
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_inv invoices%ROWTYPE; v_outstanding bigint; v_reserved bigint; v_bank bank_accounts%ROWTYPE; v_snapshot jsonb; v_id integer;
BEGIN
  SELECT * INTO v_inv FROM invoices WHERE id = p_invoice FOR UPDATE;
  IF NOT FOUND THEN PERFORM vr_fail(404, 'Invoice not found'); END IF;
  IF v_inv.status NOT IN ('issued', 'partially_paid') THEN PERFORM vr_fail(409, 'The invoice must be issued and have an unpaid balance'); END IF;
  SELECT o_outstanding INTO v_outstanding FROM vr_recompute_outstanding(p_invoice);
  SELECT coalesce(sum(amount_minor), 0)::bigint INTO v_reserved FROM payments WHERE invoice_id = p_invoice AND status = 'pending_confirmation';
  IF p_amount <= 0 OR p_amount > v_outstanding - v_reserved THEN PERFORM vr_fail(422, 'The amount exceeds the unreserved outstanding balance'); END IF;
  IF p_date > vr_today() THEN PERFORM vr_fail(422, 'Payment date cannot be in the future'); END IF;
  IF p_bank IS NOT NULL THEN
    SELECT * INTO v_bank FROM bank_accounts WHERE id = p_bank;
    IF NOT FOUND OR NOT v_bank.active OR v_bank.currency <> v_inv.currency THEN PERFORM vr_fail(422, 'The receiving bank account is inactive or does not match the invoice currency'); END IF;
    v_snapshot := vr_bank_snapshot(v_bank);
  END IF;
  INSERT INTO payments (invoice_id, amount_minor, date, method, reference, status, receiving_bank_id, receiving_bank_snapshot)
    VALUES (p_invoice, p_amount, p_date, p_method, p_reference, 'pending_confirmation', p_bank, v_snapshot::json) RETURNING id INTO v_id;
  PERFORM vr_audit(p_actor, 'payment-pending', 'invoice', p_invoice, format('Payment #%s: %s %s; not cleared', v_id, p_amount, v_inv.currency));
  RETURN v_id;
END
$fn$;

CREATE OR REPLACE FUNCTION payment_cancel(p_actor integer, p_payment integer) RETURNS integer
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_invoice integer; v_pay payments%ROWTYPE;
BEGIN
  SELECT invoice_id INTO v_invoice FROM payments WHERE id = p_payment;
  IF NOT FOUND THEN PERFORM vr_fail(404, 'Payment not found'); END IF;
  PERFORM 1 FROM invoices WHERE id = v_invoice FOR UPDATE;
  SELECT * INTO v_pay FROM payments WHERE id = p_payment FOR UPDATE;
  IF v_pay.status <> 'pending_confirmation' THEN PERFORM vr_fail(409, 'Only unconfirmed payments can be cancelled here'); END IF;
  UPDATE payments SET status = 'cancelled' WHERE id = p_payment;
  PERFORM vr_audit(p_actor, 'cancel-unconfirmed-payment', 'payment', p_payment, 'No funds confirmed');
  RETURN v_invoice;
END
$fn$;

-- Finance confirms that the funds are credited. In ONE transaction, under row locks (invoice first, then payment, the same order everywhere):
-- the payment becomes recorded, the invoice balance and status are recomputed, the receipt and its verification link are created.
-- Concurrent confirmations of the same payment: exactly one succeeds. Returns what the application needs to queue the customer emails.
CREATE OR REPLACE FUNCTION payment_confirm(p_actor integer, p_payment integer, p_bank integer, p_stamp_required boolean) RETURNS jsonb
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE
  v_invoice integer; v_inv invoices%ROWTYPE; v_pay payments%ROWTYPE; v_confirmed bigint; v_bank bank_accounts%ROWTYPE; v_snapshot json;
  v_outstanding bigint; v_status text; v_after bigint; v_cust customers%ROWTYPE; v_number text; v_receipt integer; v_token text;
BEGIN
  SELECT invoice_id INTO v_invoice FROM payments WHERE id = p_payment;
  IF NOT FOUND THEN PERFORM vr_fail(404, 'Payment not found'); END IF;
  SELECT * INTO v_inv FROM invoices WHERE id = v_invoice FOR UPDATE;
  SELECT * INTO v_pay FROM payments WHERE id = p_payment FOR UPDATE;
  IF v_pay.status <> 'pending_confirmation' THEN PERFORM vr_fail(409, 'The payment was already confirmed, cancelled or voided'); END IF;
  IF v_inv.status IN ('draft', 'void') THEN PERFORM vr_fail(409, 'The invoice is not eligible for payment confirmation'); END IF;
  SELECT coalesce(sum(amount_minor), 0)::bigint INTO v_confirmed FROM payments WHERE invoice_id = v_inv.id AND status = 'recorded';
  IF v_pay.amount_minor > v_inv.total_minor - v_confirmed THEN PERFORM vr_fail(409, 'The payment exceeds the invoice balance'); END IF;

  v_snapshot := v_pay.receiving_bank_snapshot;
  IF p_bank IS NOT NULL THEN
    SELECT * INTO v_bank FROM bank_accounts WHERE id = p_bank;
    IF NOT FOUND OR NOT v_bank.active OR v_bank.currency <> v_inv.currency THEN PERFORM vr_fail(422, 'The receiving bank account is inactive or does not match the invoice currency'); END IF;
    v_snapshot := vr_bank_snapshot(v_bank)::json;
    UPDATE payments SET receiving_bank_id = v_bank.id, receiving_bank_snapshot = v_snapshot WHERE id = p_payment;
  END IF;
  IF v_snapshot IS NULL AND lower(btrim(v_pay.method)) ~ '^(bank )?transfer$' THEN PERFORM vr_fail(422, 'Select the VORA bank account that received the transfer'); END IF;

  UPDATE payments SET status = 'recorded', confirmed_at = now(), confirmed_by = p_actor WHERE id = p_payment;
  SELECT r.o_outstanding, r.o_status INTO v_outstanding, v_status FROM vr_recompute_outstanding(v_inv.id) r;
  SELECT outstanding_minor INTO v_after FROM invoices WHERE id = v_inv.id;
  SELECT * INTO v_cust FROM customers WHERE id = v_inv.customer_id;
  v_number := vr_next_number('RCP', vr_public_code('customers', v_cust.id), coalesce(nullif(v_pay.date, ''), vr_today()));
  INSERT INTO receipts (number, invoice_id, payment_id, status, stamp_required) VALUES (v_number, v_inv.id, p_payment, CASE WHEN p_stamp_required THEN 'pending_stamp' ELSE 'issued' END, p_stamp_required) RETURNING id INTO v_receipt;
  v_token := vr_create_verification('receipt', v_receipt);
  PERFORM vr_audit(p_actor, 'confirm-cleared-payment', 'payment', p_payment, format('Invoice %s; receipt %s; %s; bank credit confirmed', v_inv.number, v_number, v_status));
  RETURN jsonb_build_object('receipt_id', v_receipt, 'receipt_number', v_number, 'token', v_token, 'invoice_id', v_inv.id, 'invoice_number', v_inv.number, 'currency', v_inv.currency,
    'invoice_status', v_status, 'outstanding_minor', v_after, 'stamp_required', p_stamp_required,
    'payment', jsonb_build_object('amount_minor', v_pay.amount_minor, 'date', v_pay.date, 'reference', v_pay.reference),
    'customer', jsonb_build_object('id', v_cust.id, 'name', v_cust.name, 'email', v_cust.email));
END
$fn$;

-- The stamped PDF was checked and stored by the application; this records it, but only if the receipt is still waiting for it.
CREATE OR REPLACE FUNCTION receipt_stamp_commit(p_actor integer, p_id integer, p_key text, p_sha256 text, p_reference text) RETURNS jsonb
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_receipt receipts%ROWTYPE; v_inv invoices%ROWTYPE; v_cust customers%ROWTYPE; v_token text;
BEGIN
  SELECT * INTO v_receipt FROM receipts WHERE id = p_id FOR UPDATE;
  IF NOT FOUND OR v_receipt.status <> 'pending_stamp' OR NOT v_receipt.stamp_required THEN PERFORM vr_fail(409, 'This receipt is not waiting for a manual e-meterai'); END IF;
  SELECT * INTO v_inv FROM invoices WHERE id = v_receipt.invoice_id;
  SELECT * INTO v_cust FROM customers WHERE id = v_inv.customer_id;
  UPDATE receipts SET stamp_storage_key = p_key, stamp_sha256 = p_sha256, stamp_uploaded_at = now(), stamp_uploaded_by = p_actor, stamp_provider_reference = p_reference, status = 'issued' WHERE id = p_id;
  SELECT token INTO v_token FROM document_verification_tokens WHERE kind = 'receipt' AND document_id = p_id ORDER BY id LIMIT 1;
  PERFORM vr_audit(p_actor, 'stamp-upload', 'receipt', p_id, 'Official e-meterai reference: ' || p_reference || '; sha256: ' || p_sha256);
  RETURN jsonb_build_object('receipt_number', v_receipt.number, 'token', coalesce(v_token, ''), 'invoice_number', v_inv.number, 'customer', jsonb_build_object('name', v_cust.name, 'email', v_cust.email));
END
$fn$;

-- Voids a receipt AND reverses its payment: the invoice balance and status are recalculated and the QR link is revoked.
CREATE OR REPLACE FUNCTION receipt_void(p_actor integer, p_id integer) RETURNS void
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_ref receipts%ROWTYPE; v_receipt receipts%ROWTYPE; v_pay payments%ROWTYPE;
BEGIN
  SELECT * INTO v_ref FROM receipts WHERE id = p_id;
  IF NOT FOUND THEN PERFORM vr_fail(404, 'Receipt not found'); END IF;
  PERFORM 1 FROM invoices WHERE id = v_ref.invoice_id FOR UPDATE;
  SELECT * INTO v_receipt FROM receipts WHERE id = p_id FOR UPDATE;
  IF v_receipt.status = 'void' THEN PERFORM vr_fail(409, 'The receipt is already void'); END IF;
  SELECT * INTO v_pay FROM payments WHERE id = v_ref.payment_id FOR UPDATE;
  IF NOT FOUND OR v_pay.status <> 'recorded' THEN PERFORM vr_fail(409, 'The payment is not in a recorded state'); END IF;
  UPDATE receipts SET status = 'void' WHERE id = p_id;
  UPDATE payments SET status = 'void' WHERE id = v_pay.id;
  UPDATE document_verification_tokens SET revoked = TRUE WHERE kind = 'receipt' AND document_id = p_id;
  PERFORM vr_recompute_outstanding(v_ref.invoice_id);
  PERFORM vr_audit(p_actor, 'void-payment-and-receipt', 'receipt', p_id, v_receipt.number);
END
$fn$;

-- ============================================================================
-- Quotations and the customer's approval upload
-- ============================================================================
-- p: owner_kind ('customer' | 'lead'), owner_id, currency, issued_at, valid_until, payment_terms, terms_conditions, notes, tax_percent,
--    subtotal_minor, tax_minor, total_minor, items[{description, unit, quantity, price_minor, amount_minor}]
CREATE OR REPLACE FUNCTION quotation_create(p_actor integer, p jsonb) RETURNS integer
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE
  v_kind text := p->>'owner_kind'; v_owner integer := (p->>'owner_id')::integer; v_currency text; v_number text; v_id integer; v_item jsonb;
BEGIN
  IF v_kind = 'customer' THEN
    SELECT currency INTO v_currency FROM customers WHERE id = v_owner;
    IF NOT FOUND THEN PERFORM vr_fail(422, 'Recipient unavailable'); END IF;
  ELSIF v_kind = 'lead' THEN
    PERFORM 1 FROM leads WHERE id = v_owner;
    IF NOT FOUND THEN PERFORM vr_fail(422, 'Recipient unavailable'); END IF;
    v_currency := 'IDR';
  ELSE
    PERFORM vr_fail(422, 'Select a customer or lead');
  END IF;
  IF v_currency <> p->>'currency' THEN PERFORM vr_fail(409, 'The recipient''s currency changed while the quotation was being prepared: try again'); END IF;
  v_number := vr_next_number('QUO', vr_public_code(CASE WHEN v_kind = 'customer' THEN 'customers' ELSE 'leads' END, v_owner), p->>'issued_at');
  INSERT INTO quotations (number, customer_id, lead_id, status, currency, issued_at, valid_until, payment_terms, terms_conditions, notes, tax_percent, subtotal_minor, tax_minor, total_minor)
    VALUES (v_number, CASE WHEN v_kind = 'customer' THEN v_owner END, CASE WHEN v_kind = 'lead' THEN v_owner END, 'draft', v_currency, p->>'issued_at', p->>'valid_until',
            p->>'payment_terms', p->>'terms_conditions', p->>'notes', p->>'tax_percent', (p->>'subtotal_minor')::bigint, (p->>'tax_minor')::bigint, (p->>'total_minor')::bigint) RETURNING id INTO v_id;
  FOR v_item IN SELECT * FROM jsonb_array_elements(p->'items') LOOP
    INSERT INTO quotation_items (quotation_id, description, unit, quantity, price_minor, amount_minor)
      VALUES (v_id, v_item->>'description', v_item->>'unit', v_item->>'quantity', (v_item->>'price_minor')::bigint, (v_item->>'amount_minor')::bigint);
  END LOOP;
  PERFORM vr_create_verification('quotation', v_id);
  PERFORM vr_audit(p_actor, 'create', 'quotation', v_id, v_number);
  RETURN v_id;
END
$fn$;

-- issue: draft -> issued. void: draft/issued/awaiting/approved -> void, revoking the QR link and any open approval link.
CREATE OR REPLACE FUNCTION quotation_set_status(p_actor integer, p_id integer, p_action text) RETURNS void
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_q quotations%ROWTYPE;
BEGIN
  SELECT * INTO v_q FROM quotations WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN PERFORM vr_fail(404, 'Quotation not found'); END IF;
  IF p_action = 'issue' AND v_q.status = 'draft' THEN
    UPDATE quotations SET status = 'issued' WHERE id = p_id;
  ELSIF p_action = 'void' AND v_q.status IN ('draft', 'issued', 'awaiting_approval', 'approved') THEN
    UPDATE quotations SET status = 'void' WHERE id = p_id;
    UPDATE quotation_approvals SET status = 'revoked' WHERE quotation_id = p_id AND status = 'pending';
    UPDATE document_verification_tokens SET revoked = TRUE WHERE kind = 'quotation' AND document_id = p_id;
  ELSE
    PERFORM vr_fail(409, 'Quotation cannot make that status transition');
  END IF;
  PERFORM vr_audit(p_actor, p_action, 'quotation', p_id, v_q.number);
END
$fn$;

-- The link of an approval request is derived from the request's own number (see approval-token.ts), so the number is taken first.
CREATE OR REPLACE FUNCTION quotation_approval_next_id() RETURNS integer
LANGUAGE sql SET search_path = public, pg_temp AS $fn$
  SELECT nextval(pg_get_serial_sequence('quotation_approvals', 'id'))::integer
$fn$;

-- Opens a private, expiring upload link for the customer. Earlier pending links are revoked. The application sends the email afterwards.
CREATE OR REPLACE FUNCTION quotation_request_approval(p_actor integer, p_id integer, p_approval integer, p_token_hash text, p_expires_at timestamptz) RETURNS jsonb
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_q quotations%ROWTYPE; v_token text;
BEGIN
  SELECT * INTO v_q FROM quotations WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN PERFORM vr_fail(404, 'Quotation not found'); END IF;
  IF v_q.status NOT IN ('issued', 'awaiting_approval') THEN PERFORM vr_fail(409, 'Issue the quotation before requesting customer approval'); END IF;
  IF v_q.valid_until < vr_today() THEN PERFORM vr_fail(409, 'Quotation validity has expired'); END IF;
  UPDATE quotation_approvals SET status = 'revoked' WHERE quotation_id = p_id AND status = 'pending';
  INSERT INTO quotation_approvals (id, quotation_id, token_hash, expires_at, status) VALUES (p_approval, p_id, p_token_hash, p_expires_at, 'pending');
  UPDATE quotations SET status = 'awaiting_approval' WHERE id = p_id;
  SELECT token INTO v_token FROM document_verification_tokens WHERE kind = 'quotation' AND document_id = p_id ORDER BY id LIMIT 1;
  PERFORM vr_audit(p_actor, 'send-approval-request', 'quotation', p_id, format('Customer approval link #%s expires %s', p_approval, to_char(p_expires_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
  RETURN jsonb_build_object('number', v_q.number, 'valid_until', v_q.valid_until, 'verification_token', coalesce(v_token, ''));
END
$fn$;

-- The customer's upload (already checked and stored by the application). It never approves anything by itself: it waits for Finance's review.
CREATE OR REPLACE FUNCTION approval_submit(p_token_hash text, p_key text, p_sha256 text, p_signer text, p_title text) RETURNS jsonb
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_item quotation_approvals%ROWTYPE; v_q quotations%ROWTYPE;
BEGIN
  SELECT * INTO v_item FROM quotation_approvals WHERE token_hash = p_token_hash FOR UPDATE;
  IF NOT FOUND THEN PERFORM vr_fail(404, 'This approval link is not valid'); END IF;
  SELECT * INTO v_q FROM quotations WHERE id = v_item.quotation_id FOR UPDATE;
  IF v_item.status <> 'pending' OR v_item.expires_at < now() OR NOT FOUND OR v_q.status <> 'awaiting_approval' THEN
    PERFORM vr_fail(410, 'This approval request has expired or was already used');
  END IF;
  UPDATE quotation_approvals SET signed_pdf_key = p_key, signed_pdf_sha256 = p_sha256, signer_name = p_signer, signer_title = p_title, uploaded_at = now(), status = 'submitted' WHERE id = v_item.id;
  PERFORM vr_audit(NULL, 'customer-approval-upload', 'quotation', v_item.quotation_id, format('Customer submission #%s, SHA256 %s', v_item.id, p_sha256));
  RETURN jsonb_build_object('approval_id', v_item.id, 'quotation_id', v_item.quotation_id, 'number', v_q.number);
END
$fn$;

-- Finance's decision on a submitted file. Approval requires a manual look at the signature and company stamp.
CREATE OR REPLACE FUNCTION approval_review(p_actor integer, p_id integer, p_outcome text, p_verified boolean, p_note text) RETURNS jsonb
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_item quotation_approvals%ROWTYPE; v_q quotations%ROWTYPE;
BEGIN
  IF p_outcome NOT IN ('approve', 'reject') THEN PERFORM vr_fail(422, 'Invalid review outcome'); END IF;
  SELECT * INTO v_item FROM quotation_approvals WHERE id = p_id FOR UPDATE;
  IF NOT FOUND OR v_item.status <> 'submitted' THEN PERFORM vr_fail(409, 'Only submitted approvals can be reviewed'); END IF;
  SELECT * INTO v_q FROM quotations WHERE id = v_item.quotation_id FOR UPDATE;
  IF NOT FOUND OR v_q.status <> 'awaiting_approval' THEN PERFORM vr_fail(409, 'The quotation is no longer awaiting approval'); END IF;
  IF p_outcome = 'approve' AND NOT coalesce(p_verified, FALSE) THEN PERFORM vr_fail(422, 'Confirm that the signature and company stamp were reviewed manually'); END IF;
  UPDATE quotation_approvals SET status = CASE WHEN p_outcome = 'approve' THEN 'approved' ELSE 'rejected' END, reviewed_by = p_actor, reviewed_at = now(), review_note = left(p_note, 2000) WHERE id = p_id;
  UPDATE quotations SET status = CASE WHEN p_outcome = 'approve' THEN 'approved' ELSE 'issued' END WHERE id = v_q.id;
  PERFORM vr_audit(p_actor, 'customer-quotation-' || p_outcome, 'quotation', v_q.id, format('Approval #%s; PDF checksum %s', p_id, v_item.signed_pdf_sha256));
  RETURN jsonb_build_object('quotation_id', v_q.id, 'number', v_q.number);
END
$fn$;

-- ============================================================================
-- Email queue
-- ============================================================================
-- Claims due messages atomically (FOR UPDATE SKIP LOCKED + a lease), so two cron workers or an admin click can never send the same message
-- twice, and a crashed worker's jobs are picked up again once the lease runs out.
CREATE OR REPLACE FUNCTION mail_claim(p_limit integer, p_lease_minutes integer) RETURNS SETOF email_jobs
LANGUAGE sql SET search_path = public, pg_temp AS $fn$
  UPDATE email_jobs SET status = 'sending', next_attempt_at = now() + make_interval(mins => p_lease_minutes)
  WHERE id IN (SELECT id FROM email_jobs WHERE status IN ('queued', 'retry', 'sending') AND next_attempt_at <= now() ORDER BY id LIMIT least(greatest(p_limit, 1), 30) FOR UPDATE SKIP LOCKED)
  RETURNING *
$fn$;

-- Puts a failed or waiting message back in the queue (admin "Retry").
CREATE OR REPLACE FUNCTION mail_retry(p_actor integer, p_id integer) RETURNS void
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_job email_jobs%ROWTYPE;
BEGIN
  SELECT * INTO v_job FROM email_jobs WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN PERFORM vr_fail(404, 'Message not found'); END IF;
  IF v_job.status NOT IN ('failed', 'retry') THEN PERFORM vr_fail(409, 'Only failed or waiting messages can be retried'); END IF;
  UPDATE email_jobs SET status = 'queued', attempts = 0, error = '', next_attempt_at = now() WHERE id = p_id;
  PERFORM vr_audit(p_actor, 'retry', 'email-job', p_id, v_job.event);
END
$fn$;

-- ============================================================================
-- Website enquiries
-- ============================================================================
-- Stores a contact message or RFQ from the public website, with its reference number, in one transaction. The per-address throttle is counted under
-- an advisory lock, so a burst of simultaneous submissions cannot slip past it.
-- p: kind ('rfq' | 'contact'), name, email, message, company, mode, origin, destination, cargo, pickup, window_minutes, max_per_email
CREATE OR REPLACE FUNCTION lead_create(p jsonb) RETURNS jsonb
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_rfq boolean := p->>'kind' = 'rfq'; v_id integer; v_ref text; v_recent integer;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('lead-' || lower(p->>'email')));
  SELECT count(*) INTO v_recent FROM leads WHERE email = p->>'email' AND created_at >= now() - make_interval(mins => (p->>'window_minutes')::integer);
  IF v_recent >= (p->>'max_per_email')::integer THEN PERFORM vr_fail(429, 'Too many submissions; try again later'); END IF;
  INSERT INTO leads (type, name, email, message, company, mode, origin, destination, cargo, pickup, source)
    VALUES (CASE WHEN v_rfq THEN 'RFQ' ELSE 'contact' END, p->>'name', p->>'email', p->>'message', p->>'company',
            CASE WHEN v_rfq THEN p->>'mode' ELSE '' END, CASE WHEN v_rfq THEN p->>'origin' ELSE '' END, CASE WHEN v_rfq THEN p->>'destination' ELSE '' END,
            CASE WHEN v_rfq THEN p->>'cargo' ELSE '' END, CASE WHEN v_rfq THEN p->>'pickup' ELSE '' END, 'website') RETURNING id INTO v_id;
  v_ref := vr_next_number(CASE WHEN v_rfq THEN 'RFQ' ELSE 'INQ' END, vr_public_code('leads', v_id));
  UPDATE leads SET reference = v_ref WHERE id = v_id;
  RETURN jsonb_build_object('id', v_id, 'reference', v_ref);
END
$fn$;

-- ============================================================================
-- Website content (articles, pages, sections)
-- ============================================================================
-- The application cleans and validates the text (HTML sanitising, slugs, allowed layouts); these functions keep the revision history, the
-- publishing snapshot and the audit row consistent with the change, in one transaction.
CREATE OR REPLACE FUNCTION vr_article_snapshot(a articles) RETURNS jsonb
LANGUAGE sql IMMUTABLE SET search_path = public, pg_temp AS $fn$
  SELECT jsonb_build_object('title', a.title, 'slug', a.slug, 'excerpt', a.excerpt, 'body', a.body, 'category', a.category, 'tags', a.tags, 'locale', a.locale,
    'status', a.status, 'cover', a.cover, 'author', a.author, 'seoTitle', a.seo_title, 'seoDescription', a.seo_description)
$fn$;

-- Saves (p_id NULL = create) an article; every edit first stores the previous state as a revision.
-- p: title, slug, excerpt, body, category, tags, locale, author, seo_title, seo_description.  p_action: 'publish' | 'unpublish' | anything else = plain save
CREATE OR REPLACE FUNCTION article_save(p_actor integer, p_id integer, p jsonb, p_action text) RETURNS integer
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_old articles%ROWTYPE; v_id integer := p_id; v_status text;
BEGIN
  v_status := CASE p_action WHEN 'publish' THEN 'published' WHEN 'unpublish' THEN 'draft' END;
  IF p_id IS NOT NULL THEN
    SELECT * INTO v_old FROM articles WHERE id = p_id FOR UPDATE;
    IF NOT FOUND THEN PERFORM vr_fail(404, 'Article not found'); END IF;
    INSERT INTO revisions (resource, resource_id, snapshot, author_id) VALUES ('article', p_id, vr_article_snapshot(v_old)::json, p_actor);
    UPDATE articles SET title = p->>'title', slug = p->>'slug', excerpt = p->>'excerpt', body = p->>'body', category = p->>'category', tags = p->>'tags', locale = p->>'locale',
           author = p->>'author', seo_title = p->>'seo_title', seo_description = p->>'seo_description', updated_at = now() WHERE id = p_id;
    IF v_status = 'published' THEN UPDATE articles SET status = 'published', published_at = now() WHERE id = p_id;
    ELSIF v_status = 'draft' THEN UPDATE articles SET status = 'draft' WHERE id = p_id; END IF;
  ELSE
    INSERT INTO articles (title, slug, excerpt, body, category, tags, locale, author, seo_title, seo_description, status, published_at)
      VALUES (p->>'title', p->>'slug', p->>'excerpt', p->>'body', p->>'category', p->>'tags', p->>'locale', p->>'author', p->>'seo_title', p->>'seo_description',
              coalesce(v_status, 'draft'), CASE WHEN v_status = 'published' THEN now() END) RETURNING id INTO v_id;
  END IF;
  PERFORM vr_audit(p_actor, CASE WHEN p_action = 'publish' THEN 'publish' ELSE 'update' END, 'article', v_id, p->>'title');
  RETURN v_id;
END
$fn$;

-- p_body is the revision's body after the application sanitised it again.
CREATE OR REPLACE FUNCTION article_restore(p_actor integer, p_id integer, p_revision integer, p_body text) RETURNS void
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_a articles%ROWTYPE; v_r revisions%ROWTYPE; v_snap jsonb;
BEGIN
  SELECT * INTO v_a FROM articles WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN PERFORM vr_fail(404, 'Not found'); END IF;
  SELECT * INTO v_r FROM revisions WHERE id = p_revision AND resource = 'article' AND resource_id = p_id;
  IF NOT FOUND THEN PERFORM vr_fail(404, 'Not found'); END IF;
  INSERT INTO revisions (resource, resource_id, snapshot, author_id) VALUES ('article', p_id, vr_article_snapshot(v_a)::json, p_actor);
  v_snap := v_r.snapshot::jsonb;
  UPDATE articles SET title = v_snap->>'title', slug = v_snap->>'slug', excerpt = v_snap->>'excerpt', body = p_body, category = v_snap->>'category', tags = v_snap->>'tags',
         locale = v_snap->>'locale', status = v_snap->>'status', cover = coalesce(v_snap->>'cover', ''), author = v_snap->>'author',
         seo_title = coalesce(v_snap->>'seoTitle', ''), seo_description = coalesce(v_snap->>'seoDescription', ''), updated_at = now() WHERE id = p_id;
  PERFORM vr_audit(p_actor, 'restore', 'article', p_id, p_revision::text);
END
$fn$;

-- A frozen copy of a page and its sections: visitors only ever see published snapshots. Keys stay snake_case (a stable format).
CREATE OR REPLACE FUNCTION vr_page_snapshot(p pages) RETURNS jsonb
LANGUAGE sql STABLE SET search_path = public, pg_temp AS $fn$
  SELECT jsonb_build_object('title', p.title, 'slug', p.slug, 'description', p.description, 'seo_title', p.seo_title, 'seo_description', p.seo_description, 'locale', p.locale,
    'sections', coalesce((SELECT jsonb_agg(jsonb_build_object('position', s.position, 'kind', s.kind, 'layout', s.layout, 'visible', s.visible, 'title', s.title, 'body', s.body,
      'image', s.image, 'button_label', s.button_label, 'button_href', s.button_href, 'surface', s.surface) ORDER BY s.position, s.id) FROM sections s WHERE s.page_id = p.id), '[]'::jsonb))
$fn$;

-- p: title, slug, locale, description, seo_title.  p_action: 'publish' | 'unpublish' | other = save as draft
CREATE OR REPLACE FUNCTION page_save(p_actor integer, p_id integer, p jsonb, p_action text) RETURNS integer
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_id integer := p_id; v_page pages%ROWTYPE;
BEGIN
  IF p_id IS NOT NULL THEN
    PERFORM 1 FROM pages WHERE id = p_id FOR UPDATE;
    IF NOT FOUND THEN PERFORM vr_fail(404, 'Page not found'); END IF;
    UPDATE pages SET title = p->>'title', slug = p->>'slug', locale = p->>'locale', description = p->>'description', seo_title = p->>'seo_title', seo_description = p->>'description', updated_at = now() WHERE id = p_id;
  ELSE
    INSERT INTO pages (title, slug, locale, description, seo_title, seo_description) VALUES (p->>'title', p->>'slug', p->>'locale', p->>'description', p->>'seo_title', p->>'description') RETURNING id INTO v_id;
  END IF;
  SELECT * INTO v_page FROM pages WHERE id = v_id;
  IF p_action = 'publish' THEN
    INSERT INTO revisions (resource, resource_id, snapshot, author_id) VALUES ('page', v_id, coalesce(v_page.published_snapshot, '{}'::json), p_actor);
    UPDATE pages SET published_snapshot = vr_page_snapshot(v_page)::json, status = 'published' WHERE id = v_id;
  ELSIF p_action = 'unpublish' THEN
    UPDATE pages SET status = 'draft' WHERE id = v_id;
  END IF;
  PERFORM vr_audit(p_actor, coalesce(nullif(p_action, ''), 'draft'), 'page', v_id, p->>'slug');
  RETURN v_id;
END
$fn$;

CREATE OR REPLACE FUNCTION page_restore(p_actor integer, p_id integer, p_revision integer) RETURNS void
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_r revisions%ROWTYPE;
BEGIN
  SELECT * INTO v_r FROM revisions WHERE id = p_revision AND resource = 'page' AND resource_id = p_id;
  IF NOT FOUND THEN PERFORM vr_fail(404, 'Not found'); END IF;
  IF v_r.snapshot IS NULL OR (v_r.snapshot::jsonb) -> 'sections' IS NULL THEN PERFORM vr_fail(409, 'Previous revision is empty'); END IF;
  UPDATE pages SET published_snapshot = v_r.snapshot, status = 'published' WHERE id = p_id;
  PERFORM vr_audit(p_actor, 'restore', 'page', p_id, p_revision::text);
END
$fn$;

CREATE OR REPLACE FUNCTION section_add(p_page integer) RETURNS void
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
BEGIN
  PERFORM 1 FROM pages WHERE id = p_page FOR UPDATE;
  IF NOT FOUND THEN PERFORM vr_fail(404, 'Page not found'); END IF;
  INSERT INTO sections (page_id, position, kind, layout, visible, title, body)
    VALUES (p_page, (SELECT coalesce(max(position), 0) + 1 FROM sections WHERE page_id = p_page), 'editorial', 'split', TRUE, 'New editorial block', 'Edit this text before publishing');
END
$fn$;

-- Updates, reorders (p_move 'up' | 'down') or deletes (p_remove) a draft section. Returns the owning page id.
-- p: title, body, kind, layout, surface, visible, button_label, button_href, image  (already validated by the application)
CREATE OR REPLACE FUNCTION section_save(p_actor integer, p_id integer, p jsonb, p_move text, p_remove boolean) RETURNS integer
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_s sections%ROWTYPE; v_ids integer[]; v_i integer; v_j integer; v_tmp integer; n integer;
BEGIN
  SELECT * INTO v_s FROM sections WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN PERFORM vr_fail(404, 'Section not found'); END IF;
  IF p_remove THEN
    DELETE FROM sections WHERE id = p_id;
  ELSIF p_move IN ('up', 'down') THEN
    SELECT array_agg(id ORDER BY position, id) INTO v_ids FROM sections WHERE page_id = v_s.page_id;
    v_i := array_position(v_ids, p_id);
    v_j := v_i + CASE WHEN p_move = 'up' THEN -1 ELSE 1 END;
    IF v_j >= 1 AND v_j <= cardinality(v_ids) THEN
      v_tmp := v_ids[v_i]; v_ids[v_i] := v_ids[v_j]; v_ids[v_j] := v_tmp;
      FOR n IN 1..cardinality(v_ids) LOOP UPDATE sections SET position = n - 1 WHERE id = v_ids[n]; END LOOP;
    END IF;
  ELSE
    UPDATE sections SET title = p->>'title', body = p->>'body', kind = p->>'kind', layout = p->>'layout', surface = p->>'surface', visible = (p->>'visible')::boolean,
           button_label = p->>'button_label', button_href = p->>'button_href', image = p->>'image' WHERE id = p_id;
  END IF;
  PERFORM vr_audit(p_actor, 'update', 'section', p_id, 'section draft');
  RETURN v_s.page_id;
END
$fn$;

-- ============================================================================
-- General documents (letters, statements, certificates...)
-- ============================================================================
-- The application validates what was typed against the document type and hands over the finished values.
-- p: prefix (number prefix of the type), kind, language, customer_id (or null), subject, recipient, document_date, fields (json)
CREATE OR REPLACE FUNCTION document_create(p_actor integer, p jsonb) RETURNS integer
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_customer integer := nullif(p->>'customer_id', '')::integer; v_owner text; v_number text; v_id integer;
BEGIN
  IF v_customer IS NOT NULL THEN
    PERFORM 1 FROM customers WHERE id = v_customer;
    IF NOT FOUND THEN PERFORM vr_fail(422, 'Select an existing customer'); END IF;
    v_owner := vr_public_code('customers', v_customer);
  ELSE
    v_owner := vr_company_code();
  END IF;
  v_number := vr_next_number(p->>'prefix', v_owner, p->>'document_date');
  INSERT INTO documents (number, kind, language, status, customer_id, subject, recipient, document_date, fields, created_by)
    VALUES (v_number, p->>'kind', p->>'language', 'draft', v_customer, p->>'subject', p->>'recipient', p->>'document_date', (p->'fields')::json, p_actor) RETURNING id INTO v_id;
  PERFORM vr_create_verification('document', v_id);
  PERFORM vr_audit(p_actor, 'create', 'document', v_id, v_number);
  RETURN v_id;
END
$fn$;

-- Only a draft can be edited. p: customer_id, subject, recipient, document_date, fields
CREATE OR REPLACE FUNCTION document_update(p_actor integer, p_id integer, p jsonb) RETURNS void
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_doc documents%ROWTYPE;
BEGIN
  SELECT * INTO v_doc FROM documents WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN PERFORM vr_fail(404, 'Document not found'); END IF;
  IF v_doc.status <> 'draft' THEN PERFORM vr_fail(409, 'Only a draft can be edited: void this document and write a new one'); END IF;
  UPDATE documents SET customer_id = nullif(p->>'customer_id', '')::integer, subject = p->>'subject', recipient = p->>'recipient', document_date = p->>'document_date',
         fields = (p->'fields')::json, updated_at = now() WHERE id = p_id;
  PERFORM vr_audit(p_actor, 'update', 'document', p_id, v_doc.number);
END
$fn$;

-- issue: draft -> issued, with the values the application re-checked against the type and the invoices as they stand now (p). It is refused if
-- the draft was edited meanwhile (p_expected is the updated_at the application read, to the millisecond). void: any draft or issued document.
CREATE OR REPLACE FUNCTION document_set_status(p_actor integer, p_id integer, p_action text, p jsonb DEFAULT NULL, p_expected timestamptz DEFAULT NULL) RETURNS void
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_doc documents%ROWTYPE;
BEGIN
  SELECT * INTO v_doc FROM documents WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN PERFORM vr_fail(404, 'Document not found'); END IF;
  IF p_action = 'issue' AND v_doc.status = 'draft' THEN
    IF p IS NULL OR date_trunc('milliseconds', v_doc.updated_at) <> date_trunc('milliseconds', p_expected) THEN PERFORM vr_fail(409, 'The draft was changed while it was being issued: open it again'); END IF;
    UPDATE documents SET status = 'issued', issued_at = now(), issued_by = p_actor, subject = p->>'subject', recipient = p->>'recipient', fields = (p->'fields')::json, updated_at = now() WHERE id = p_id;
  ELSIF p_action = 'void' AND v_doc.status <> 'void' THEN
    UPDATE documents SET status = 'void', updated_at = now() WHERE id = p_id;
    UPDATE document_verification_tokens SET revoked = TRUE WHERE kind = 'document' AND document_id = p_id;
  ELSE
    PERFORM vr_fail(409, 'Invalid state change');
  END IF;
  PERFORM vr_audit(p_actor, p_action, 'document', p_id, v_doc.number);
END
$fn$;

-- ============================================================================
-- Who may call what
-- ============================================================================
DO $$
DECLARE f record;
BEGIN
  FOR f IN
    SELECT p.oid::regprocedure AS sig FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public' AND (p.proname LIKE 'vr\_%' OR p.proname IN (
      'customer_save', 'bank_create', 'bank_update', 'invoice_create', 'invoice_set_status', 'prepayment_ensure', 'prepayment_stamp_commit', 'prepayment_void',
      'payment_record', 'payment_cancel', 'payment_confirm', 'receipt_stamp_commit', 'receipt_void', 'quotation_create', 'quotation_set_status',
      'quotation_approval_next_id', 'quotation_request_approval', 'approval_submit', 'approval_review', 'mail_claim', 'mail_retry', 'lead_create', 'article_save', 'article_restore', 'page_save', 'page_restore', 'section_add', 'section_save', 'document_create', 'document_update', 'document_set_status'))
  LOOP
    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC', f.sig);
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN EXECUTE format('REVOKE ALL ON FUNCTION %s FROM anon', f.sig); END IF;
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN EXECUTE format('REVOKE ALL ON FUNCTION %s FROM authenticated', f.sig); END IF;
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'service_role') THEN EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role', f.sig); END IF;
  END LOOP;
  -- A function added by a later migration starts closed, too: it must be opened to service_role on purpose.
  ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE EXECUTE ON FUNCTIONS FROM anon; END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE EXECUTE ON FUNCTIONS FROM authenticated; END IF;
END $$;

-- ---------------------------------------------------------------------------
-- 0025_deliveries.sql
-- ---------------------------------------------------------------------------
-- Delivery notes (surat jalan) with a proof of delivery (POD).
-- A delivery note travels with the goods and carries a QR code. The DRIVER or COURIER who delivers the goods scans it, on their own phone, at
-- the handover: they say who they are, the receiver gives their name and signs on the screen, the driver photographs the goods, and the
-- phone's position (the location must be on: a proof without it is refused) and the time are recorded: that is the POD.
-- The QR code and the emailed "view the POD" link are two different, unguessable tokens (a printed QR must keep working, so they are
-- stored, not derived from a secret that may be rotated). Evidence files (signature, photos) live in the private documents bucket.
-- Delivery status: draft -> issued -> delivered (a POD was submitted) -> back to issued when Finance rejects the POD; void from draft or issued.
-- RLS is enabled with no policies, so the Supabase Data API cannot read any of it; the server reaches it with the secret key, through the
-- functions at the end of this file (SECURITY INVOKER, EXECUTE only for service_role).
CREATE TABLE IF NOT EXISTS deliveries (
  id                 SERIAL PRIMARY KEY,
  number             VARCHAR(70)  NOT NULL UNIQUE,
  status             VARCHAR(12)  NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'issued', 'delivered', 'void')),
  customer_id        INTEGER REFERENCES customers (id),
  consignee_name     VARCHAR(240) NOT NULL,
  consignee_address  TEXT         NOT NULL DEFAULT '',
  consignee_contact  VARCHAR(160) NOT NULL DEFAULT '',
  consignee_phone    VARCHAR(60)  NOT NULL DEFAULT '',
  consignee_email    VARCHAR(200) NOT NULL DEFAULT '',
  origin             VARCHAR(240) NOT NULL DEFAULT '',
  destination        VARCHAR(240) NOT NULL DEFAULT '',
  shipment_reference VARCHAR(120) NOT NULL DEFAULT '',
  po_number          VARCHAR(100) NOT NULL DEFAULT '',
  carrier            VARCHAR(160) NOT NULL DEFAULT '',
  vehicle            VARCHAR(120) NOT NULL DEFAULT '',
  vehicle_plate      VARCHAR(30)  NOT NULL DEFAULT '',
  driver_name        VARCHAR(160) NOT NULL DEFAULT '',
  driver_phone       VARCHAR(60)  NOT NULL DEFAULT '',
  delivery_date      VARCHAR(10)  NOT NULL,
  notes              TEXT         NOT NULL DEFAULT '',
  capture_token      VARCHAR(120) NOT NULL UNIQUE,
  view_token         VARCHAR(120) NOT NULL UNIQUE,
  created_by         INTEGER REFERENCES users (id),
  created_at         TIMESTAMPTZ  NOT NULL DEFAULT now(),
  updated_at         TIMESTAMPTZ  NOT NULL DEFAULT now(),
  issued_at          TIMESTAMPTZ,
  delivered_at       TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS ix_deliveries_status ON deliveries (status);
CREATE INDEX IF NOT EXISTS ix_deliveries_customer ON deliveries (customer_id);

CREATE TABLE IF NOT EXISTS delivery_items (
  id          SERIAL PRIMARY KEY,
  delivery_id INTEGER      NOT NULL REFERENCES deliveries (id),
  position    INTEGER      NOT NULL DEFAULT 0,
  description VARCHAR(500) NOT NULL,
  quantity    VARCHAR(40)  NOT NULL,
  unit        VARCHAR(30)  NOT NULL DEFAULT 'pcs',
  remarks     VARCHAR(240) NOT NULL DEFAULT ''
);
CREATE INDEX IF NOT EXISTS ix_delivery_items_delivery ON delivery_items (delivery_id, position);

-- One live (submitted) proof per delivery; a rejected one stays as history and the delivery can be received again.
-- The location is required for a new proof (delivery_submit_proof refuses one without it); 'unavailable' stays allowed by the table so a row
-- recorded some other way is still valid.
CREATE TABLE IF NOT EXISTS delivery_proofs (
  id                 SERIAL PRIMARY KEY,
  delivery_id        INTEGER      NOT NULL REFERENCES deliveries (id),
  status             VARCHAR(12)  NOT NULL DEFAULT 'submitted' CHECK (status IN ('submitted', 'rejected')),
  receiver_name      VARCHAR(160) NOT NULL,
  receiver_position  VARCHAR(160) NOT NULL,
  receiver_phone     VARCHAR(60)  NOT NULL,
  receiver_email     VARCHAR(200) NOT NULL DEFAULT '',
  receiver_id_number VARCHAR(40)  NOT NULL DEFAULT '',
  courier_name       VARCHAR(160) NOT NULL DEFAULT '',
  courier_phone      VARCHAR(60)  NOT NULL DEFAULT '',
  received_condition VARCHAR(10)  NOT NULL DEFAULT 'good' CHECK (received_condition IN ('good', 'damaged', 'partial')),
  condition_note     VARCHAR(1000) NOT NULL DEFAULT '',
  signature_key      VARCHAR(500) NOT NULL,
  signature_sha256   VARCHAR(64)  NOT NULL,
  latitude           DOUBLE PRECISION CHECK (latitude BETWEEN -90 AND 90),
  longitude          DOUBLE PRECISION CHECK (longitude BETWEEN -180 AND 180),
  accuracy_m         DOUBLE PRECISION CHECK (accuracy_m >= 0),
  location_status    VARCHAR(12)  NOT NULL CHECK (location_status IN ('captured', 'unavailable')),
  location_note      VARCHAR(240) NOT NULL DEFAULT '',
  device_time        VARCHAR(40)  NOT NULL DEFAULT '',
  server_time        TIMESTAMPTZ  NOT NULL DEFAULT now(),
  ip                 VARCHAR(64)  NOT NULL DEFAULT '',
  user_agent         VARCHAR(300) NOT NULL DEFAULT '',
  rejected_at        TIMESTAMPTZ,
  rejected_by        INTEGER REFERENCES users (id),
  reject_reason      VARCHAR(500) NOT NULL DEFAULT '',
  CHECK (location_status <> 'captured' OR (latitude IS NOT NULL AND longitude IS NOT NULL))
);
-- Who delivered (a database that already had the table without them gets them here).
ALTER TABLE delivery_proofs ADD COLUMN IF NOT EXISTS courier_name VARCHAR(160) NOT NULL DEFAULT '';
ALTER TABLE delivery_proofs ADD COLUMN IF NOT EXISTS courier_phone VARCHAR(60) NOT NULL DEFAULT '';
CREATE UNIQUE INDEX IF NOT EXISTS ux_delivery_proofs_live ON delivery_proofs (delivery_id) WHERE status = 'submitted';
CREATE INDEX IF NOT EXISTS ix_delivery_proofs_delivery ON delivery_proofs (delivery_id, id);

CREATE TABLE IF NOT EXISTS delivery_proof_photos (
  id          SERIAL PRIMARY KEY,
  proof_id    INTEGER      NOT NULL REFERENCES delivery_proofs (id),
  position    INTEGER      NOT NULL DEFAULT 0,
  storage_key VARCHAR(500) NOT NULL,
  sha256      VARCHAR(64)  NOT NULL
);
CREATE INDEX IF NOT EXISTS ix_delivery_proof_photos_proof ON delivery_proof_photos (proof_id, position);

DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['deliveries', 'delivery_items', 'delivery_proofs', 'delivery_proof_photos'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN
      EXECUTE format('REVOKE ALL ON TABLE %I FROM anon', t);
      EXECUTE format('REVOKE ALL ON SEQUENCE %I FROM anon', t || '_id_seq');
    END IF;
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN
      EXECUTE format('REVOKE ALL ON TABLE %I FROM authenticated', t);
      EXECUTE format('REVOKE ALL ON SEQUENCE %I FROM authenticated', t || '_id_seq');
    END IF;
  END LOOP;
END $$;

-- The two emails: to the consignee (with the link to the POD) and to the VORA admin. Both start switched off like every notification.
INSERT INTO email_templates (key, subject, html) VALUES
  ('delivery_received_customer', $vora$VORA delivery $delivery_number received$vora$, $vora$<p>Dear $consignee_name,</p><p>Your shipment <strong>$delivery_number</strong> has been delivered and received by <strong>$receiver_name</strong> on $received_at.</p><p>The proof of delivery, with the signature, photos, location (when shared) and time of receipt, is available here: <a href="$pod_url">View the proof of delivery</a>.</p><p>VORA | Freight & Logistics</p>$vora$),
  ('delivery_received_admin', $vora$VORA delivery $delivery_number received$vora$, $vora$<p>Delivery <strong>$delivery_number</strong> to $consignee_name was received by $receiver_name on $received_at.</p><p>Open in admin: <a href="$admin_url">$delivery_number</a></p>$vora$)
ON CONFLICT (key) DO NOTHING;
INSERT INTO email_rules (key, enabled) VALUES
  ('delivery_received_customer', FALSE),
  ('delivery_received_admin', FALSE)
ON CONFLICT (key) DO NOTHING;

-- ---------------------------------------------------------------------------------------------------------------------------------
-- Functions. The application checks and prepares every value; these functions repeat the checks that matter under a row lock and write
-- the change, its items and its audit row in one transaction. A refusal is a SQLSTATE VRnnn (see vr_fail in migration 0024).
-- ---------------------------------------------------------------------------------------------------------------------------------

-- p: customer_id, consignee_*, origin, destination, shipment_reference, po_number, carrier, vehicle, vehicle_plate, driver_name, driver_phone,
--    delivery_date, notes, capture_token, view_token, items [{description, quantity, unit, remarks}]
CREATE OR REPLACE FUNCTION delivery_create(p_actor integer, p jsonb) RETURNS integer
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_customer integer := nullif(p->>'customer_id', '')::integer; v_owner text; v_number text; v_id integer;
BEGIN
  IF jsonb_typeof(p->'items') IS DISTINCT FROM 'array' OR jsonb_array_length(p->'items') = 0 THEN PERFORM vr_fail(422, 'Add at least one item'); END IF;
  IF v_customer IS NOT NULL THEN
    PERFORM 1 FROM customers WHERE id = v_customer;
    IF NOT FOUND THEN PERFORM vr_fail(422, 'Select an existing customer'); END IF;
    v_owner := vr_public_code('customers', v_customer);
  ELSE
    v_owner := vr_company_code();
  END IF;
  v_number := vr_next_number('DLV', v_owner, p->>'delivery_date');
  INSERT INTO deliveries (number, status, customer_id, consignee_name, consignee_address, consignee_contact, consignee_phone, consignee_email, origin, destination,
      shipment_reference, po_number, carrier, vehicle, vehicle_plate, driver_name, driver_phone, delivery_date, notes, capture_token, view_token, created_by)
    VALUES (v_number, 'draft', v_customer, p->>'consignee_name', p->>'consignee_address', p->>'consignee_contact', p->>'consignee_phone', p->>'consignee_email', p->>'origin', p->>'destination',
      p->>'shipment_reference', p->>'po_number', p->>'carrier', p->>'vehicle', p->>'vehicle_plate', p->>'driver_name', p->>'driver_phone', p->>'delivery_date', p->>'notes',
      p->>'capture_token', p->>'view_token', p_actor)
    RETURNING id INTO v_id;
  INSERT INTO delivery_items (delivery_id, position, description, quantity, unit, remarks)
    SELECT v_id, (t.ord - 1)::integer, t.x->>'description', t.x->>'quantity', t.x->>'unit', t.x->>'remarks' FROM jsonb_array_elements(p->'items') WITH ORDINALITY AS t(x, ord);
  PERFORM vr_audit(p_actor, 'create', 'delivery', v_id, v_number);
  RETURN v_id;
END
$fn$;

-- Only a draft can be edited: once issued, the note is on its way with a printed QR code. p as for delivery_create, without the tokens.
CREATE OR REPLACE FUNCTION delivery_update(p_actor integer, p_id integer, p jsonb) RETURNS void
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_d deliveries%ROWTYPE; v_customer integer := nullif(p->>'customer_id', '')::integer;
BEGIN
  SELECT * INTO v_d FROM deliveries WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN PERFORM vr_fail(404, 'Delivery note not found'); END IF;
  IF v_d.status <> 'draft' THEN PERFORM vr_fail(409, 'Only a draft can be edited: void this delivery note and write a new one'); END IF;
  IF jsonb_typeof(p->'items') IS DISTINCT FROM 'array' OR jsonb_array_length(p->'items') = 0 THEN PERFORM vr_fail(422, 'Add at least one item'); END IF;
  IF v_customer IS NOT NULL THEN
    PERFORM 1 FROM customers WHERE id = v_customer;
    IF NOT FOUND THEN PERFORM vr_fail(422, 'Select an existing customer'); END IF;
  END IF;
  UPDATE deliveries SET customer_id = v_customer, consignee_name = p->>'consignee_name', consignee_address = p->>'consignee_address', consignee_contact = p->>'consignee_contact',
      consignee_phone = p->>'consignee_phone', consignee_email = p->>'consignee_email', origin = p->>'origin', destination = p->>'destination', shipment_reference = p->>'shipment_reference',
      po_number = p->>'po_number', carrier = p->>'carrier', vehicle = p->>'vehicle', vehicle_plate = p->>'vehicle_plate', driver_name = p->>'driver_name', driver_phone = p->>'driver_phone',
      delivery_date = p->>'delivery_date', notes = p->>'notes', updated_at = now()
    WHERE id = p_id;
  DELETE FROM delivery_items WHERE delivery_id = p_id;
  INSERT INTO delivery_items (delivery_id, position, description, quantity, unit, remarks)
    SELECT p_id, (t.ord - 1)::integer, t.x->>'description', t.x->>'quantity', t.x->>'unit', t.x->>'remarks' FROM jsonb_array_elements(p->'items') WITH ORDINALITY AS t(x, ord);
  PERFORM vr_audit(p_actor, 'update', 'delivery', p_id, v_d.number);
END
$fn$;

-- issue: draft -> issued (its QR code starts to work). void: a draft or issued note (its QR code stops).
-- A received one needs its POD rejected first.
CREATE OR REPLACE FUNCTION delivery_set_status(p_actor integer, p_id integer, p_action text) RETURNS void
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_d deliveries%ROWTYPE;
BEGIN
  SELECT * INTO v_d FROM deliveries WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN PERFORM vr_fail(404, 'Delivery note not found'); END IF;
  IF p_action = 'issue' AND v_d.status = 'draft' THEN
    UPDATE deliveries SET status = 'issued', issued_at = now(), updated_at = now() WHERE id = p_id;
  ELSIF p_action = 'void' AND v_d.status IN ('draft', 'issued') THEN
    UPDATE deliveries SET status = 'void', updated_at = now() WHERE id = p_id;
  ELSIF p_action = 'void' AND v_d.status = 'delivered' THEN
    PERFORM vr_fail(409, 'The goods were received: reject the proof of delivery first if it was recorded by mistake');
  ELSE
    PERFORM vr_fail(409, 'Invalid state change');
  END IF;
  PERFORM vr_audit(p_actor, p_action, 'delivery', p_id, v_d.number);
END
$fn$;

-- The recorded POD was wrong (wrong person, wrong goods): it stays as history and the same QR code can be used again.
CREATE OR REPLACE FUNCTION delivery_reject_proof(p_actor integer, p_id integer, p_reason text) RETURNS void
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_d deliveries%ROWTYPE;
BEGIN
  SELECT * INTO v_d FROM deliveries WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN PERFORM vr_fail(404, 'Delivery note not found'); END IF;
  IF v_d.status <> 'delivered' THEN PERFORM vr_fail(409, 'This delivery has no recorded proof of delivery'); END IF;
  UPDATE delivery_proofs SET status = 'rejected', rejected_at = now(), rejected_by = p_actor, reject_reason = p_reason WHERE delivery_id = p_id AND status = 'submitted';
  UPDATE deliveries SET status = 'issued', delivered_at = NULL, updated_at = now() WHERE id = p_id;
  PERFORM vr_audit(p_actor, 'reject-proof', 'delivery', p_id, v_d.number || ': ' || p_reason);
END
$fn$;

-- The driver's submission (the receiver's details and signature included), after its evidence files were stored under the keys in p. The delivery is found by the QR code's token and
-- locked, so two phones sending at once record one proof; the second is told the receipt is already recorded (and the application removes
-- the files it had stored). p: token, courier_name, courier_phone, receiver_name, receiver_position, receiver_phone, receiver_email, receiver_id_number, condition,
-- condition_note, signature_key, signature_sha256, photos [{key, sha256}], location_status, latitude, longitude, accuracy_m, location_note,
-- device_time, ip, user_agent.
CREATE OR REPLACE FUNCTION delivery_submit_proof(p jsonb) RETURNS jsonb
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_d deliveries%ROWTYPE; v_proof_id integer; v_time timestamptz;
BEGIN
  SELECT * INTO v_d FROM deliveries WHERE capture_token = p->>'token' FOR UPDATE;
  IF NOT FOUND THEN PERFORM vr_fail(404, 'This delivery link is not valid'); END IF;
  IF v_d.status = 'delivered' THEN PERFORM vr_fail(409, 'The receipt of this delivery has already been recorded'); END IF;
  IF v_d.status = 'draft' THEN PERFORM vr_fail(409, 'This delivery note has not been issued yet'); END IF;
  IF v_d.status <> 'issued' THEN PERFORM vr_fail(409, 'This delivery note was cancelled'); END IF;
  IF jsonb_typeof(p->'photos') IS DISTINCT FROM 'array' OR jsonb_array_length(p->'photos') = 0 THEN PERFORM vr_fail(422, 'Take at least one photo of the goods'); END IF;
  IF p->>'location_status' IS DISTINCT FROM 'captured' OR nullif(p->>'latitude', '') IS NULL OR nullif(p->>'longitude', '') IS NULL THEN
    PERFORM vr_fail(422, 'Turn on the location of your phone: the delivery cannot be recorded without it');
  END IF;
  INSERT INTO delivery_proofs (delivery_id, status, receiver_name, receiver_position, receiver_phone, receiver_email, receiver_id_number, courier_name, courier_phone, received_condition, condition_note,
      signature_key, signature_sha256, latitude, longitude, accuracy_m, location_status, location_note, device_time, ip, user_agent)
    VALUES (v_d.id, 'submitted', p->>'receiver_name', p->>'receiver_position', p->>'receiver_phone', p->>'receiver_email', p->>'receiver_id_number', p->>'courier_name', p->>'courier_phone', p->>'condition', p->>'condition_note',
      p->>'signature_key', p->>'signature_sha256', nullif(p->>'latitude', '')::double precision, nullif(p->>'longitude', '')::double precision, nullif(p->>'accuracy_m', '')::double precision,
      p->>'location_status', p->>'location_note', p->>'device_time', p->>'ip', p->>'user_agent')
    RETURNING id, server_time INTO v_proof_id, v_time;
  INSERT INTO delivery_proof_photos (proof_id, position, storage_key, sha256)
    SELECT v_proof_id, (t.ord - 1)::integer, t.x->>'key', t.x->>'sha256' FROM jsonb_array_elements(p->'photos') WITH ORDINALITY AS t(x, ord);
  UPDATE deliveries SET status = 'delivered', delivered_at = v_time, updated_at = now() WHERE id = v_d.id;
  PERFORM vr_audit(NULL, 'receive', 'delivery', v_d.id, v_d.number || ': received by ' || (p->>'receiver_name'));
  RETURN jsonb_build_object('proof_id', v_proof_id, 'server_time', v_time, 'delivery_id', v_d.id, 'number', v_d.number, 'consignee_name', v_d.consignee_name,
                            'consignee_email', v_d.consignee_email, 'view_token', v_d.view_token);
END
$fn$;

-- Closed to everyone but the server's secret key (service_role).
DO $$
DECLARE f record;
BEGIN
  FOR f IN SELECT p.oid::regprocedure AS sig FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
           WHERE n.nspname = 'public' AND p.proname IN ('delivery_create', 'delivery_update', 'delivery_set_status', 'delivery_reject_proof', 'delivery_submit_proof')
  LOOP
    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC', f.sig);
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN EXECUTE format('REVOKE ALL ON FUNCTION %s FROM anon', f.sig); END IF;
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN EXECUTE format('REVOKE ALL ON FUNCTION %s FROM authenticated', f.sig); END IF;
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'service_role') THEN EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role', f.sig); END IF;
  END LOOP;
END $$;

-- ---------------------------------------------------------------------------
-- 0026_commercial_workflow.sql
-- ---------------------------------------------------------------------------
-- Phase 3A: one commercial workflow with two entry points.
--
--   Path A:  Lead -> Customer -> Quotation -> Customer approval -> VORA validation -> Delivery notes (POD) -> Invoice + pre-payment receipt -> Payment -> Receipt
--   Path B:  Customer ------------------^ (no lead at all)
--
-- The CUSTOMER is the commercial entity; the lead is an optional source of business. A new quotation requires a customer and never a lead
-- (quotations.customer_id / quotations.lead_id are both nullable columns so that the historical lead-only quotations stay as they are, but the
-- function that creates a quotation now insists on the customer). A new delivery note is tied to a customer and to one of that customer's
-- VALIDATED quotations; a new invoice is tied to a customer, a validated quotation and the delivery notes it bills (invoice_delivery_notes).
--
-- Forward-only and safe to run again: every column, table and index is IF NOT EXISTS, every function is CREATE OR REPLACE, the template updates only touch a
-- template the owner has not edited (they compare with the previous default), and the status backfill only maps records that carry approval evidence.

-- ---------------------------------------------------------------------------------------------------------------------------------
-- Customers: the primary contact person (PIC). `customers.phone` (already there) is the company's general number.
-- ---------------------------------------------------------------------------------------------------------------------------------
ALTER TABLE customers ADD COLUMN IF NOT EXISTS pic_name     VARCHAR(160) NOT NULL DEFAULT '';
ALTER TABLE customers ADD COLUMN IF NOT EXISTS pic_position VARCHAR(160) NOT NULL DEFAULT '';
ALTER TABLE customers ADD COLUMN IF NOT EXISTS pic_email    VARCHAR(200) NOT NULL DEFAULT '';
ALTER TABLE customers ADD COLUMN IF NOT EXISTS pic_phone    VARCHAR(60)  NOT NULL DEFAULT '';
CREATE INDEX IF NOT EXISTS ix_customers_name_lower ON customers (lower(name));
CREATE INDEX IF NOT EXISTS ix_customers_email_lower ON customers (lower(email));

-- ---------------------------------------------------------------------------------------------------------------------------------
-- Leads: the customer a lead became (kept: the lead itself is never rewritten or deleted).
-- ---------------------------------------------------------------------------------------------------------------------------------
ALTER TABLE leads ADD COLUMN IF NOT EXISTS customer_id  INTEGER REFERENCES customers (id);
ALTER TABLE leads ADD COLUMN IF NOT EXISTS converted_at TIMESTAMPTZ;
ALTER TABLE leads ADD COLUMN IF NOT EXISTS converted_by INTEGER REFERENCES users (id);
CREATE INDEX IF NOT EXISTS ix_leads_customer ON leads (customer_id);

-- ---------------------------------------------------------------------------------------------------------------------------------
-- Quotations: who at the customer, what is being quoted, and the two separate milestones after the customer signs.
--   status: draft -> issued -> awaiting_approval -> customer_approved (the customer uploaded the signed PDF)
--           -> validated (VORA checked it) | rejected (needs correction; the approval can be requested again) | void.  Expiry is read from valid_until.
-- ---------------------------------------------------------------------------------------------------------------------------------
ALTER TABLE quotations ADD COLUMN IF NOT EXISTS pic_name             VARCHAR(160) NOT NULL DEFAULT '';
ALTER TABLE quotations ADD COLUMN IF NOT EXISTS pic_email            VARCHAR(200) NOT NULL DEFAULT '';
ALTER TABLE quotations ADD COLUMN IF NOT EXISTS pic_phone            VARCHAR(60)  NOT NULL DEFAULT '';
ALTER TABLE quotations ADD COLUMN IF NOT EXISTS service_mode         VARCHAR(120) NOT NULL DEFAULT '';
ALTER TABLE quotations ADD COLUMN IF NOT EXISTS origin               VARCHAR(240) NOT NULL DEFAULT '';
ALTER TABLE quotations ADD COLUMN IF NOT EXISTS destination          VARCHAR(240) NOT NULL DEFAULT '';
ALTER TABLE quotations ADD COLUMN IF NOT EXISTS cargo_info           TEXT         NOT NULL DEFAULT '';
ALTER TABLE quotations ADD COLUMN IF NOT EXISTS customer_approved_at TIMESTAMPTZ;
ALTER TABLE quotations ADD COLUMN IF NOT EXISTS validated_at         TIMESTAMPTZ;
ALTER TABLE quotations ADD COLUMN IF NOT EXISTS validated_by         INTEGER REFERENCES users (id);
-- Until now a quotation had EITHER a customer OR a lead (quote_one_recipient). It now has a customer and, when the business came from a lead, that lead too; a historical
-- quotation with a lead alone stays valid. The new rule only asks for a recipient; the function that creates a quotation insists on the customer.
ALTER TABLE quotations DROP CONSTRAINT IF EXISTS quote_one_recipient;
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'quote_has_recipient' AND conrelid = 'quotations'::regclass) THEN
    ALTER TABLE quotations ADD CONSTRAINT quote_has_recipient CHECK (customer_id IS NOT NULL OR lead_id IS NOT NULL);
  END IF;
END $$;
CREATE INDEX IF NOT EXISTS ix_quotations_customer ON quotations (customer_id, status);
CREATE INDEX IF NOT EXISTS ix_quotations_lead ON quotations (lead_id);

-- The old single 'approved' state meant "Finance reviewed the customer's signed PDF". That is today's 'validated' - but only for a record that
-- really has that evidence (a reviewed approval with a stored PDF and its fingerprint). Any other 'approved' quotation is left exactly as it is.
UPDATE quotations q
   SET status = 'validated', customer_approved_at = coalesce(q.customer_approved_at, a.uploaded_at), validated_at = coalesce(q.validated_at, a.reviewed_at),
       validated_by = coalesce(q.validated_by, a.reviewed_by)
  FROM (SELECT DISTINCT ON (quotation_id) * FROM quotation_approvals WHERE status = 'approved' AND signed_pdf_key IS NOT NULL AND signed_pdf_sha256 IS NOT NULL AND reviewed_at IS NOT NULL
         ORDER BY quotation_id, reviewed_at DESC) a
 WHERE a.quotation_id = q.id AND q.status = 'approved';

-- ---------------------------------------------------------------------------------------------------------------------------------
-- Delivery notes and invoices point at the quotation they come from; an invoice bills delivery notes through a junction table.
-- (Historical rows keep a NULL quotation_id: no relationship is invented for them.)
-- ---------------------------------------------------------------------------------------------------------------------------------
ALTER TABLE deliveries ADD COLUMN IF NOT EXISTS quotation_id INTEGER REFERENCES quotations (id);
CREATE INDEX IF NOT EXISTS ix_deliveries_quotation ON deliveries (quotation_id);
ALTER TABLE invoices ADD COLUMN IF NOT EXISTS quotation_id INTEGER REFERENCES quotations (id);
CREATE INDEX IF NOT EXISTS ix_invoices_quotation ON invoices (quotation_id);
CREATE INDEX IF NOT EXISTS ix_invoices_customer ON invoices (customer_id);

-- One live (not released) billing per delivery note: a delivery note can be on only one open invoice. A voided invoice releases its delivery
-- notes (released_at), and the row stays as history.
CREATE TABLE IF NOT EXISTS invoice_delivery_notes (
  id          SERIAL PRIMARY KEY,
  invoice_id  INTEGER     NOT NULL REFERENCES invoices (id),
  delivery_id INTEGER     NOT NULL REFERENCES deliveries (id),
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  released_at TIMESTAMPTZ
);
CREATE UNIQUE INDEX IF NOT EXISTS ux_invoice_delivery_live ON invoice_delivery_notes (delivery_id) WHERE released_at IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS ux_invoice_delivery_pair ON invoice_delivery_notes (invoice_id, delivery_id);
CREATE INDEX IF NOT EXISTS ix_invoice_delivery_invoice ON invoice_delivery_notes (invoice_id);

-- ---------------------------------------------------------------------------------------------------------------------------------
-- E-mail with more than one attachment (the invoice and its pre-payment receipt travel in ONE message).
-- email_jobs.attachment_kind/attachment_id stay for the single-attachment messages.
-- ---------------------------------------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS email_job_attachments (
  id          SERIAL PRIMARY KEY,
  job_id      INTEGER     NOT NULL REFERENCES email_jobs (id),
  position    INTEGER     NOT NULL DEFAULT 0,
  kind        VARCHAR(20) NOT NULL CHECK (kind IN ('invoice', 'receipt', 'quotation', 'prepayment')),
  document_id INTEGER     NOT NULL
);
CREATE INDEX IF NOT EXISTS ix_email_job_attachments_job ON email_job_attachments (job_id, position);

DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['invoice_delivery_notes', 'email_job_attachments'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN
      EXECUTE format('REVOKE ALL ON TABLE %I FROM anon', t);
      EXECUTE format('REVOKE ALL ON SEQUENCE %I FROM anon', t || '_id_seq');
    END IF;
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN
      EXECUTE format('REVOKE ALL ON TABLE %I FROM authenticated', t);
      EXECUTE format('REVOKE ALL ON SEQUENCE %I FROM authenticated', t || '_id_seq');
    END IF;
  END LOOP;
END $$;

-- ---------------------------------------------------------------------------------------------------------------------------------
-- Functions. Business refusals are SQLSTATE VRnnn (vr_fail, migration 0024). Everything stays SECURITY INVOKER, with a pinned search_path.
-- ---------------------------------------------------------------------------------------------------------------------------------

-- p: name, email, phone, address, tax_id, currency, terms_days, pic_name, pic_position, pic_email, pic_phone
CREATE OR REPLACE FUNCTION customer_save(p_actor integer, p_id integer, p jsonb) RETURNS integer
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_id integer := p_id; v_currency text; v_used bigint;
BEGIN
  IF p_id IS NOT NULL THEN
    SELECT currency INTO v_currency FROM customers WHERE id = p_id FOR UPDATE;
    IF NOT FOUND THEN PERFORM vr_fail(404, 'Customer not found'); END IF;
    IF v_currency <> p->>'currency' THEN
      SELECT (SELECT count(*) FROM invoices WHERE customer_id = p_id) + (SELECT count(*) FROM quotations WHERE customer_id = p_id) INTO v_used;
      IF v_used > 0 THEN PERFORM vr_fail(409, 'Currency cannot change on a customer that already has quotations or invoices'); END IF;
    END IF;
    UPDATE customers SET name = p->>'name', email = p->>'email', phone = coalesce(p->>'phone', ''), address = p->>'address', tax_id = p->>'tax_id', currency = p->>'currency',
           terms_days = (p->>'terms_days')::integer, pic_name = coalesce(p->>'pic_name', ''), pic_position = coalesce(p->>'pic_position', ''),
           pic_email = coalesce(p->>'pic_email', ''), pic_phone = coalesce(p->>'pic_phone', '')
     WHERE id = p_id;
  ELSE
    INSERT INTO customers (name, email, phone, address, tax_id, currency, terms_days, pic_name, pic_position, pic_email, pic_phone)
      VALUES (p->>'name', p->>'email', coalesce(p->>'phone', ''), p->>'address', p->>'tax_id', p->>'currency', (p->>'terms_days')::integer,
              coalesce(p->>'pic_name', ''), coalesce(p->>'pic_position', ''), coalesce(p->>'pic_email', ''), coalesce(p->>'pic_phone', '')) RETURNING id INTO v_id;
  END IF;
  PERFORM vr_public_code('customers', v_id);
  PERFORM vr_audit(p_actor, 'upsert', 'customer', v_id, p->>'name');
  RETURN v_id;
END
$fn$;

-- The public form's phone / WhatsApp number is stored too.
CREATE OR REPLACE FUNCTION lead_create(p jsonb) RETURNS jsonb
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_rfq boolean := p->>'kind' = 'rfq'; v_id integer; v_ref text; v_recent integer;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('lead-' || lower(p->>'email')));
  SELECT count(*) INTO v_recent FROM leads WHERE email = p->>'email' AND created_at >= now() - make_interval(mins => (p->>'window_minutes')::integer);
  IF v_recent >= (p->>'max_per_email')::integer THEN PERFORM vr_fail(429, 'Too many submissions; try again later'); END IF;
  INSERT INTO leads (type, name, email, phone, message, company, mode, origin, destination, cargo, pickup, source)
    VALUES (CASE WHEN v_rfq THEN 'RFQ' ELSE 'contact' END, p->>'name', p->>'email', coalesce(p->>'phone', ''), p->>'message', p->>'company',
            CASE WHEN v_rfq THEN p->>'mode' ELSE '' END, CASE WHEN v_rfq THEN p->>'origin' ELSE '' END, CASE WHEN v_rfq THEN p->>'destination' ELSE '' END,
            CASE WHEN v_rfq THEN p->>'cargo' ELSE '' END, CASE WHEN v_rfq THEN p->>'pickup' ELSE '' END, 'website') RETURNING id INTO v_id;
  v_ref := vr_next_number(CASE WHEN v_rfq THEN 'RFQ' ELSE 'INQ' END, vr_public_code('leads', v_id));
  UPDATE leads SET reference = v_ref WHERE id = v_id;
  RETURN jsonb_build_object('id', v_id, 'reference', v_ref);
END
$fn$;

-- A lead becomes (or is linked to) a customer. The lead is kept as it is; the link and who made it are recorded; a lead converts once.
-- p: customer_id (link this existing customer) OR customer {customer_save fields} (create one).
CREATE OR REPLACE FUNCTION lead_convert(p_actor integer, p_lead integer, p jsonb) RETURNS jsonb
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_lead leads%ROWTYPE; v_customer integer := nullif(p->>'customer_id', '')::integer; v_created boolean := FALSE; v_name text;
BEGIN
  SELECT * INTO v_lead FROM leads WHERE id = p_lead FOR UPDATE;
  IF NOT FOUND THEN PERFORM vr_fail(404, 'Lead not found'); END IF;
  IF v_lead.customer_id IS NOT NULL THEN PERFORM vr_fail(409, 'This lead was already converted to a customer'); END IF;
  IF v_customer IS NOT NULL THEN
    SELECT name INTO v_name FROM customers WHERE id = v_customer;
    IF NOT FOUND THEN PERFORM vr_fail(422, 'Select an existing customer'); END IF;
  ELSE
    IF jsonb_typeof(p->'customer') IS DISTINCT FROM 'object' THEN PERFORM vr_fail(422, 'Give the customer''s details or choose an existing customer'); END IF;
    v_customer := customer_save(p_actor, NULL, p->'customer');
    v_created := TRUE;
    v_name := p->'customer'->>'name';
  END IF;
  UPDATE leads SET customer_id = v_customer, converted_at = now(), converted_by = p_actor, updated_at = now() WHERE id = p_lead;
  INSERT INTO lead_activities (lead_id, actor_id, message)
    VALUES (p_lead, p_actor, CASE WHEN v_created THEN 'Saved as a new customer: ' ELSE 'Linked to the existing customer: ' END || v_name);
  PERFORM vr_audit(p_actor, 'convert', 'lead', p_lead, CASE WHEN v_created THEN 'New customer ' ELSE 'Existing customer ' END || v_name);
  RETURN jsonb_build_object('customer_id', v_customer, 'created', v_created);
END
$fn$;

-- p: customer_id (REQUIRED), lead_id (optional, the lead that brought the business), currency, issued_at, valid_until, payment_terms, terms_conditions,
--    notes, tax_percent, subtotal_minor, tax_minor, total_minor, pic_name, pic_email, pic_phone, service_mode, origin, destination, cargo_info,
--    items[{description, unit, quantity, price_minor, amount_minor}]
-- A quotation is numbered under the customer's permanent code. A lead is linked, never required, and never created here.
CREATE OR REPLACE FUNCTION quotation_create(p_actor integer, p jsonb) RETURNS integer
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE
  v_customer integer := nullif(p->>'customer_id', '')::integer; v_lead integer := nullif(p->>'lead_id', '')::integer; v_currency text; v_number text; v_id integer; v_item jsonb;
  v_lead_customer integer; v_name text;
BEGIN
  IF v_customer IS NULL THEN PERFORM vr_fail(422, 'Select the customer this quotation is for'); END IF;
  SELECT currency, name INTO v_currency, v_name FROM customers WHERE id = v_customer;
  IF NOT FOUND THEN PERFORM vr_fail(422, 'Select an existing customer'); END IF;
  IF v_currency <> p->>'currency' THEN PERFORM vr_fail(409, 'The customer''s currency changed while the quotation was being prepared: try again'); END IF;
  IF jsonb_typeof(p->'items') IS DISTINCT FROM 'array' OR jsonb_array_length(p->'items') = 0 THEN PERFORM vr_fail(422, 'Add at least one charge item'); END IF;
  IF v_lead IS NOT NULL THEN
    SELECT customer_id INTO v_lead_customer FROM leads WHERE id = v_lead FOR UPDATE;
    IF NOT FOUND THEN PERFORM vr_fail(422, 'The lead does not exist'); END IF;
    IF v_lead_customer IS NOT NULL AND v_lead_customer <> v_customer THEN PERFORM vr_fail(409, 'This lead belongs to another customer'); END IF;
    IF v_lead_customer IS NULL THEN
      UPDATE leads SET customer_id = v_customer, converted_at = now(), converted_by = p_actor, updated_at = now() WHERE id = v_lead;
      INSERT INTO lead_activities (lead_id, actor_id, message) VALUES (v_lead, p_actor, 'Linked to the customer ' || v_name || ' when a quotation was made');
    END IF;
  END IF;
  v_number := vr_next_number('QUO', vr_public_code('customers', v_customer), p->>'issued_at');
  INSERT INTO quotations (number, customer_id, lead_id, status, currency, issued_at, valid_until, payment_terms, terms_conditions, notes, tax_percent, subtotal_minor, tax_minor, total_minor,
                          pic_name, pic_email, pic_phone, service_mode, origin, destination, cargo_info)
    VALUES (v_number, v_customer, v_lead, 'draft', v_currency, p->>'issued_at', p->>'valid_until', p->>'payment_terms', p->>'terms_conditions', p->>'notes', p->>'tax_percent',
            (p->>'subtotal_minor')::bigint, (p->>'tax_minor')::bigint, (p->>'total_minor')::bigint,
            coalesce(p->>'pic_name', ''), coalesce(p->>'pic_email', ''), coalesce(p->>'pic_phone', ''), coalesce(p->>'service_mode', ''), coalesce(p->>'origin', ''),
            coalesce(p->>'destination', ''), coalesce(p->>'cargo_info', '')) RETURNING id INTO v_id;
  FOR v_item IN SELECT * FROM jsonb_array_elements(p->'items') LOOP
    INSERT INTO quotation_items (quotation_id, description, unit, quantity, price_minor, amount_minor)
      VALUES (v_id, v_item->>'description', v_item->>'unit', v_item->>'quantity', (v_item->>'price_minor')::bigint, (v_item->>'amount_minor')::bigint);
  END LOOP;
  PERFORM vr_create_verification('quotation', v_id);
  PERFORM vr_audit(p_actor, 'create', 'quotation', v_id, v_number);
  RETURN v_id;
END
$fn$;

-- issue: draft -> issued.  void: any state that is not void; a validated quotation only while no delivery note or invoice that is not void was made from it.
CREATE OR REPLACE FUNCTION quotation_set_status(p_actor integer, p_id integer, p_action text) RETURNS void
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_q quotations%ROWTYPE;
BEGIN
  SELECT * INTO v_q FROM quotations WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN PERFORM vr_fail(404, 'Quotation not found'); END IF;
  IF p_action = 'issue' AND v_q.status = 'draft' THEN
    UPDATE quotations SET status = 'issued' WHERE id = p_id;
  ELSIF p_action = 'void' AND v_q.status IN ('draft', 'issued', 'awaiting_approval', 'customer_approved', 'rejected', 'validated', 'approved') THEN
    IF EXISTS (SELECT 1 FROM deliveries WHERE quotation_id = p_id AND status <> 'void') OR EXISTS (SELECT 1 FROM invoices WHERE quotation_id = p_id AND status <> 'void') THEN
      PERFORM vr_fail(409, 'Delivery notes or invoices were made from this quotation: void them first');
    END IF;
    UPDATE quotations SET status = 'void' WHERE id = p_id;
    UPDATE quotation_approvals SET status = 'revoked' WHERE quotation_id = p_id AND status = 'pending';
    UPDATE document_verification_tokens SET revoked = TRUE WHERE kind = 'quotation' AND document_id = p_id;
  ELSE
    PERFORM vr_fail(409, 'Quotation cannot make that status transition');
  END IF;
  PERFORM vr_audit(p_actor, p_action, 'quotation', p_id, v_q.number);
END
$fn$;

-- A rejected quotation (it needs correction) can be sent again.
CREATE OR REPLACE FUNCTION quotation_request_approval(p_actor integer, p_id integer, p_approval integer, p_token_hash text, p_expires_at timestamptz) RETURNS jsonb
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_q quotations%ROWTYPE; v_token text;
BEGIN
  SELECT * INTO v_q FROM quotations WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN PERFORM vr_fail(404, 'Quotation not found'); END IF;
  IF v_q.status NOT IN ('issued', 'awaiting_approval', 'rejected') THEN PERFORM vr_fail(409, 'Issue the quotation before requesting customer approval'); END IF;
  IF v_q.valid_until < vr_today() THEN PERFORM vr_fail(409, 'Quotation validity has expired'); END IF;
  UPDATE quotation_approvals SET status = 'revoked' WHERE quotation_id = p_id AND status = 'pending';
  INSERT INTO quotation_approvals (id, quotation_id, token_hash, expires_at, status) VALUES (p_approval, p_id, p_token_hash, p_expires_at, 'pending');
  UPDATE quotations SET status = 'awaiting_approval' WHERE id = p_id;
  SELECT token INTO v_token FROM document_verification_tokens WHERE kind = 'quotation' AND document_id = p_id ORDER BY id LIMIT 1;
  PERFORM vr_audit(p_actor, 'send-approval-request', 'quotation', p_id, format('Customer approval link #%s expires %s', p_approval, to_char(p_expires_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
  RETURN jsonb_build_object('number', v_q.number, 'valid_until', v_q.valid_until, 'verification_token', coalesce(v_token, ''));
END
$fn$;

-- The customer's upload (already checked and stored by the application): the quotation becomes CUSTOMER APPROVED. That is not VORA's validation.
CREATE OR REPLACE FUNCTION approval_submit(p_token_hash text, p_key text, p_sha256 text, p_signer text, p_title text) RETURNS jsonb
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_item quotation_approvals%ROWTYPE; v_q quotations%ROWTYPE;
BEGIN
  SELECT * INTO v_item FROM quotation_approvals WHERE token_hash = p_token_hash FOR UPDATE;
  IF NOT FOUND THEN PERFORM vr_fail(404, 'This approval link is not valid'); END IF;
  SELECT * INTO v_q FROM quotations WHERE id = v_item.quotation_id FOR UPDATE;
  IF v_item.status <> 'pending' OR v_item.expires_at < now() OR NOT FOUND OR v_q.status <> 'awaiting_approval' THEN
    PERFORM vr_fail(410, 'This approval request has expired or was already used');
  END IF;
  UPDATE quotation_approvals SET signed_pdf_key = p_key, signed_pdf_sha256 = p_sha256, signer_name = p_signer, signer_title = p_title, uploaded_at = now(), status = 'submitted' WHERE id = v_item.id;
  UPDATE quotations SET status = 'customer_approved', customer_approved_at = now() WHERE id = v_q.id;
  PERFORM vr_audit(NULL, 'customer-approval-upload', 'quotation', v_item.quotation_id, format('Customer submission #%s by %s, %s, SHA256 %s', v_item.id, p_signer, p_title, p_sha256));
  RETURN jsonb_build_object('approval_id', v_item.id, 'quotation_id', v_item.quotation_id, 'number', v_q.number, 'signer_name', p_signer, 'signer_title', p_title,
                            'customer_id', v_q.customer_id);
END
$fn$;

-- VORA's decision on the uploaded file: validate (after looking at the signature and the company stamp by hand) or reject with a reason.
CREATE OR REPLACE FUNCTION approval_review(p_actor integer, p_id integer, p_outcome text, p_verified boolean, p_note text) RETURNS jsonb
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_item quotation_approvals%ROWTYPE; v_q quotations%ROWTYPE;
BEGIN
  IF p_outcome NOT IN ('approve', 'reject') THEN PERFORM vr_fail(422, 'Invalid review outcome'); END IF;
  SELECT * INTO v_item FROM quotation_approvals WHERE id = p_id FOR UPDATE;
  IF NOT FOUND OR v_item.status <> 'submitted' THEN PERFORM vr_fail(409, 'Only submitted approvals can be reviewed'); END IF;
  SELECT * INTO v_q FROM quotations WHERE id = v_item.quotation_id FOR UPDATE;
  IF NOT FOUND OR v_q.status <> 'customer_approved' THEN PERFORM vr_fail(409, 'The quotation is not waiting for validation'); END IF;
  IF p_outcome = 'approve' AND NOT coalesce(p_verified, FALSE) THEN PERFORM vr_fail(422, 'Confirm that the signature and company stamp were reviewed manually'); END IF;
  IF p_outcome = 'reject' AND length(btrim(coalesce(p_note, ''))) < 5 THEN PERFORM vr_fail(422, 'Give the reason the document is rejected (at least 5 characters)'); END IF;
  UPDATE quotation_approvals SET status = CASE WHEN p_outcome = 'approve' THEN 'approved' ELSE 'rejected' END, reviewed_by = p_actor, reviewed_at = now(), review_note = left(p_note, 2000) WHERE id = p_id;
  IF p_outcome = 'approve' THEN
    UPDATE quotations SET status = 'validated', validated_at = now(), validated_by = p_actor WHERE id = v_q.id;
  ELSE
    UPDATE quotations SET status = 'rejected' WHERE id = v_q.id;
  END IF;
  PERFORM vr_audit(p_actor, CASE WHEN p_outcome = 'approve' THEN 'validate-quotation' ELSE 'reject-quotation' END, 'quotation', v_q.id, format('Approval #%s; PDF checksum %s', p_id, v_item.signed_pdf_sha256));
  RETURN jsonb_build_object('quotation_id', v_q.id, 'number', v_q.number, 'customer_id', v_q.customer_id);
END
$fn$;

-- p: customer_id, quotation_id (both REQUIRED for a new note: a delivery is made for a customer's VALIDATED quotation), consignee_*, origin, ...
--    (as before), capture_token, view_token, items[{description, quantity, unit, remarks}]
CREATE OR REPLACE FUNCTION delivery_create(p_actor integer, p jsonb) RETURNS integer
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_customer integer := nullif(p->>'customer_id', '')::integer; v_quotation integer := nullif(p->>'quotation_id', '')::integer; v_q quotations%ROWTYPE; v_number text; v_id integer;
BEGIN
  IF v_customer IS NULL THEN PERFORM vr_fail(422, 'Select the customer'); END IF;
  PERFORM 1 FROM customers WHERE id = v_customer;
  IF NOT FOUND THEN PERFORM vr_fail(422, 'Select an existing customer'); END IF;
  IF v_quotation IS NULL THEN PERFORM vr_fail(422, 'Select one of the customer''s validated quotations'); END IF;
  SELECT * INTO v_q FROM quotations WHERE id = v_quotation FOR SHARE;
  IF NOT FOUND OR v_q.customer_id IS DISTINCT FROM v_customer THEN PERFORM vr_fail(422, 'The quotation does not belong to this customer'); END IF;
  IF v_q.status <> 'validated' THEN PERFORM vr_fail(409, 'Delivery notes can only be made for a validated quotation'); END IF;
  IF jsonb_typeof(p->'items') IS DISTINCT FROM 'array' OR jsonb_array_length(p->'items') = 0 THEN PERFORM vr_fail(422, 'Add at least one item'); END IF;
  v_number := vr_next_number('DLV', vr_public_code('customers', v_customer), p->>'delivery_date');
  INSERT INTO deliveries (number, status, customer_id, quotation_id, consignee_name, consignee_address, consignee_contact, consignee_phone, consignee_email, origin, destination,
      shipment_reference, po_number, carrier, vehicle, vehicle_plate, driver_name, driver_phone, delivery_date, notes, capture_token, view_token, created_by)
    VALUES (v_number, 'draft', v_customer, v_quotation, p->>'consignee_name', p->>'consignee_address', p->>'consignee_contact', p->>'consignee_phone', p->>'consignee_email', p->>'origin', p->>'destination',
      p->>'shipment_reference', p->>'po_number', p->>'carrier', p->>'vehicle', p->>'vehicle_plate', p->>'driver_name', p->>'driver_phone', p->>'delivery_date', p->>'notes',
      p->>'capture_token', p->>'view_token', p_actor)
    RETURNING id INTO v_id;
  INSERT INTO delivery_items (delivery_id, position, description, quantity, unit, remarks)
    SELECT v_id, (t.ord - 1)::integer, t.x->>'description', t.x->>'quantity', t.x->>'unit', t.x->>'remarks' FROM jsonb_array_elements(p->'items') WITH ORDINALITY AS t(x, ord);
  PERFORM vr_audit(p_actor, 'create', 'delivery', v_id, v_number || ' for quotation ' || v_q.number);
  RETURN v_id;
END
$fn$;

-- Only a draft can be edited. Its customer and quotation stay as they were made.
CREATE OR REPLACE FUNCTION delivery_update(p_actor integer, p_id integer, p jsonb) RETURNS void
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_d deliveries%ROWTYPE;
BEGIN
  SELECT * INTO v_d FROM deliveries WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN PERFORM vr_fail(404, 'Delivery note not found'); END IF;
  IF v_d.status <> 'draft' THEN PERFORM vr_fail(409, 'Only a draft can be edited: void this delivery note and write a new one'); END IF;
  IF jsonb_typeof(p->'items') IS DISTINCT FROM 'array' OR jsonb_array_length(p->'items') = 0 THEN PERFORM vr_fail(422, 'Add at least one item'); END IF;
  UPDATE deliveries SET consignee_name = p->>'consignee_name', consignee_address = p->>'consignee_address', consignee_contact = p->>'consignee_contact',
      consignee_phone = p->>'consignee_phone', consignee_email = p->>'consignee_email', origin = p->>'origin', destination = p->>'destination', shipment_reference = p->>'shipment_reference',
      po_number = p->>'po_number', carrier = p->>'carrier', vehicle = p->>'vehicle', vehicle_plate = p->>'vehicle_plate', driver_name = p->>'driver_name', driver_phone = p->>'driver_phone',
      delivery_date = p->>'delivery_date', notes = p->>'notes', updated_at = now()
    WHERE id = p_id;
  DELETE FROM delivery_items WHERE delivery_id = p_id;
  INSERT INTO delivery_items (delivery_id, position, description, quantity, unit, remarks)
    SELECT p_id, (t.ord - 1)::integer, t.x->>'description', t.x->>'quantity', t.x->>'unit', t.x->>'remarks' FROM jsonb_array_elements(p->'items') WITH ORDINALITY AS t(x, ord);
  PERFORM vr_audit(p_actor, 'update', 'delivery', p_id, v_d.number);
END
$fn$;

-- p: as before, plus quotation_id and delivery_ids[] (REQUIRED), over_quotation_ack (boolean).
-- The invoice is for one customer's VALIDATED quotation and bills delivery notes that have a proof of delivery, belong to that customer and that
-- quotation, and are not on another open invoice. The quotation row is locked first, so two invoices cannot both be checked against the same
-- balance; then the delivery notes are locked in a fixed order. The billed total of the quotation may not pass its quoted subtotal unless the
-- administrator acknowledged it.
CREATE OR REPLACE FUNCTION invoice_create(p_actor integer, p jsonb) RETURNS integer
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE
  v_cust customers%ROWTYPE; v_q quotations%ROWTYPE; v_quotation integer := nullif(p->>'quotation_id', '')::integer; v_dels integer[]; v_d deliveries%ROWTYPE; v_del_id integer;
  v_ids integer[]; v_bank bank_accounts%ROWTYPE; v_default integer; v_number text; v_id integer; v_bank_id integer; v_pos integer := 0; v_item jsonb; v_billed bigint;
BEGIN
  SELECT * INTO v_cust FROM customers WHERE id = (p->>'customer_id')::integer;
  IF NOT FOUND THEN PERFORM vr_fail(422, 'Select an existing customer'); END IF;
  IF v_cust.currency <> p->>'currency' THEN PERFORM vr_fail(409, 'The customer''s currency changed while the invoice was being prepared: try again'); END IF;
  IF v_quotation IS NULL THEN PERFORM vr_fail(422, 'Select one of the customer''s validated quotations'); END IF;
  SELECT * INTO v_q FROM quotations WHERE id = v_quotation FOR UPDATE;
  IF NOT FOUND OR v_q.customer_id IS DISTINCT FROM v_cust.id THEN PERFORM vr_fail(422, 'The quotation does not belong to this customer'); END IF;
  IF v_q.status <> 'validated' THEN PERFORM vr_fail(409, 'Only a validated quotation can be invoiced'); END IF;
  IF v_q.currency <> v_cust.currency THEN PERFORM vr_fail(409, 'The quotation and the invoice must be in the same currency'); END IF;

  SELECT coalesce(array_agg(DISTINCT t.value::integer ORDER BY t.value::integer), '{}') INTO v_dels FROM jsonb_array_elements_text(coalesce(p->'delivery_ids', '[]'::jsonb)) AS t(value);
  IF cardinality(v_dels) = 0 THEN PERFORM vr_fail(422, 'Select at least one delivery note to bill'); END IF;
  IF cardinality(v_dels) <> jsonb_array_length(p->'delivery_ids') THEN PERFORM vr_fail(422, 'A delivery note was selected twice'); END IF;
  FOREACH v_del_id IN ARRAY v_dels LOOP
    SELECT * INTO v_d FROM deliveries WHERE id = v_del_id FOR UPDATE;
    IF NOT FOUND THEN PERFORM vr_fail(422, 'A selected delivery note does not exist'); END IF;
    IF v_d.customer_id IS DISTINCT FROM v_cust.id THEN PERFORM vr_fail(422, 'Delivery note ' || v_d.number || ' belongs to another customer'); END IF;
    IF v_d.quotation_id IS DISTINCT FROM v_quotation THEN PERFORM vr_fail(422, 'Delivery note ' || v_d.number || ' belongs to another quotation'); END IF;
    IF v_d.status <> 'delivered' THEN PERFORM vr_fail(409, 'Delivery note ' || v_d.number || ' has no recorded proof of delivery yet'); END IF;
    IF EXISTS (SELECT 1 FROM invoice_delivery_notes WHERE delivery_id = v_del_id AND released_at IS NULL) THEN PERFORM vr_fail(409, 'Delivery note ' || v_d.number || ' is already billed on another invoice'); END IF;
  END LOOP;
  SELECT coalesce(sum(subtotal_minor), 0)::bigint INTO v_billed FROM invoices WHERE quotation_id = v_quotation AND status <> 'void';
  IF v_billed + (p->>'subtotal_minor')::bigint > v_q.subtotal_minor AND NOT coalesce((p->>'over_quotation_ack')::boolean, FALSE) THEN
    PERFORM vr_fail(409, format('The invoices for this quotation would total %s against %s quoted: check the amounts, or acknowledge that this is intended', v_billed + (p->>'subtotal_minor')::bigint, v_q.subtotal_minor));
  END IF;

  SELECT coalesce(array_agg(t.value::integer ORDER BY t.ord), '{}') INTO v_ids FROM jsonb_array_elements_text(coalesce(p->'bank_ids', '[]'::jsonb)) WITH ORDINALITY AS t(value, ord);
  IF cardinality(v_ids) = 0 THEN
    SELECT id INTO v_default FROM bank_accounts WHERE currency = v_cust.currency AND active AND is_default;
    IF FOUND THEN v_ids := ARRAY[v_default]; END IF;
  END IF;
  FOREACH v_bank_id IN ARRAY v_ids LOOP
    SELECT * INTO v_bank FROM bank_accounts WHERE id = v_bank_id;
    IF NOT FOUND OR NOT v_bank.active OR v_bank.currency <> v_cust.currency THEN PERFORM vr_fail(422, 'Only active bank accounts in the invoice currency can be selected'); END IF;
  END LOOP;

  v_number := vr_next_number('INV', vr_public_code('customers', v_cust.id), p->>'issued_at');
  INSERT INTO invoices (number, customer_id, quotation_id, status, currency, issued_at, due_at, po_number, shipment_reference, service_mode, origin, destination,
      transport_document_ref, notes, tax_percent, withholding_percent, discount_minor, subtotal_minor, tax_minor, withholding_minor, total_minor, outstanding_minor)
    VALUES (v_number, v_cust.id, v_quotation, 'draft', v_cust.currency, p->>'issued_at', p->>'due_at', p->>'po_number', p->>'shipment_reference', p->>'service_mode', p->>'origin', p->>'destination',
      p->>'transport_document_ref', p->>'notes', p->>'tax_percent', p->>'withholding_percent', (p->>'discount_minor')::bigint, (p->>'subtotal_minor')::bigint, (p->>'tax_minor')::bigint,
      (p->>'withholding_minor')::bigint, (p->>'total_minor')::bigint, (p->>'total_minor')::bigint) RETURNING id INTO v_id;
  FOREACH v_del_id IN ARRAY v_dels LOOP
    INSERT INTO invoice_delivery_notes (invoice_id, delivery_id) VALUES (v_id, v_del_id);
  END LOOP;
  FOREACH v_bank_id IN ARRAY v_ids LOOP
    SELECT * INTO v_bank FROM bank_accounts WHERE id = v_bank_id;
    INSERT INTO invoice_bank_instructions (invoice_id, bank_account_id, bank_name, account_number, account_holder, currency, branch, swift_code, position)
      VALUES (v_id, v_bank.id, v_bank.bank_name, v_bank.account_number, v_bank.account_holder, v_bank.currency, v_bank.branch, v_bank.swift_code, v_pos);
    v_pos := v_pos + 1;
  END LOOP;
  FOR v_item IN SELECT * FROM jsonb_array_elements(p->'items') LOOP
    INSERT INTO invoice_items (invoice_id, description, unit, quantity, price_minor, amount_minor)
      VALUES (v_id, v_item->>'description', v_item->>'unit', v_item->>'quantity', (v_item->>'price_minor')::bigint, (v_item->>'amount_minor')::bigint);
  END LOOP;
  PERFORM vr_create_verification('invoice', v_id);
  -- Every invoice comes with its pre-payment receipt (a draft until the invoice is issued). It is not a payment: it never changes the balance.
  PERFORM vr_create_prepayment(v_id, v_cust.id, v_cust.currency, (p->>'total_minor')::bigint, p->>'issued_at', coalesce((p->>'stamp_required')::boolean, FALSE));
  PERFORM vr_audit(p_actor, 'create', 'invoice', v_id, v_number || ' for quotation ' || v_q.number);
  RETURN v_id;
END
$fn$;

-- As before, and a voided invoice lets its delivery notes be billed again (the link stays as history).
CREATE OR REPLACE FUNCTION invoice_set_status(p_actor integer, p_id integer, p_action text) RETURNS void
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_inv invoices%ROWTYPE; v_cancelled integer;
BEGIN
  SELECT * INTO v_inv FROM invoices WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN PERFORM vr_fail(404, 'Invoice not found'); END IF;
  IF p_action = 'issue' AND v_inv.status = 'draft' THEN
    UPDATE invoices SET status = 'issued' WHERE id = p_id;
    PERFORM vr_release_prepayment(p_id);
  ELSIF p_action = 'void' AND v_inv.status NOT IN ('void', 'paid', 'partially_paid') THEN
    UPDATE invoices SET status = 'void' WHERE id = p_id;
    UPDATE document_verification_tokens SET revoked = TRUE WHERE kind = 'invoice' AND document_id = p_id;
    PERFORM vr_void_prepayments_of(p_id);
    UPDATE invoice_delivery_notes SET released_at = now() WHERE invoice_id = p_id AND released_at IS NULL;
    WITH c AS (UPDATE payments SET status = 'cancelled' WHERE invoice_id = p_id AND status = 'pending_confirmation' RETURNING id) SELECT count(*) INTO v_cancelled FROM c;
    IF v_cancelled > 0 THEN PERFORM vr_audit(p_actor, 'cancel-unconfirmed-payment', 'invoice', p_id, v_cancelled || ' open payment claim(s) cancelled with the void'); END IF;
  ELSE
    PERFORM vr_fail(409, 'Invalid state change. Reverse confirmed payments (void their receipts) before voiding an invoice');
  END IF;
  PERFORM vr_audit(p_actor, p_action, 'invoice', p_id, v_inv.number);
END
$fn$;

-- The stamped receipt is released: what the customer's email needs (the amount and date of the payment it is for) comes back with it.
CREATE OR REPLACE FUNCTION receipt_stamp_commit(p_actor integer, p_id integer, p_key text, p_sha256 text, p_reference text) RETURNS jsonb
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_receipt receipts%ROWTYPE; v_inv invoices%ROWTYPE; v_cust customers%ROWTYPE; v_pay payments%ROWTYPE; v_token text;
BEGIN
  SELECT * INTO v_receipt FROM receipts WHERE id = p_id FOR UPDATE;
  IF NOT FOUND OR v_receipt.status <> 'pending_stamp' OR NOT v_receipt.stamp_required THEN PERFORM vr_fail(409, 'This receipt is not waiting for a manual e-meterai'); END IF;
  SELECT * INTO v_inv FROM invoices WHERE id = v_receipt.invoice_id;
  SELECT * INTO v_cust FROM customers WHERE id = v_inv.customer_id;
  SELECT * INTO v_pay FROM payments WHERE id = v_receipt.payment_id;
  UPDATE receipts SET stamp_storage_key = p_key, stamp_sha256 = p_sha256, stamp_uploaded_at = now(), stamp_uploaded_by = p_actor, stamp_provider_reference = p_reference, status = 'issued' WHERE id = p_id;
  SELECT token INTO v_token FROM document_verification_tokens WHERE kind = 'receipt' AND document_id = p_id ORDER BY id LIMIT 1;
  PERFORM vr_audit(p_actor, 'stamp-upload', 'receipt', p_id, 'Official e-meterai reference: ' || p_reference || '; sha256: ' || p_sha256);
  RETURN jsonb_build_object('receipt_number', v_receipt.number, 'token', coalesce(v_token, ''), 'invoice_number', v_inv.number, 'currency', v_inv.currency,
    'payment', jsonb_build_object('amount_minor', v_pay.amount_minor, 'date', v_pay.date, 'reference', v_pay.reference),
    'customer', jsonb_build_object('name', v_cust.name, 'email', v_cust.email));
END
$fn$;

-- Queues ONE message with its attachments, all or nothing (a message without its attachments must never exist). `dedupe_key` makes it idempotent:
-- a second call with the same key returns the message already queued. p: event, recipient, subject, html, dedupe_key, attachments[{kind, id}].
CREATE OR REPLACE FUNCTION mail_enqueue(p jsonb) RETURNS jsonb
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_id integer; v_status text; v_att jsonb; v_pos integer := 0;
BEGIN
  IF jsonb_typeof(p->'attachments') IS DISTINCT FROM 'array' OR jsonb_array_length(p->'attachments') = 0 THEN PERFORM vr_fail(422, 'A message with attachments needs at least one'); END IF;
  INSERT INTO email_jobs (event, recipient, subject, html, status, attempts, dedupe_key)
    VALUES (p->>'event', p->>'recipient', p->>'subject', p->>'html', 'queued', 0, nullif(p->>'dedupe_key', ''))
    ON CONFLICT (dedupe_key) DO NOTHING RETURNING id, status INTO v_id, v_status;
  IF v_id IS NULL THEN
    SELECT id, status INTO v_id, v_status FROM email_jobs WHERE dedupe_key = p->>'dedupe_key';
    RETURN jsonb_build_object('id', v_id, 'status', v_status, 'created', FALSE);
  END IF;
  FOR v_att IN SELECT * FROM jsonb_array_elements(p->'attachments') LOOP
    INSERT INTO email_job_attachments (job_id, position, kind, document_id) VALUES (v_id, v_pos, v_att->>'kind', (v_att->>'id')::integer);
    v_pos := v_pos + 1;
  END LOOP;
  RETURN jsonb_build_object('id', v_id, 'status', v_status, 'created', TRUE);
END
$fn$;

-- ---------------------------------------------------------------------------------------------------------------------------------
-- E-mail wording. The new messages start switched off like every notification. A template the owner has edited is never touched: the
-- UPDATEs below apply only where the stored subject and text are still exactly the previous default.
-- ---------------------------------------------------------------------------------------------------------------------------------
INSERT INTO email_templates (key, subject, html) VALUES
  ('quotation_customer_approved_admin', $vora$VORA quotation signed by the customer - $document_number$vora$, $vora$<p>$customer_name has uploaded the signed quotation <strong>$document_number</strong> (signed by $signer_name, $signer_title).</p><p>Check the signature and the company stamp, then validate or reject it: <a href="$admin_url">Open the quotation</a>.</p>$vora$),
  ('quotation_validated_customer', $vora$VORA quotation validated - $document_number$vora$, $vora$<p>Dear $customer_name,</p><p>We have received your signed quotation <strong>$document_number</strong> and VORA has validated it. We will arrange the delivery with you accordingly.</p><p>VORA | Freight & Logistics</p>$vora$)
ON CONFLICT (key) DO NOTHING;
INSERT INTO email_rules (key, enabled) VALUES
  ('quotation_customer_approved_admin', FALSE),
  ('quotation_validated_customer', FALSE)
ON CONFLICT (key) DO NOTHING;

-- The invoice email now carries the invoice AND its pre-payment receipt.
UPDATE email_templates
   SET subject = $vora$VORA invoice $document_number$vora$,
       html = $vora$<p>Dear $customer_name,</p><p>Please find attached invoice <strong>$document_number</strong> ($document_date) and its pre-payment receipt <strong>$prepayment_number</strong>, in this one email.</p><p>The pre-payment receipt is prepared for your internal payment process. It is not proof that payment has been made: VORA issues the official payment receipt once the funds are credited to its bank account.</p><p>Verify the invoice using the QR code in the PDF or the link: <a href="$verify_url">Verify invoice</a>.</p><p>VORA | Freight & Logistics</p>$vora$
 WHERE key = 'invoice_customer'
   AND subject = $vora$VORA invoice $document_number$vora$
   AND html = $vora$<p>Dear $customer_name,</p><p>Please find attached invoice <strong>$document_number</strong> ($document_date).</p><p>Verify the document using the QR code in the PDF or the link: <a href="$verify_url">Verify invoice</a>.</p><p>VORA | Freight & Logistics</p>$vora$;

-- The official receipt email names the invoice, the confirmed amount and the date.
UPDATE email_templates
   SET subject = $vora$VORA | Payment Receipt $document_number$vora$,
       html = $vora$<p>Dear $customer_name,</p><p>Thank you. We confirm that your payment of <strong>$payment_amount</strong> was received on $payment_date for invoice <strong>$invoice_number</strong>.</p><p>Your official payment receipt <strong>$document_number</strong> is attached. Verify the document through the QR code or <a href="$verify_url">online verification</a>.</p><p>VORA | Freight & Logistics</p>$vora$
 WHERE key = 'receipt_customer'
   AND subject = $vora$VORA payment receipt $document_number$vora$
   AND html = $vora$<p>Dear $customer_name,</p><p>Your payment receipt <strong>$document_number</strong> is attached. Verify the document through the QR code or <a href="$verify_url">online verification</a>.</p><p>VORA | Freight & Logistics</p>$vora$;

-- The administrator's notice of a new inquiry shows the phone number.
UPDATE email_templates
   SET html = $vora$<h2>New $lead_type inquiry</h2><p>Reference: <strong>#$lead_id</strong></p><p>From: $name ($company)</p><p>Email: $email</p><p>Phone / WhatsApp: $phone</p><p>Service: $mode</p><p>Origin: $origin &nbsp; Destination: $destination</p><p>Message: $message</p><p>Open in admin: <a href="$admin_url">Lead #$lead_id</a></p>$vora$
 WHERE key = 'lead_admin'
   AND html = $vora$<h2>New $lead_type inquiry</h2><p>Reference: <strong>#$lead_id</strong></p><p>From: $name ($company)</p><p>Email: $email</p><p>Service: $mode</p><p>Origin: $origin &nbsp; Destination: $destination</p><p>Message: $message</p><p>Open in admin: <a href="$admin_url">Lead #$lead_id</a></p>$vora$;

-- ---------------------------------------------------------------------------------------------------------------------------------
-- The new functions are closed to everyone but the server's secret key (service_role), like the others.
-- ---------------------------------------------------------------------------------------------------------------------------------
DO $$
DECLARE f record;
BEGIN
  FOR f IN SELECT p.oid::regprocedure AS sig FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
           WHERE n.nspname = 'public' AND p.proname IN ('customer_save', 'lead_create', 'lead_convert', 'quotation_create', 'quotation_set_status', 'quotation_request_approval', 'approval_submit',
             'approval_review', 'delivery_create', 'delivery_update', 'invoice_create', 'invoice_set_status', 'receipt_stamp_commit', 'mail_enqueue')
  LOOP
    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC', f.sig);
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN EXECUTE format('REVOKE ALL ON FUNCTION %s FROM anon', f.sig); END IF;
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN EXECUTE format('REVOKE ALL ON FUNCTION %s FROM authenticated', f.sig); END IF;
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'service_role') THEN EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role', f.sig); END IF;
  END LOOP;
END $$;

-- ---------------------------------------------------------------------------
-- 0027_documents_bucket_evidence_types.sql
-- ---------------------------------------------------------------------------
-- The private documents bucket must accept the files the application stores in it.
-- Migration 0013 created `vora-documents` with application/pdf as its ONLY allowed type, but proof-of-delivery evidence is stored there too:
-- the receiver's signature (image/png) and the photos of the goods (image/jpeg). Supabase Storage refused those uploads, so no proof of delivery
-- could be recorded ("Private document storage failed"). 0013 never changes a bucket that already exists, so this migration does it.
--
-- What it does, and only this, to the bucket named below:
--   * adds application/pdf, image/png and image/jpeg to its allowed types, keeping every type that is already allowed;
--   * leaves a bucket that has NO type restriction (NULL) alone: it already accepts everything;
--   * keeps the bucket PRIVATE and keeps its file-size limit;
--   * creates the bucket (private) if it is missing.
-- It can be run again at any time. If the server uses another bucket name (environment variable SUPABASE_DOCUMENTS_BUCKET), change the name in
-- the first line below to that bucket's id before running it.
DO $$
DECLARE
  v_bucket constant text := 'vora-documents';
  v_needed constant text[] := ARRAY['application/pdf', 'image/png', 'image/jpeg'];
BEGIN
  IF to_regclass('storage.buckets') IS NULL THEN
    RAISE NOTICE 'storage schema not present: in the Supabase dashboard (Storage) make bucket % private and allow %', v_bucket, array_to_string(v_needed, ', ');
    RETURN;
  END IF;
  BEGIN
    INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
      VALUES (v_bucket, v_bucket, FALSE, 10485760, v_needed)
      ON CONFLICT (id) DO NOTHING;
    UPDATE storage.buckets
       SET public = FALSE,
           allowed_mime_types = (SELECT array_agg(DISTINCT t ORDER BY t) FROM unnest(allowed_mime_types || v_needed) AS t)
     WHERE id = v_bucket AND allowed_mime_types IS NOT NULL;
    UPDATE storage.buckets SET public = FALSE WHERE id = v_bucket;
  EXCEPTION WHEN undefined_column THEN
    RAISE NOTICE 'this Supabase storage schema has no per-bucket type list: allow % for bucket % in the dashboard', array_to_string(v_needed, ', '), v_bucket;
  END;
END $$;

-- ---------------------------------------------------------------------------
-- 0028_delivery_parties.sql
-- ---------------------------------------------------------------------------
-- Delivery notes: the SHIPPER (sender) is a party of its own.
-- A delivery note named only a consignee. The customer who pays, the shipper who hands the cargo over and the consignee who receives it are three
-- different roles and often three different organisations; `origin` and `destination` are places, not parties. This adds the shipper's identity
-- next to the consignee's, which already exist as consignee_name / _address / _contact / _phone / _email.
--
-- Historical delivery notes keep NULL shipper columns: nothing is invented or copied into them (the customer is not necessarily the shipper),
-- they stay readable, and they can still change state (issue, receive, reject, void). A NEW note, and the edit of a draft, must name the shipper
-- and the consignee and give both a full address: delivery_create / delivery_update refuse otherwise. The table's own rule only forbids a shipper
-- that is present but blank, so it never blocks a historical row.
ALTER TABLE deliveries
  ADD COLUMN IF NOT EXISTS shipper_name    VARCHAR(240),
  ADD COLUMN IF NOT EXISTS shipper_address TEXT,
  ADD COLUMN IF NOT EXISTS shipper_contact VARCHAR(160),
  ADD COLUMN IF NOT EXISTS shipper_phone   VARCHAR(60),
  ADD COLUMN IF NOT EXISTS shipper_email   VARCHAR(200);

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'deliveries_shipper_complete' AND conrelid = 'deliveries'::regclass) THEN
    ALTER TABLE deliveries ADD CONSTRAINT deliveries_shipper_complete
      CHECK (shipper_name IS NULL OR (btrim(shipper_name) <> '' AND btrim(coalesce(shipper_address, '')) <> ''));
  END IF;
END $$;

-- p: customer_id, quotation_id (both REQUIRED for a new note), shipper_name / _address / _contact / _phone / _email (name and address REQUIRED),
--    consignee_name / _address / _contact / _phone / _email (name and address REQUIRED), origin, destination, shipment_reference, po_number, carrier, vehicle,
--    vehicle_plate, driver_name, driver_phone, delivery_date, notes, capture_token, view_token, items[{description, quantity, unit, remarks}]
CREATE OR REPLACE FUNCTION delivery_create(p_actor integer, p jsonb) RETURNS integer
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_customer integer := nullif(p->>'customer_id', '')::integer; v_quotation integer := nullif(p->>'quotation_id', '')::integer; v_q quotations%ROWTYPE; v_number text; v_id integer;
BEGIN
  IF v_customer IS NULL THEN PERFORM vr_fail(422, 'Select the customer'); END IF;
  PERFORM 1 FROM customers WHERE id = v_customer;
  IF NOT FOUND THEN PERFORM vr_fail(422, 'Select an existing customer'); END IF;
  IF v_quotation IS NULL THEN PERFORM vr_fail(422, 'Select one of the customer''s validated quotations'); END IF;
  SELECT * INTO v_q FROM quotations WHERE id = v_quotation FOR SHARE;
  IF NOT FOUND OR v_q.customer_id IS DISTINCT FROM v_customer THEN PERFORM vr_fail(422, 'The quotation does not belong to this customer'); END IF;
  IF v_q.status <> 'validated' THEN PERFORM vr_fail(409, 'Delivery notes can only be made for a validated quotation'); END IF;
  IF length(btrim(coalesce(p->>'shipper_name', ''))) = 0 OR length(btrim(coalesce(p->>'shipper_address', ''))) = 0 THEN PERFORM vr_fail(422, 'Write the shipper''s name and full address'); END IF;
  IF length(btrim(coalesce(p->>'consignee_name', ''))) = 0 OR length(btrim(coalesce(p->>'consignee_address', ''))) = 0 THEN PERFORM vr_fail(422, 'Write the consignee''s name and full address'); END IF;
  IF jsonb_typeof(p->'items') IS DISTINCT FROM 'array' OR jsonb_array_length(p->'items') = 0 THEN PERFORM vr_fail(422, 'Add at least one item'); END IF;
  v_number := vr_next_number('DLV', vr_public_code('customers', v_customer), p->>'delivery_date');
  INSERT INTO deliveries (number, status, customer_id, quotation_id,
      shipper_name, shipper_address, shipper_contact, shipper_phone, shipper_email,
      consignee_name, consignee_address, consignee_contact, consignee_phone, consignee_email, origin, destination,
      shipment_reference, po_number, carrier, vehicle, vehicle_plate, driver_name, driver_phone, delivery_date, notes, capture_token, view_token, created_by)
    VALUES (v_number, 'draft', v_customer, v_quotation,
      p->>'shipper_name', p->>'shipper_address', coalesce(p->>'shipper_contact', ''), coalesce(p->>'shipper_phone', ''), coalesce(p->>'shipper_email', ''),
      p->>'consignee_name', p->>'consignee_address', p->>'consignee_contact', p->>'consignee_phone', p->>'consignee_email', p->>'origin', p->>'destination',
      p->>'shipment_reference', p->>'po_number', p->>'carrier', p->>'vehicle', p->>'vehicle_plate', p->>'driver_name', p->>'driver_phone', p->>'delivery_date', p->>'notes',
      p->>'capture_token', p->>'view_token', p_actor)
    RETURNING id INTO v_id;
  INSERT INTO delivery_items (delivery_id, position, description, quantity, unit, remarks)
    SELECT v_id, (t.ord - 1)::integer, t.x->>'description', t.x->>'quantity', t.x->>'unit', t.x->>'remarks' FROM jsonb_array_elements(p->'items') WITH ORDINALITY AS t(x, ord);
  PERFORM vr_audit(p_actor, 'create', 'delivery', v_id, v_number || ' for quotation ' || v_q.number);
  RETURN v_id;
END
$fn$;

-- Only a draft can be edited (an issued note is on its way with a printed QR code; its parties are not rewritten silently: void it and write a new one).
-- Its customer and quotation stay as they were made. A legacy draft without a shipper must be given one when it is saved.
CREATE OR REPLACE FUNCTION delivery_update(p_actor integer, p_id integer, p jsonb) RETURNS void
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_d deliveries%ROWTYPE;
BEGIN
  SELECT * INTO v_d FROM deliveries WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN PERFORM vr_fail(404, 'Delivery note not found'); END IF;
  IF v_d.status <> 'draft' THEN PERFORM vr_fail(409, 'Only a draft can be edited: void this delivery note and write a new one'); END IF;
  IF length(btrim(coalesce(p->>'shipper_name', ''))) = 0 OR length(btrim(coalesce(p->>'shipper_address', ''))) = 0 THEN PERFORM vr_fail(422, 'Write the shipper''s name and full address'); END IF;
  IF length(btrim(coalesce(p->>'consignee_name', ''))) = 0 OR length(btrim(coalesce(p->>'consignee_address', ''))) = 0 THEN PERFORM vr_fail(422, 'Write the consignee''s name and full address'); END IF;
  IF jsonb_typeof(p->'items') IS DISTINCT FROM 'array' OR jsonb_array_length(p->'items') = 0 THEN PERFORM vr_fail(422, 'Add at least one item'); END IF;
  UPDATE deliveries SET shipper_name = p->>'shipper_name', shipper_address = p->>'shipper_address', shipper_contact = coalesce(p->>'shipper_contact', ''),
      shipper_phone = coalesce(p->>'shipper_phone', ''), shipper_email = coalesce(p->>'shipper_email', ''),
      consignee_name = p->>'consignee_name', consignee_address = p->>'consignee_address', consignee_contact = p->>'consignee_contact',
      consignee_phone = p->>'consignee_phone', consignee_email = p->>'consignee_email', origin = p->>'origin', destination = p->>'destination', shipment_reference = p->>'shipment_reference',
      po_number = p->>'po_number', carrier = p->>'carrier', vehicle = p->>'vehicle', vehicle_plate = p->>'vehicle_plate', driver_name = p->>'driver_name', driver_phone = p->>'driver_phone',
      delivery_date = p->>'delivery_date', notes = p->>'notes', updated_at = now()
    WHERE id = p_id;
  DELETE FROM delivery_items WHERE delivery_id = p_id;
  INSERT INTO delivery_items (delivery_id, position, description, quantity, unit, remarks)
    SELECT p_id, (t.ord - 1)::integer, t.x->>'description', t.x->>'quantity', t.x->>'unit', t.x->>'remarks' FROM jsonb_array_elements(p->'items') WITH ORDINALITY AS t(x, ord);
  PERFORM vr_audit(p_actor, 'update', 'delivery', p_id, v_d.number);
END
$fn$;

-- Closed to everyone but the server's secret key (service_role), like the rest.
DO $$
DECLARE f record;
BEGIN
  FOR f IN SELECT p.oid::regprocedure AS sig FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
           WHERE n.nspname = 'public' AND p.proname IN ('delivery_create', 'delivery_update')
  LOOP
    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC', f.sig);
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN EXECUTE format('REVOKE ALL ON FUNCTION %s FROM anon', f.sig); END IF;
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN EXECUTE format('REVOKE ALL ON FUNCTION %s FROM authenticated', f.sig); END IF;
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'service_role') THEN EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role', f.sig); END IF;
  END LOOP;
END $$;

-- ---------------------------------------------------------------------------
-- 0029_document_trust.sql
-- ---------------------------------------------------------------------------
-- VORA Document Trust: immutable issued artifacts, organisational issuance attestations, an append-only evidence chain, revocation/supersession,
-- signer profiles and authority, passkey credentials, signing requests, challenges and events, and the parties of a multi-party document.
--
-- Additive and backward compatible: no existing table loses a column or a row, every existing document and QR token keeps working, and a document that was
-- issued before this migration simply has no artifact, no attestation and no signing event. It is NOT given any: the verification page shows only the evidence
-- that exists ("legacy" assurance). Nothing here is applied to production automatically.
--
-- What is and is not claimed:
--   * An artifact is the exact PDF VORA issued, kept in private storage with its SHA-256. It is never rewritten.
--   * An attestation is VORA's own Ed25519 signature over a canonical description of that artifact, made with a server-held key whose public half is listed
--     here. It is an internal application attestation, NOT a PSrE-certified electronic seal and NOT a personal electronic signature.
--   * A signing event is a non-certified electronic signature by an authenticated individual who held an active authority, consented explicitly, and proved
--     control of a passkey for THIS exact payload. It is not a certificate-backed signature.

-- The moment this system started. A document CREATED before it (an invoice, a letter, ...) keeps its legacy behaviour for ever: it is not given an archived artifact or
-- an attestation, because that would claim evidence that was never kept. Only documents created at or after this moment are archived when they are issued.
INSERT INTO settings (key, value, updated_at) VALUES ('trust_enabled_at', to_char(clock_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'), now()) ON CONFLICT (key) DO NOTHING;

-- ---------------------------------------------------------------------------------------------------------------------------------------------------------
-- Keys
-- ---------------------------------------------------------------------------------------------------------------------------------------------------------
-- The PUBLIC halves of the attestation keys. The private key is never in the database: it is an environment secret of the server (see DEPLOYMENT.md).
-- A retired key still verifies what it signed; a compromised key is marked so that the verification page says its attestations are not to be relied on.
CREATE TABLE IF NOT EXISTS attestation_keys (
  key_id         VARCHAR(64) PRIMARY KEY CHECK (key_id ~ '^[A-Za-z0-9._-]{3,64}$'),
  algorithm      VARCHAR(16) NOT NULL DEFAULT 'Ed25519' CHECK (algorithm = 'Ed25519'),
  public_key     TEXT NOT NULL CHECK (length(public_key) BETWEEN 40 AND 200),      -- base64 of the SPKI DER
  status         VARCHAR(16) NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'retired', 'compromised')),
  note           TEXT,
  created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  retired_at     TIMESTAMPTZ,
  compromised_at TIMESTAMPTZ
);
CREATE UNIQUE INDEX IF NOT EXISTS ux_attestation_keys_one_active ON attestation_keys ((TRUE)) WHERE status = 'active';

-- ---------------------------------------------------------------------------------------------------------------------------------------------------------
-- Artifacts and attestations
-- ---------------------------------------------------------------------------------------------------------------------------------------------------------
-- `kind` is the kind of the verification token (invoice, receipt, quotation, prepayment, document, delivery, pod); `document_id` is the row it names.
-- Version 1 is the issued file; a later version is a signed file made from the one before it (`supersedes_artifact_id`). Rows are never changed.
CREATE TABLE IF NOT EXISTS document_artifacts (
  id                     SERIAL PRIMARY KEY,
  kind                   VARCHAR(20) NOT NULL,
  document_id            INTEGER NOT NULL,
  version                INTEGER NOT NULL CHECK (version >= 1),
  role                   VARCHAR(16) NOT NULL CHECK (role IN ('issued', 'signed')),
  storage_key            VARCHAR(300) NOT NULL,
  sha256                 CHAR(64) NOT NULL CHECK (sha256 ~ '^[0-9a-f]{64}$'),
  byte_size              INTEGER NOT NULL CHECK (byte_size > 0),
  pages                  INTEGER,
  source_sha256          CHAR(64) CHECK (source_sha256 IS NULL OR source_sha256 ~ '^[0-9a-f]{64}$'),  -- the original third-party file, when there is one
  supersedes_artifact_id INTEGER REFERENCES document_artifacts (id),
  created_by             INTEGER REFERENCES users (id),
  created_at             TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (kind, document_id, version),
  UNIQUE (storage_key)
);
CREATE INDEX IF NOT EXISTS ix_document_artifacts_sha ON document_artifacts (sha256);

CREATE TABLE IF NOT EXISTS document_attestations (
  id                SERIAL PRIMARY KEY,
  artifact_id       INTEGER NOT NULL UNIQUE REFERENCES document_artifacts (id),
  key_id            VARCHAR(64) NOT NULL REFERENCES attestation_keys (key_id),
  algorithm         VARCHAR(16) NOT NULL DEFAULT 'Ed25519',
  payload_canonical TEXT NOT NULL,                  -- the exact text that was signed (canonical JSON)
  signature         TEXT NOT NULL,                  -- base64url
  issued_at         TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ---------------------------------------------------------------------------------------------------------------------------------------------------------
-- Evidence chain (append-only, hash-linked per document)
-- ---------------------------------------------------------------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS evidence_events (
  id          BIGSERIAL PRIMARY KEY,
  kind        VARCHAR(20) NOT NULL,
  document_id INTEGER NOT NULL,
  artifact_id INTEGER REFERENCES document_artifacts (id),
  event_type  VARCHAR(40) NOT NULL CHECK (event_type IN ('issued', 'attested', 'attestation_unavailable', 'signing_requested', 'signing_completed', 'signing_cancelled', 'revoked', 'superseded',
                                                       'party_fulfilled', 'legal_review_recorded', 'evidence_exported')),
  actor_id    INTEGER REFERENCES users (id),
  payload     JSONB NOT NULL DEFAULT '{}'::jsonb,
  prev_hash   CHAR(64) NOT NULL,
  hash        CHAR(64) NOT NULL,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS ix_evidence_events_document ON evidence_events (kind, document_id, id);

-- ---------------------------------------------------------------------------------------------------------------------------------------------------------
-- Revocation and supersession live next to the QR token that they affect
-- ---------------------------------------------------------------------------------------------------------------------------------------------------------
ALTER TABLE document_verification_tokens
  ADD COLUMN IF NOT EXISTS revoked_at          TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS revoked_reason      VARCHAR(300),
  ADD COLUMN IF NOT EXISTS superseded_by_kind  VARCHAR(20),
  ADD COLUMN IF NOT EXISTS superseded_by_id    INTEGER;

-- ---------------------------------------------------------------------------------------------------------------------------------------------------------
-- Signers
-- ---------------------------------------------------------------------------------------------------------------------------------------------------------
-- One profile per portal user. The identity is the Supabase Auth account behind users.auth_user_id: the name and position below are what the AUTHORISED
-- person is called on documents, set by an administrator other than that person (see signer_authority_grant), never typed by whoever prepares a document.
CREATE TABLE IF NOT EXISTS signer_profiles (
  id           SERIAL PRIMARY KEY,
  user_id      INTEGER NOT NULL UNIQUE REFERENCES users (id),
  display_name VARCHAR(160) NOT NULL CHECK (btrim(display_name) <> ''),
  position     VARCHAR(160) NOT NULL CHECK (btrim(position) <> ''),
  status       VARCHAR(16) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'active', 'suspended')),
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Grants of authority, kept for ever: a grant ends by being revoked (revoked_at), never by being deleted or edited.
-- `scope` lists document families the person may sign for (letter, parties, certificate, agreement, seal, ...) or '*'.
CREATE TABLE IF NOT EXISTS signer_authorities (
  id            SERIAL PRIMARY KEY,
  profile_id    INTEGER NOT NULL REFERENCES signer_profiles (id),
  scope         TEXT[] NOT NULL CHECK (cardinality(scope) > 0),
  granted_by    INTEGER NOT NULL REFERENCES users (id),
  granted_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  valid_until   TIMESTAMPTZ,
  sole_admin_grant BOOLEAN NOT NULL DEFAULT FALSE,    -- the only active administrator granted authority to themselves: recorded, not hidden
  note          VARCHAR(300),
  revoked_at    TIMESTAMPTZ,
  revoked_by    INTEGER REFERENCES users (id),
  revoke_reason VARCHAR(300)
);
CREATE INDEX IF NOT EXISTS ix_signer_authorities_profile ON signer_authorities (profile_id);

-- Passkeys (WebAuthn). The private key never leaves the signer's device; only the public key and a sign counter are stored.
CREATE TABLE IF NOT EXISTS signer_credentials (
  id            SERIAL PRIMARY KEY,
  profile_id    INTEGER NOT NULL REFERENCES signer_profiles (id),
  credential_id TEXT NOT NULL UNIQUE,                 -- base64url
  public_key    TEXT NOT NULL,                        -- base64url of the COSE key
  counter       BIGINT NOT NULL DEFAULT 0,
  transports    TEXT[],
  device_type   VARCHAR(20),
  backed_up     BOOLEAN,
  label         VARCHAR(80),
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_used_at  TIMESTAMPTZ,
  revoked_at    TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS ix_signer_credentials_profile ON signer_credentials (profile_id);

-- ---------------------------------------------------------------------------------------------------------------------------------------------------------
-- Signing requests, challenges and events
-- ---------------------------------------------------------------------------------------------------------------------------------------------------------
-- A request names the document, the exact artifact (and its SHA-256) the person is asked to sign, the person, and why. The person who prepares it is
-- recorded and is NOT the signer by virtue of preparing it.
CREATE TABLE IF NOT EXISTS signing_requests (
  id                 SERIAL PRIMARY KEY,
  ref                VARCHAR(24) NOT NULL UNIQUE,                       -- VORA-SIG-XXXXXXXX
  kind               VARCHAR(20) NOT NULL,
  document_id        INTEGER NOT NULL,
  family             VARCHAR(30) NOT NULL,
  source_artifact_id INTEGER NOT NULL REFERENCES document_artifacts (id),
  source_sha256      CHAR(64) NOT NULL CHECK (source_sha256 ~ '^[0-9a-f]{64}$'),
  signer_profile_id  INTEGER NOT NULL REFERENCES signer_profiles (id),
  purpose            VARCHAR(20) NOT NULL CHECK (purpose IN ('verified', 'approved', 'acknowledged', 'signed')),
  party_role         VARCHAR(30) NOT NULL DEFAULT 'vora',
  created_by         INTEGER NOT NULL REFERENCES users (id),
  legal_review_note  VARCHAR(500),                                      -- a document class that needs legal review records who reviewed it and what was decided
  legal_review_by    INTEGER REFERENCES users (id),
  status             VARCHAR(12) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'signed', 'cancelled', 'expired')),
  created_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
  expires_at         TIMESTAMPTZ NOT NULL,
  completed_at       TIMESTAMPTZ,
  result_artifact_id INTEGER REFERENCES document_artifacts (id)
);
CREATE INDEX IF NOT EXISTS ix_signing_requests_document ON signing_requests (kind, document_id);
CREATE INDEX IF NOT EXISTS ix_signing_requests_signer ON signing_requests (signer_profile_id, status);
-- One open request per document and signer, so that two preparers cannot race two ceremonies on the same file.
CREATE UNIQUE INDEX IF NOT EXISTS ux_signing_requests_open ON signing_requests (kind, document_id, signer_profile_id) WHERE status = 'pending';

-- One row per ceremony attempt (or passkey registration). `challenge` is what the passkey signs: for a signing it is the SHA-256 of the canonical payload, so
-- the assertion is bound to that exact document, signer, purpose, consent and placement. Used once (consumed_at) and only before it expires.
CREATE TABLE IF NOT EXISTS signing_challenges (
  id                SERIAL PRIMARY KEY,
  purpose           VARCHAR(12) NOT NULL CHECK (purpose IN ('register', 'sign')),
  profile_id        INTEGER NOT NULL REFERENCES signer_profiles (id),
  request_id        INTEGER REFERENCES signing_requests (id),
  challenge         VARCHAR(100) NOT NULL UNIQUE,                       -- base64url
  payload_canonical TEXT,
  created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
  expires_at        TIMESTAMPTZ NOT NULL,
  consumed_at       TIMESTAMPTZ
);

CREATE TABLE IF NOT EXISTS signing_events (
  id                 SERIAL PRIMARY KEY,
  request_id         INTEGER NOT NULL UNIQUE REFERENCES signing_requests (id),
  ref                VARCHAR(24) NOT NULL UNIQUE,
  profile_id         INTEGER NOT NULL REFERENCES signer_profiles (id),
  user_id            INTEGER NOT NULL REFERENCES users (id),
  credential_id      INTEGER NOT NULL REFERENCES signer_credentials (id),
  kind               VARCHAR(20) NOT NULL,
  document_id        INTEGER NOT NULL,
  source_artifact_id INTEGER NOT NULL REFERENCES document_artifacts (id),
  signed_artifact_id INTEGER NOT NULL UNIQUE REFERENCES document_artifacts (id),
  purpose            VARCHAR(20) NOT NULL,
  signer_name        VARCHAR(160) NOT NULL,                              -- frozen at signing
  signer_position    VARCHAR(160) NOT NULL,
  payload_canonical  TEXT NOT NULL,
  payload_sha256     CHAR(64) NOT NULL,
  consent            JSONB NOT NULL,                                     -- the statement shown, its version and each separate confirmation
  authentication     JSONB NOT NULL,                                     -- method, rp id, origin, user verification, counter: no secret, no IP
  placement          JSONB NOT NULL,
  signed_at          TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- The parties a document needs, and how each was fulfilled. VORA signing never fulfils anybody else's part.
CREATE TABLE IF NOT EXISTS document_parties (
  id               SERIAL PRIMARY KEY,
  kind             VARCHAR(20) NOT NULL,
  document_id      INTEGER NOT NULL,
  role             VARCHAR(30) NOT NULL,
  name             VARCHAR(240) NOT NULL CHECK (btrim(name) <> ''),
  required         BOOLEAN NOT NULL DEFAULT TRUE,
  method           VARCHAR(30) CHECK (method IS NULL OR method IN ('vora_electronic', 'external_pdf_uploaded', 'wet_ink_uploaded', 'manually_validated', 'external_certified_verified')),
  signing_event_id INTEGER REFERENCES signing_events (id),
  evidence_note    VARCHAR(500),
  evidence_sha256  CHAR(64) CHECK (evidence_sha256 IS NULL OR evidence_sha256 ~ '^[0-9a-f]{64}$'),
  fulfilled_at     TIMESTAMPTZ,
  fulfilled_by     INTEGER REFERENCES users (id),
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (kind, document_id, role),
  CHECK ((method IS NULL) = (fulfilled_at IS NULL)),
  CHECK (method IS DISTINCT FROM 'vora_electronic' OR signing_event_id IS NOT NULL)
);

-- ---------------------------------------------------------------------------------------------------------------------------------------------------------
-- Immutability
-- ---------------------------------------------------------------------------------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION trust_block_change() RETURNS trigger
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
BEGIN
  RAISE EXCEPTION 'Evidence is append-only: % on % is not allowed', TG_OP, TG_TABLE_NAME USING ERRCODE = 'VR409';
END
$fn$;

DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['document_artifacts', 'document_attestations', 'evidence_events', 'signing_events'] LOOP
    EXECUTE format('DROP TRIGGER IF EXISTS trg_%1$s_immutable ON %1$I', t);
    EXECUTE format('CREATE TRIGGER trg_%1$s_immutable BEFORE UPDATE OR DELETE ON %1$I FOR EACH ROW EXECUTE FUNCTION trust_block_change()', t);
    EXECUTE format('DROP TRIGGER IF EXISTS trg_%1$s_no_truncate ON %1$I', t);
    EXECUTE format('CREATE TRIGGER trg_%1$s_no_truncate BEFORE TRUNCATE ON %1$I FOR EACH STATEMENT EXECUTE FUNCTION trust_block_change()', t);
  END LOOP;
END $$;

-- An authority can only be ended: the one change allowed is to fill in the revocation, once.
CREATE OR REPLACE FUNCTION trust_authority_guard() RETURNS trigger
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
BEGIN
  IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'Authority history is kept: a grant is revoked, not deleted' USING ERRCODE = 'VR409'; END IF;
  IF OLD.revoked_at IS NOT NULL
     OR (to_jsonb(NEW) - 'revoked_at' - 'revoked_by' - 'revoke_reason') IS DISTINCT FROM (to_jsonb(OLD) - 'revoked_at' - 'revoked_by' - 'revoke_reason') THEN
    RAISE EXCEPTION 'A grant of authority cannot be edited: revoke it and grant a new one' USING ERRCODE = 'VR409';
  END IF;
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS trg_signer_authorities_guard ON signer_authorities;
CREATE TRIGGER trg_signer_authorities_guard BEFORE UPDATE OR DELETE ON signer_authorities FOR EACH ROW EXECUTE FUNCTION trust_authority_guard();

-- Revoking a token records when, and writes the evidence event, whichever code path voided the document.
CREATE OR REPLACE FUNCTION trust_token_revoked() RETURNS trigger
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
BEGIN
  IF NEW.revoked AND NOT coalesce(OLD.revoked, FALSE) THEN
    NEW.revoked_at := coalesce(NEW.revoked_at, now());
  END IF;
  RETURN NEW;
END
$fn$;
DROP TRIGGER IF EXISTS trg_tokens_revoked_before ON document_verification_tokens;
CREATE TRIGGER trg_tokens_revoked_before BEFORE UPDATE OF revoked ON document_verification_tokens FOR EACH ROW EXECUTE FUNCTION trust_token_revoked();

-- ---------------------------------------------------------------------------------------------------------------------------------------------------------
-- Evidence chain functions
-- ---------------------------------------------------------------------------------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION trust_event_hash(p_prev text, p_kind text, p_document integer, p_type text, p_actor integer, p_artifact integer, p_payload jsonb, p_at timestamptz) RETURNS text
LANGUAGE sql IMMUTABLE SET search_path = public, pg_temp AS $fn$
  SELECT encode(sha256(convert_to(
    p_prev || '|' || p_kind || '|' || p_document::text || '|' || p_type || '|' || coalesce(p_actor::text, '') || '|' || coalesce(p_artifact::text, '') || '|' || p_payload::text || '|' ||
    to_char(p_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'), 'UTF8')), 'hex')
$fn$;

-- Appends one event to the document's chain. Serialised per document, so two writers can never fork the chain.
CREATE OR REPLACE FUNCTION trust_append_evidence(p_kind text, p_document integer, p_type text, p_actor integer, p_artifact integer, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $fn$
DECLARE v_prev text; v_now timestamptz := clock_timestamp(); v_id bigint;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('trust-chain:' || p_kind || ':' || p_document::text));
  SELECT hash INTO v_prev FROM evidence_events WHERE kind = p_kind AND document_id = p_document ORDER BY id DESC LIMIT 1;
  v_prev := coalesce(v_prev, repeat('0', 64));
  v_now := date_trunc('milliseconds', v_now);
  INSERT INTO evidence_events (kind, document_id, artifact_id, event_type, actor_id, payload, prev_hash, hash, created_at)
    VALUES (p_kind, p_document, p_artifact, p_type, p_actor, coalesce(p_payload, '{}'::jsonb), v_prev,
            trust_event_hash(v_prev, p_kind, p_document, p_type, p_actor, p_artifact, coalesce(p_payload, '{}'::jsonb), v_now), v_now)
    RETURNING id INTO v_id;
  RETURN v_id;
END
$fn$;

-- Re-computes the whole chain of a document: { ok, events, broken_at }.
CREATE OR REPLACE FUNCTION trust_verify_evidence(p_kind text, p_document integer) RETURNS jsonb
LANGUAGE plpgsql STABLE SET search_path = public, pg_temp AS $fn$
DECLARE r record; v_prev text := repeat('0', 64); v_count integer := 0;
BEGIN
  FOR r IN SELECT * FROM evidence_events WHERE kind = p_kind AND document_id = p_document ORDER BY id LOOP
    IF r.prev_hash <> v_prev OR r.hash <> trust_event_hash(r.prev_hash, r.kind, r.document_id, r.event_type, r.actor_id, r.artifact_id, r.payload, r.created_at) THEN
      RETURN jsonb_build_object('ok', FALSE, 'events', v_count, 'broken_at', r.id);
    END IF;
    v_prev := r.hash; v_count := v_count + 1;
  END LOOP;
  RETURN jsonb_build_object('ok', TRUE, 'events', v_count, 'broken_at', NULL);
END
$fn$;

-- ---------------------------------------------------------------------------------------------------------------------------------------------------------
-- Issuance
-- ---------------------------------------------------------------------------------------------------------------------------------------------------------
-- The verification token of a document that may not have one yet (a delivery note or a proof of delivery). Idempotent, and serialised so that two callers get one token.
CREATE OR REPLACE FUNCTION trust_ensure_verification(p_kind text, p_document integer) RETURNS text
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE v_token text;
BEGIN
  IF p_kind NOT IN ('invoice', 'receipt', 'quotation', 'prepayment', 'document', 'delivery', 'pod') THEN RAISE EXCEPTION 'Unknown document kind' USING ERRCODE = 'VR422'; END IF;
  PERFORM pg_advisory_xact_lock(hashtext('trust-token:' || p_kind || ':' || p_document::text));
  SELECT token INTO v_token FROM document_verification_tokens WHERE kind = p_kind AND document_id = p_document ORDER BY id LIMIT 1;
  IF v_token IS NULL THEN v_token := vr_create_verification(p_kind, p_document); END IF;
  RETURN v_token;
END
$fn$;

-- The next version of a document's artifacts, for the application to put into the attestation it is about to sign.
CREATE OR REPLACE FUNCTION trust_next_version(p_kind text, p_document integer) RETURNS integer
LANGUAGE sql STABLE SET search_path = public, pg_temp AS $fn$
  SELECT coalesce(max(version), 0) + 1 FROM document_artifacts WHERE kind = p_kind AND document_id = p_document
$fn$;

-- Records an artifact, its attestation (when there is one) and the evidence, in one transaction. `p_expected_version` is the version the attestation was made for:
-- if another issuance got there first the call is refused (409) and the application removes the file it stored, so a document is issued once.
-- p: { storage_key, sha256, byte_size, pages, source_sha256, role, key_id, payload_canonical, signature, summary }
CREATE OR REPLACE FUNCTION trust_record_issuance(p_actor integer, p_kind text, p_document integer, p_expected_version integer, p jsonb) RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $fn$
DECLARE v_version integer; v_prev integer; v_id integer; v_role text := p->>'role'; v_key text := nullif(p->>'key_id', '');
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('trust-artifact:' || p_kind || ':' || p_document::text));
  SELECT coalesce(max(version), 0) + 1, max(id) INTO v_version, v_prev FROM document_artifacts WHERE kind = p_kind AND document_id = p_document;
  IF v_version <> p_expected_version THEN RAISE EXCEPTION 'This document was issued or signed meanwhile: reload it' USING ERRCODE = 'VR409'; END IF;
  IF v_role = 'issued' AND v_version <> 1 THEN RAISE EXCEPTION 'This document already has an issued file' USING ERRCODE = 'VR409'; END IF;
  IF v_role = 'signed' AND v_version = 1 THEN RAISE EXCEPTION 'A signed file is made from an issued one' USING ERRCODE = 'VR409'; END IF;
  IF v_role NOT IN ('issued', 'signed') THEN RAISE EXCEPTION 'Unknown artifact role' USING ERRCODE = 'VR422'; END IF;
  IF NOT EXISTS (SELECT 1 FROM document_verification_tokens WHERE kind = p_kind AND document_id = p_document AND NOT revoked) THEN
    RAISE EXCEPTION 'The document has no active verification record' USING ERRCODE = 'VR409';
  END IF;
  INSERT INTO document_artifacts (kind, document_id, version, role, storage_key, sha256, byte_size, pages, source_sha256, supersedes_artifact_id, created_by)
    VALUES (p_kind, p_document, v_version, v_role, p->>'storage_key', p->>'sha256', (p->>'byte_size')::integer, nullif(p->>'pages', '')::integer, nullif(p->>'source_sha256', ''), v_prev, p_actor)
    RETURNING id INTO v_id;
  PERFORM trust_append_evidence(p_kind, p_document, 'issued', p_actor, v_id, jsonb_build_object('version', v_version, 'role', v_role, 'sha256', p->>'sha256', 'summary', p->'summary'));
  IF v_key IS NOT NULL THEN
    INSERT INTO document_attestations (artifact_id, key_id, payload_canonical, signature) VALUES (v_id, v_key, p->>'payload_canonical', p->>'signature');
    PERFORM trust_append_evidence(p_kind, p_document, 'attested', p_actor, v_id, jsonb_build_object('key_id', v_key));
  ELSE
    PERFORM trust_append_evidence(p_kind, p_document, 'attestation_unavailable', p_actor, v_id, jsonb_build_object('reason', 'no attestation key was configured'));
  END IF;
  RETURN v_id;
END
$fn$;

-- Revokes a document's verification record (the existing void functions already do this on their own) or marks it superseded by another document.
CREATE OR REPLACE FUNCTION trust_revoke(p_actor integer, p_kind text, p_document integer, p_reason text, p_superseded_kind text DEFAULT NULL, p_superseded_id integer DEFAULT NULL) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $fn$
DECLARE v_n integer;
BEGIN
  IF p_superseded_kind IS NOT NULL AND p_superseded_id IS NULL THEN RAISE EXCEPTION 'Name the document that replaces this one' USING ERRCODE = 'VR422'; END IF;
  UPDATE document_verification_tokens
     SET revoked = TRUE, revoked_at = coalesce(revoked_at, now()), revoked_reason = left(coalesce(revoked_reason, p_reason), 300),
         superseded_by_kind = coalesce(superseded_by_kind, p_superseded_kind), superseded_by_id = coalesce(superseded_by_id, p_superseded_id)
   WHERE kind = p_kind AND document_id = p_document;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n = 0 THEN RAISE EXCEPTION 'The document has no verification record' USING ERRCODE = 'VR404'; END IF;
  PERFORM trust_append_evidence(p_kind, p_document, CASE WHEN p_superseded_kind IS NULL THEN 'revoked' ELSE 'superseded' END, p_actor, NULL,
                                jsonb_build_object('reason', left(coalesce(p_reason, ''), 300), 'superseded_by_kind', p_superseded_kind, 'superseded_by_id', p_superseded_id));
END
$fn$;

-- ---------------------------------------------------------------------------------------------------------------------------------------------------------
-- Signers and signing
-- ---------------------------------------------------------------------------------------------------------------------------------------------------------
-- Is the profile active, and does it hold a current, unrevoked authority covering `p_family` at `p_at`?
CREATE OR REPLACE FUNCTION trust_signer_authorized(p_profile integer, p_family text, p_at timestamptz DEFAULT now()) RETURNS boolean
LANGUAGE sql STABLE SET search_path = public, pg_temp AS $fn$
  SELECT EXISTS (
    SELECT 1 FROM signer_profiles p JOIN users u ON u.id = p.user_id JOIN signer_authorities a ON a.profile_id = p.id
     WHERE p.id = p_profile AND p.status = 'active' AND u.active
       AND a.revoked_at IS NULL AND a.granted_at <= p_at AND (a.valid_until IS NULL OR a.valid_until > p_at)
       AND ('*' = ANY (a.scope) OR p_family = ANY (a.scope)))
$fn$;

-- Grants authority. The administrator who grants it is not the person who receives it, except for the sole active administrator, which is recorded on the grant.
CREATE OR REPLACE FUNCTION trust_authority_grant(p_actor integer, p_profile integer, p_scope text[], p_valid_until timestamptz, p_note text) RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $fn$
DECLARE v_user integer; v_sole boolean := FALSE; v_id integer;
BEGIN
  SELECT user_id INTO v_user FROM signer_profiles WHERE id = p_profile FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Signer profile not found' USING ERRCODE = 'VR404'; END IF;
  IF p_valid_until IS NOT NULL AND p_valid_until <= now() THEN RAISE EXCEPTION 'The end of the authority must be in the future' USING ERRCODE = 'VR422'; END IF;
  IF v_user = p_actor THEN
    IF (SELECT count(*) FROM users WHERE active AND role = 'admin') <> 1 THEN RAISE EXCEPTION 'Authority to sign is granted by another administrator' USING ERRCODE = 'VR403'; END IF;
    v_sole := TRUE;
  END IF;
  INSERT INTO signer_authorities (profile_id, scope, granted_by, valid_until, sole_admin_grant, note) VALUES (p_profile, p_scope, p_actor, p_valid_until, v_sole, left(p_note, 300)) RETURNING id INTO v_id;
  UPDATE signer_profiles SET status = 'active', updated_at = now() WHERE id = p_profile AND status = 'pending';
  PERFORM vr_audit(p_actor, 'grant', 'signer_authority', v_id, array_to_string(p_scope, ','));
  RETURN v_id;
END
$fn$;

-- Uses a challenge once: only a challenge that exists, belongs to the profile and purpose, has not expired and has not been used. Returns its request and payload.
CREATE OR REPLACE FUNCTION trust_consume_challenge(p_challenge text, p_profile integer, p_purpose text) RETURNS jsonb
LANGUAGE plpgsql SET search_path = public, pg_temp AS $fn$
DECLARE r signing_challenges%ROWTYPE;
BEGIN
  UPDATE signing_challenges SET consumed_at = now()
   WHERE challenge = p_challenge AND profile_id = p_profile AND purpose = p_purpose AND consumed_at IS NULL AND expires_at > now()
   RETURNING * INTO r;
  IF NOT FOUND THEN RAISE EXCEPTION 'The authentication request is unknown, expired or already used: start again' USING ERRCODE = 'VR409'; END IF;
  RETURN jsonb_build_object('request_id', r.request_id, 'payload_canonical', r.payload_canonical);
END
$fn$;

-- Completes a signing, all or nothing. Everything the ceremony relied on is checked again here, under lock, whatever the application believed:
-- the request is still pending and unexpired, the signer is still authorised, the file being signed is still the latest and has the SHA-256 that was shown.
-- p: { credential_row_id, counter, signer_name, signer_position, payload_canonical, payload_sha256, consent, authentication, placement,
--      artifact: { storage_key, sha256, byte_size, pages, key_id, payload_canonical, signature } }
CREATE OR REPLACE FUNCTION trust_complete_signing(p_request integer, p_expected_version integer, p jsonb) RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $fn$
DECLARE q signing_requests%ROWTYPE; v_profile signer_profiles%ROWTYPE; v_latest document_artifacts%ROWTYPE; v_artifact integer; v_event integer; v_cred integer := (p->>'credential_row_id')::integer;
BEGIN
  SELECT * INTO q FROM signing_requests WHERE id = p_request FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Signing request not found' USING ERRCODE = 'VR404'; END IF;
  IF q.status <> 'pending' THEN RAISE EXCEPTION 'This signing request is no longer open' USING ERRCODE = 'VR409'; END IF;
  IF q.expires_at <= now() THEN RAISE EXCEPTION 'This signing request has expired' USING ERRCODE = 'VR409'; END IF;
  SELECT * INTO v_profile FROM signer_profiles WHERE id = q.signer_profile_id;
  IF NOT trust_signer_authorized(q.signer_profile_id, q.family) THEN RAISE EXCEPTION 'The signer holds no current authority for this kind of document' USING ERRCODE = 'VR403'; END IF;
  IF NOT EXISTS (SELECT 1 FROM signer_credentials WHERE id = v_cred AND profile_id = q.signer_profile_id AND revoked_at IS NULL) THEN RAISE EXCEPTION 'The passkey is not valid for this signer' USING ERRCODE = 'VR403'; END IF;
  PERFORM pg_advisory_xact_lock(hashtext('trust-artifact:' || q.kind || ':' || q.document_id::text));
  SELECT * INTO v_latest FROM document_artifacts WHERE kind = q.kind AND document_id = q.document_id ORDER BY version DESC LIMIT 1;
  IF v_latest.id IS DISTINCT FROM q.source_artifact_id OR v_latest.sha256 <> q.source_sha256 THEN RAISE EXCEPTION 'The document changed after the signing request was made: the consent given does not apply to it' USING ERRCODE = 'VR409'; END IF;
  IF v_latest.version + 1 <> p_expected_version THEN RAISE EXCEPTION 'This document was signed meanwhile: reload it' USING ERRCODE = 'VR409'; END IF;
  IF NOT EXISTS (SELECT 1 FROM document_verification_tokens WHERE kind = q.kind AND document_id = q.document_id AND NOT revoked) THEN RAISE EXCEPTION 'The document is revoked or has no verification record' USING ERRCODE = 'VR409'; END IF;

  INSERT INTO document_artifacts (kind, document_id, version, role, storage_key, sha256, byte_size, pages, source_sha256, supersedes_artifact_id, created_by)
    VALUES (q.kind, q.document_id, p_expected_version, 'signed', p#>>'{artifact,storage_key}', p#>>'{artifact,sha256}', (p#>>'{artifact,byte_size}')::integer, nullif(p#>>'{artifact,pages}', '')::integer,
            v_latest.source_sha256, v_latest.id, v_profile.user_id)
    RETURNING id INTO v_artifact;
  IF nullif(p#>>'{artifact,key_id}', '') IS NOT NULL THEN
    INSERT INTO document_attestations (artifact_id, key_id, payload_canonical, signature) VALUES (v_artifact, p#>>'{artifact,key_id}', p#>>'{artifact,payload_canonical}', p#>>'{artifact,signature}');
  END IF;
  INSERT INTO signing_events (request_id, ref, profile_id, user_id, credential_id, kind, document_id, source_artifact_id, signed_artifact_id, purpose, signer_name, signer_position,
                              payload_canonical, payload_sha256, consent, authentication, placement)
    VALUES (q.id, q.ref, q.signer_profile_id, v_profile.user_id, v_cred, q.kind, q.document_id, v_latest.id, v_artifact, q.purpose, p->>'signer_name', p->>'signer_position',
            p->>'payload_canonical', p->>'payload_sha256', p->'consent', p->'authentication', p->'placement')
    RETURNING id INTO v_event;
  UPDATE signer_credentials SET counter = greatest(counter, (p->>'counter')::bigint), last_used_at = now() WHERE id = v_cred;
  UPDATE signing_requests SET status = 'signed', completed_at = now(), result_artifact_id = v_artifact WHERE id = q.id;
  PERFORM trust_append_evidence(q.kind, q.document_id, 'issued', v_profile.user_id, v_artifact, jsonb_build_object('version', p_expected_version, 'role', 'signed', 'sha256', p#>>'{artifact,sha256}'));
  IF nullif(p#>>'{artifact,key_id}', '') IS NOT NULL THEN PERFORM trust_append_evidence(q.kind, q.document_id, 'attested', v_profile.user_id, v_artifact, jsonb_build_object('key_id', p#>>'{artifact,key_id}')); END IF;
  PERFORM trust_append_evidence(q.kind, q.document_id, 'signing_completed', v_profile.user_id, v_artifact,
                                jsonb_build_object('signing_ref', q.ref, 'signer_profile_id', q.signer_profile_id, 'purpose', q.purpose, 'party_role', q.party_role, 'payload_sha256', p->>'payload_sha256'));
  -- The party this signing was for, if the document tracks parties: fulfilled by this event, and only this party.
  UPDATE document_parties SET method = 'vora_electronic', signing_event_id = v_event, fulfilled_at = now(), fulfilled_by = v_profile.user_id
   WHERE kind = q.kind AND document_id = q.document_id AND role = q.party_role AND method IS NULL;
  RETURN v_event;
END
$fn$;

-- ---------------------------------------------------------------------------------------------------------------------------------------------------------
-- Who may do what: the tables are closed to the public API roles, evidence cannot be changed even through the Data API, and the functions are for the server only.
-- ---------------------------------------------------------------------------------------------------------------------------------------------------------
DO $$
DECLARE t text; f record;
BEGIN
  FOREACH t IN ARRAY ARRAY['attestation_keys', 'document_artifacts', 'document_attestations', 'evidence_events', 'signer_profiles', 'signer_authorities', 'signer_credentials',
                           'signing_requests', 'signing_challenges', 'signing_events', 'document_parties'] LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN EXECUTE format('REVOKE ALL ON public.%I FROM anon', t); END IF;
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN EXECUTE format('REVOKE ALL ON public.%I FROM authenticated', t); END IF;
  END LOOP;
  -- Evidence is written through the functions above only. Even the server's own API role cannot edit or delete a row of it.
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'service_role') THEN
    FOREACH t IN ARRAY ARRAY['document_artifacts', 'document_attestations', 'evidence_events', 'signing_events'] LOOP
      EXECUTE format('REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.%I FROM service_role', t);
    END LOOP;
    REVOKE UPDATE, DELETE, TRUNCATE ON signer_authorities FROM service_role;
    GRANT UPDATE (revoked_at, revoked_by, revoke_reason) ON signer_authorities TO service_role;
    REVOKE DELETE, TRUNCATE ON signer_profiles, signer_credentials, signing_requests, document_parties, attestation_keys FROM service_role;
  END IF;
  FOR f IN SELECT p.oid::regprocedure AS sig FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public' AND p.proname LIKE 'trust\_%' LOOP
    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC', f.sig);
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN EXECUTE format('REVOKE ALL ON FUNCTION %s FROM anon', f.sig); END IF;
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN EXECUTE format('REVOKE ALL ON FUNCTION %s FROM authenticated', f.sig); END IF;
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'service_role') THEN EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role', f.sig); END IF;
  END LOOP;
END $$;

-- ---------------------------------------------------------------------------
-- 0030_signer_profile_removal.sql
-- ---------------------------------------------------------------------------
-- A signer profile can be removed. It is not deleted: what it signed, and the authority and passkeys it held, stay as evidence, and nothing that points at it can be broken.
-- Removing it ends its authority, revokes its passkeys and cancels what was waiting for its signature; the person can later be given a new profile (the old one is reused, with
-- no authority: every grant has to be made again). Additive and safe to run again.
ALTER TABLE signer_profiles DROP CONSTRAINT IF EXISTS signer_profiles_status_check;
ALTER TABLE signer_profiles ADD CONSTRAINT signer_profiles_status_check CHECK (status IN ('pending', 'active', 'suspended', 'removed'));

CREATE OR REPLACE FUNCTION trust_profile_remove(p_actor integer, p_profile integer, p_reason text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $fn$
DECLARE v_name text; v_status text;
BEGIN
  SELECT display_name, status INTO v_name, v_status FROM signer_profiles WHERE id = p_profile FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Signer profile not found' USING ERRCODE = 'VR404'; END IF;
  IF v_status = 'removed' THEN RAISE EXCEPTION 'This signer profile is already removed' USING ERRCODE = 'VR409'; END IF;
  IF length(btrim(coalesce(p_reason, ''))) < 5 THEN RAISE EXCEPTION 'Give a reason of at least 5 characters' USING ERRCODE = 'VR422'; END IF;
  UPDATE signer_authorities SET revoked_at = now(), revoked_by = p_actor, revoke_reason = left('Profile removed: ' || btrim(p_reason), 300) WHERE profile_id = p_profile AND revoked_at IS NULL;
  UPDATE signer_credentials SET revoked_at = now() WHERE profile_id = p_profile AND revoked_at IS NULL;
  UPDATE signing_requests SET status = 'cancelled', completed_at = now() WHERE signer_profile_id = p_profile AND status = 'pending';
  UPDATE signer_profiles SET status = 'removed', updated_at = now() WHERE id = p_profile;
  PERFORM vr_audit(p_actor, 'remove', 'signer_profile', p_profile, v_name || ': ' || btrim(p_reason));
END
$fn$;

DO $$
DECLARE f record;
BEGIN
  FOR f IN SELECT p.oid::regprocedure AS sig FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public' AND p.proname = 'trust_profile_remove' LOOP
    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC', f.sig);
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN EXECUTE format('REVOKE ALL ON FUNCTION %s FROM anon', f.sig); END IF;
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN EXECUTE format('REVOKE ALL ON FUNCTION %s FROM authenticated', f.sig); END IF;
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'service_role') THEN EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role', f.sig); END IF;
  END LOOP;
END $$;

-- ---------------------------------------------------------------------------
-- 0031_vora_agent.sql
-- ---------------------------------------------------------------------------
-- VORA Agent: private chat history and durable request quotas. No anon/authenticated table access.
-- The public API reaches these tables with the existing server-side Supabase secret key.
CREATE TABLE IF NOT EXISTS agent_sessions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  token_hash text NOT NULL UNIQUE CHECK (length(token_hash) = 64),
  locale text NOT NULL DEFAULT 'en' CHECK (locale IN ('en', 'id')),
  consent_at timestamptz NOT NULL DEFAULT now(),
  created_at timestamptz NOT NULL DEFAULT now(),
  last_activity_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL DEFAULT (now() + interval '7 days')
);
CREATE INDEX IF NOT EXISTS agent_sessions_expiration_idx ON agent_sessions (expires_at);

CREATE TABLE IF NOT EXISTS agent_messages (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  session_id uuid NOT NULL REFERENCES agent_sessions(id) ON DELETE CASCADE,
  role text NOT NULL CHECK (role IN ('user', 'assistant')),
  content text NOT NULL CHECK (length(content) BETWEEN 1 AND 4000),
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS agent_messages_session_idx ON agent_messages (session_id, id DESC);

CREATE TABLE IF NOT EXISTS agent_rate_counters (
  key_hash text NOT NULL CHECK (length(key_hash) = 64),
  window_start timestamptz NOT NULL,
  count integer NOT NULL DEFAULT 0 CHECK (count >= 0),
  PRIMARY KEY (key_hash, window_start)
);
CREATE INDEX IF NOT EXISTS agent_rate_counters_window_idx ON agent_rate_counters (window_start);

ALTER TABLE agent_sessions ENABLE ROW LEVEL SECURITY;
ALTER TABLE agent_messages ENABLE ROW LEVEL SECURITY;
ALTER TABLE agent_rate_counters ENABLE ROW LEVEL SECURITY;
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN
    REVOKE ALL ON agent_sessions, agent_messages, agent_rate_counters FROM anon;
    REVOKE ALL ON SEQUENCE agent_messages_id_seq FROM anon;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN
    REVOKE ALL ON agent_sessions, agent_messages, agent_rate_counters FROM authenticated;
    REVOKE ALL ON SEQUENCE agent_messages_id_seq FROM authenticated;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'service_role') THEN
    GRANT SELECT, INSERT, UPDATE, DELETE ON agent_sessions, agent_messages, agent_rate_counters TO service_role;
    GRANT USAGE, SELECT ON SEQUENCE agent_messages_id_seq TO service_role;
  END IF;
END $$;

-- Atomic consumption protects against simultaneous requests on different serverless instances.
-- A rejected request cannot increment beyond the cap, and does not consume model tokens.
CREATE OR REPLACE FUNCTION agent_consume_quota(p_key text, p_window_seconds integer, p_max integer)
RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp
AS $$
DECLARE v_window timestamptz;
DECLARE v_count integer;
BEGIN
  IF p_key !~ '^[0-9a-f]{64}$' OR p_window_seconds NOT IN (600, 86400) OR p_max < 1 OR p_max > 100 THEN
    RAISE EXCEPTION 'Invalid agent quota' USING ERRCODE = '22023';
  END IF;
  v_window := to_timestamp(floor(extract(epoch FROM now()) / p_window_seconds) * p_window_seconds);
  INSERT INTO agent_rate_counters (key_hash, window_start, count)
    VALUES (p_key, v_window, 1)
    ON CONFLICT (key_hash, window_start) DO UPDATE
      SET count = agent_rate_counters.count + 1
      WHERE agent_rate_counters.count < p_max
    RETURNING count INTO v_count;
  RETURN v_count IS NOT NULL;
END $$;
REVOKE ALL ON FUNCTION agent_consume_quota(text, integer, integer) FROM PUBLIC;
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN REVOKE ALL ON FUNCTION agent_consume_quota(text, integer, integer) FROM anon; END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN REVOKE ALL ON FUNCTION agent_consume_quota(text, integer, integer) FROM authenticated; END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'service_role') THEN GRANT EXECUTE ON FUNCTION agent_consume_quota(text, integer, integer) TO service_role; END IF;
END $$;

-- Remove expired conversations after seven days and stale counters. Invoked opportunistically
-- by the agent backend, at most once per hour across all serverless instances.
CREATE TABLE IF NOT EXISTS agent_housekeeping (
  id boolean PRIMARY KEY DEFAULT true CHECK (id),
  last_run_at timestamptz NOT NULL DEFAULT (now() - interval '2 hours')
);
INSERT INTO agent_housekeeping (id) VALUES (true) ON CONFLICT DO NOTHING;
ALTER TABLE agent_housekeeping ENABLE ROW LEVEL SECURITY;
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN REVOKE ALL ON agent_housekeeping FROM anon; END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN REVOKE ALL ON agent_housekeeping FROM authenticated; END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'service_role') THEN GRANT SELECT, INSERT, UPDATE, DELETE ON agent_housekeeping TO service_role; END IF;
END $$;
CREATE OR REPLACE FUNCTION agent_cleanup()
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp
AS $$
DECLARE v_run boolean;
BEGIN
  UPDATE agent_housekeeping SET last_run_at = now()
   WHERE id = true AND last_run_at < now() - interval '1 hour'
   RETURNING true INTO v_run;
  IF v_run IS TRUE THEN
    DELETE FROM agent_sessions WHERE expires_at < now();
    DELETE FROM agent_rate_counters WHERE window_start < now() - interval '2 days';
  END IF;
END $$;
REVOKE ALL ON FUNCTION agent_cleanup() FROM PUBLIC;
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN REVOKE ALL ON FUNCTION agent_cleanup() FROM anon; END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN REVOKE ALL ON FUNCTION agent_cleanup() FROM authenticated; END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'service_role') THEN GRANT EXECUTE ON FUNCTION agent_cleanup() TO service_role; END IF;
END $$;

-- ---------------------------------------------------------------------------
-- 0032_vora_agent_identity.sql
-- ---------------------------------------------------------------------------
-- VORA Virtual Agent: compulsory visitor registration and CRM-aware deduplication.
-- Run after 0031. Private service-role only; do not expose identity lookups to anonymous clients.
CREATE TABLE IF NOT EXISTS agent_contacts (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name varchar(140) NOT NULL,
  company varchar(200) NOT NULL,
  email varchar(200) NOT NULL,
  phone varchar(40) NOT NULL,
  email_key text NOT NULL,
  phone_key text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (email_key, phone_key)
);
CREATE INDEX IF NOT EXISTS agent_contacts_phone_idx ON agent_contacts(phone_key);
CREATE INDEX IF NOT EXISTS agent_contacts_email_idx ON agent_contacts(email_key);

ALTER TABLE agent_sessions ADD COLUMN IF NOT EXISTS visitor_name varchar(140);
ALTER TABLE agent_sessions ADD COLUMN IF NOT EXISTS visitor_company varchar(200);
ALTER TABLE agent_sessions ADD COLUMN IF NOT EXISTS visitor_email varchar(200);
ALTER TABLE agent_sessions ADD COLUMN IF NOT EXISTS visitor_phone varchar(40);
ALTER TABLE agent_sessions ADD COLUMN IF NOT EXISTS identity_at timestamptz;
ALTER TABLE agent_sessions ADD COLUMN IF NOT EXISTS identity_source varchar(24);
ALTER TABLE agent_sessions ADD COLUMN IF NOT EXISTS identity_ref text;

-- Potential matches are held for manual review, never auto-merged into a CRM contact.
CREATE TABLE IF NOT EXISTS agent_identity_reviews (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  session_id uuid NOT NULL UNIQUE REFERENCES agent_sessions(id) ON DELETE CASCADE,
  name varchar(140) NOT NULL,
  company varchar(200) NOT NULL,
  email varchar(200) NOT NULL,
  phone varchar(40) NOT NULL,
  reason text NOT NULL,
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','reviewed')),
  reviewed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE agent_contacts ENABLE ROW LEVEL SECURITY;
ALTER TABLE agent_identity_reviews ENABLE ROW LEVEL SECURITY;
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='anon') THEN
    REVOKE ALL ON agent_contacts, agent_identity_reviews FROM anon;
    REVOKE ALL ON SEQUENCE agent_identity_reviews_id_seq FROM anon;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='authenticated') THEN
    REVOKE ALL ON agent_contacts, agent_identity_reviews FROM authenticated;
    REVOKE ALL ON SEQUENCE agent_identity_reviews_id_seq FROM authenticated;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='service_role') THEN
    GRANT SELECT, INSERT, UPDATE, DELETE ON agent_contacts, agent_identity_reviews TO service_role;
    GRANT USAGE, SELECT ON SEQUENCE agent_identity_reviews_id_seq TO service_role;
  END IF;
END $$;

CREATE OR REPLACE FUNCTION agent_normalize_email(p text) RETURNS text
LANGUAGE plpgsql IMMUTABLE SET search_path = public AS $$
DECLARE v text := lower(btrim(coalesce(p,'')));
DECLARE v_local text;
DECLARE v_domain text;
BEGIN
  v := regexp_replace(v, '^mailto:', '');
  v_local := split_part(v, '@', 1);
  v_domain := split_part(v, '@', 2);
  IF v_domain IN ('gmail.com','googlemail.com') THEN
    RETURN replace(split_part(v_local, '+', 1), '.', '') || '@gmail.com';
  END IF;
  RETURN v;
END $$;

CREATE OR REPLACE FUNCTION agent_normalize_phone(p text) RETURNS text
LANGUAGE plpgsql IMMUTABLE SET search_path = public AS $$
DECLARE v text := regexp_replace(coalesce(p,''), '[^0-9]', '', 'g');
BEGIN
  IF left(v, 3) = '620' AND length(v) BETWEEN 11 AND 16 THEN RETURN '62' || substr(v, 4); END IF;
  IF left(v, 2) = '08' AND length(v) BETWEEN 10 AND 14 THEN RETURN '62' || substr(v, 2); END IF;
  IF left(v, 1) = '8' AND length(v) BETWEEN 9 AND 13 THEN RETURN '62' || v; END IF;
  RETURN v;
END $$;

-- Common single-character errors (substitution, insertion, deletion, adjacent transpose).
CREATE OR REPLACE FUNCTION agent_one_typo(a text, b text) RETURNS boolean
LANGUAGE plpgsql IMMUTABLE SET search_path = public AS $$
DECLARE i integer := 1; j integer := 1; mistakes integer := 0;
DECLARE la integer := length(a); lb integer := length(b);
BEGIN
  IF a = b OR abs(la - lb) > 1 OR least(la,lb) < 3 THEN RETURN false; END IF;
  WHILE i <= la AND j <= lb LOOP
    IF substr(a,i,1) = substr(b,j,1) THEN i := i+1; j := j+1; CONTINUE; END IF;
    mistakes := mistakes+1;
    IF mistakes > 1 THEN RETURN false; END IF;
    IF la=lb AND i<la AND j<lb AND substr(a,i,1)=substr(b,j+1,1) AND substr(a,i+1,1)=substr(b,j,1) THEN
      i := i+2; j := j+2;
    ELSIF la>lb THEN i := i+1;
    ELSIF lb>la THEN j := j+1;
    ELSE i := i+1; j := j+1;
    END IF;
  END LOOP;
  RETURN true;
END $$;

CREATE OR REPLACE FUNCTION agent_email_near(a text, b text) RETURNS boolean
LANGUAGE sql IMMUTABLE SET search_path = public AS $$
  SELECT CASE WHEN a = b OR a = '' OR b = '' THEN false
    WHEN split_part(a,'@',2) = split_part(b,'@',2)
      THEN agent_one_typo(split_part(a,'@',1),split_part(b,'@',1))
    WHEN split_part(a,'@',1) = split_part(b,'@',1)
      THEN agent_one_typo(split_part(a,'@',2),split_part(b,'@',2))
    ELSE false END
$$;

CREATE OR REPLACE FUNCTION agent_register_identity(
 p_session uuid, p_name text, p_company text, p_email text, p_phone text,
 p_email_key text, p_phone_key text
) RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE v_source text := '';
DECLARE v_ref text := '';
DECLARE v_name text := lower(regexp_replace(btrim(p_name), '\s+', ' ', 'g'));
DECLARE v_possible boolean := false;
DECLARE v_contact uuid;
DECLARE v_id integer;
BEGIN
  IF length(btrim(coalesce(p_name,''))) NOT BETWEEN 2 AND 140 OR
     length(btrim(coalesce(p_company,''))) NOT BETWEEN 2 AND 200 OR
     length(coalesce(p_email,'')) NOT BETWEEN 5 AND 200 OR
     length(coalesce(p_phone,'')) NOT BETWEEN 7 AND 40 OR
     p_email_key <> agent_normalize_email(p_email) OR
     p_phone_key <> agent_normalize_phone(p_phone) OR
     p_email_key !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' OR
     p_phone_key !~ '^[0-9]{7,15}$'
  THEN RAISE EXCEPTION 'Invalid registration data' USING ERRCODE = '22023'; END IF;

  -- Lock the session so concurrent registration requests cannot compete.
  PERFORM 1 FROM agent_sessions WHERE id = p_session AND expires_at > now() FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Session expired' USING ERRCODE = '22023'; END IF;
  IF EXISTS (SELECT 1 FROM agent_sessions WHERE id=p_session AND identity_at IS NOT NULL) THEN RETURN 'registered'; END IF;

  -- Exact BOTH email and phone only. Phone-only/company mailbox matches may belong to a different person.
  SELECT id INTO v_id FROM customers
    WHERE (agent_normalize_email(pic_email)=p_email_key AND agent_normalize_phone(pic_phone)=p_phone_key)
       OR (agent_normalize_email(email)=p_email_key AND agent_normalize_phone(phone)=p_phone_key)
    ORDER BY id DESC LIMIT 1;
  IF v_id IS NOT NULL THEN v_source:='customer'; v_ref:=v_id::text; END IF;

  IF v_source='' THEN
    SELECT id INTO v_id FROM leads
      WHERE agent_normalize_email(email)=p_email_key AND agent_normalize_phone(phone)=p_phone_key
      ORDER BY id DESC LIMIT 1;
    IF v_id IS NOT NULL THEN v_source:='lead'; v_ref:=v_id::text; END IF;
  END IF;

  IF v_source='' THEN
    SELECT id INTO v_contact FROM agent_contacts
      WHERE email_key=p_email_key AND phone_key=p_phone_key LIMIT 1;
    IF v_contact IS NOT NULL THEN v_source:='contact'; v_ref:=v_contact::text; END IF;
  END IF;

  IF v_source='' THEN
    SELECT EXISTS (
      SELECT 1 FROM agent_contacts c
       WHERE c.phone_key=p_phone_key OR c.email_key=p_email_key OR
          (lower(btrim(c.name))=v_name AND agent_email_near(c.email_key,p_email_key))
      UNION ALL
      SELECT 1 FROM leads l
       WHERE agent_normalize_phone(l.phone)=p_phone_key OR agent_normalize_email(l.email)=p_email_key OR
          (lower(btrim(l.name))=v_name AND agent_email_near(agent_normalize_email(l.email),p_email_key))
      UNION ALL
      SELECT 1 FROM customers c
       WHERE agent_normalize_phone(c.pic_phone)=p_phone_key OR agent_normalize_phone(c.phone)=p_phone_key OR
          agent_normalize_email(c.pic_email)=p_email_key OR agent_normalize_email(c.email)=p_email_key OR
          (lower(btrim(c.pic_name))=v_name AND agent_email_near(agent_normalize_email(c.pic_email),p_email_key))
    ) INTO v_possible;

    IF v_possible THEN
      v_source:='review';
      INSERT INTO agent_identity_reviews(session_id,name,company,email,phone,reason)
      VALUES(p_session,btrim(p_name),btrim(p_company),lower(btrim(p_email)),btrim(p_phone),'Partial or possible typo match; do not merge automatically')
      ON CONFLICT (session_id) DO NOTHING;
    ELSE
      INSERT INTO agent_contacts(name,company,email,phone,email_key,phone_key)
      VALUES(btrim(p_name),btrim(p_company),lower(btrim(p_email)),btrim(p_phone),p_email_key,p_phone_key)
      ON CONFLICT (email_key,phone_key) DO UPDATE SET email_key=EXCLUDED.email_key
      RETURNING id INTO v_contact;
      v_source:='contact'; v_ref:=v_contact::text;
    END IF;
  END IF;

  UPDATE agent_sessions SET visitor_name=btrim(p_name), visitor_company=btrim(p_company),
    visitor_email=lower(btrim(p_email)), visitor_phone=btrim(p_phone), identity_at=now(),
    identity_source=v_source, identity_ref=nullif(v_ref,''), last_activity_at=now()
    WHERE id=p_session;
  RETURN v_source;
END $$;

REVOKE ALL ON FUNCTION agent_register_identity(uuid,text,text,text,text,text,text) FROM PUBLIC;
DO $$ BEGIN
 IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='anon') THEN REVOKE ALL ON FUNCTION agent_register_identity(uuid,text,text,text,text,text,text) FROM anon; END IF;
 IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='authenticated') THEN REVOKE ALL ON FUNCTION agent_register_identity(uuid,text,text,text,text,text,text) FROM authenticated; END IF;
 IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='service_role') THEN GRANT EXECUTE ON FUNCTION agent_register_identity(uuid,text,text,text,text,text,text) TO service_role; END IF;
END $$;

-- ---------------------------------------------------------------------------
-- 0033_vora_agent_knowledge.sql
-- ---------------------------------------------------------------------------
-- VORA Virtual Agent: admin-managed, versioned and published knowledge.
-- Never grant anonymous or authenticated clients access to editable knowledge or private attachments.
CREATE TABLE IF NOT EXISTS agent_knowledge (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  category text NOT NULL DEFAULT 'company' CHECK (category IN ('company','services','operations','incoterms','customs','documentation','faq','other')),
  title_en varchar(200) NOT NULL DEFAULT '',
  title_id varchar(200) NOT NULL DEFAULT '',
  body_en text NOT NULL DEFAULT '',
  body_id text NOT NULL DEFAULT '',
  source_url text NOT NULL DEFAULT '',
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','published','archived')),
  attachment_name varchar(255),
  attachment_key text,
  revision integer NOT NULL DEFAULT 1 CHECK (revision > 0),
  published_revision integer NOT NULL DEFAULT 0,
  created_by bigint REFERENCES users(id) ON DELETE SET NULL,
  updated_by bigint REFERENCES users(id) ON DELETE SET NULL,
  published_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT agent_knowledge_en_length CHECK (length(body_en) <= 80000),
  CONSTRAINT agent_knowledge_id_length CHECK (length(body_id) <= 80000),
  CONSTRAINT agent_knowledge_language_pair CHECK (
    ((length(btrim(title_en)) > 0) = (length(btrim(body_en)) > 0))
    AND ((length(btrim(title_id)) > 0) = (length(btrim(body_id)) > 0))
  )
);
CREATE INDEX IF NOT EXISTS agent_knowledge_status_idx ON agent_knowledge(status, updated_at DESC);

CREATE TABLE IF NOT EXISTS agent_knowledge_revisions (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  document_id bigint NOT NULL REFERENCES agent_knowledge(id) ON DELETE CASCADE,
  revision integer NOT NULL,
  snapshot jsonb NOT NULL,
  actor_id bigint REFERENCES users(id) ON DELETE SET NULL,
  action text NOT NULL CHECK (action IN ('save','publish','unpublish','archive','restore')),
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(document_id, revision)
);
CREATE INDEX IF NOT EXISTS agent_knowledge_revisions_doc_idx ON agent_knowledge_revisions(document_id, revision DESC);

CREATE TABLE IF NOT EXISTS agent_knowledge_chunks (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  document_id bigint NOT NULL REFERENCES agent_knowledge(id) ON DELETE CASCADE,
  locale text NOT NULL CHECK (locale IN ('en','id')),
  chunk_number integer NOT NULL,
  heading text NOT NULL,
  content text NOT NULL,
  category text NOT NULL,
  source_url text NOT NULL DEFAULT '',
  search_vector tsvector GENERATED ALWAYS AS (to_tsvector('simple', coalesce(heading,'') || ' ' || coalesce(content,''))) STORED,
  UNIQUE(document_id, locale, chunk_number)
);
CREATE INDEX IF NOT EXISTS agent_knowledge_chunks_search_idx ON agent_knowledge_chunks USING GIN(search_vector);
CREATE INDEX IF NOT EXISTS agent_knowledge_chunks_doc_idx ON agent_knowledge_chunks(document_id, locale);

ALTER TABLE agent_knowledge ENABLE ROW LEVEL SECURITY;
ALTER TABLE agent_knowledge_revisions ENABLE ROW LEVEL SECURITY;
ALTER TABLE agent_knowledge_chunks ENABLE ROW LEVEL SECURITY;
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='anon') THEN
    REVOKE ALL ON agent_knowledge, agent_knowledge_revisions, agent_knowledge_chunks FROM anon;
    REVOKE ALL ON SEQUENCE agent_knowledge_id_seq, agent_knowledge_revisions_id_seq, agent_knowledge_chunks_id_seq FROM anon;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='authenticated') THEN
    REVOKE ALL ON agent_knowledge, agent_knowledge_revisions, agent_knowledge_chunks FROM authenticated;
    REVOKE ALL ON SEQUENCE agent_knowledge_id_seq, agent_knowledge_revisions_id_seq, agent_knowledge_chunks_id_seq FROM authenticated;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='service_role') THEN
    GRANT SELECT, INSERT, UPDATE, DELETE ON agent_knowledge, agent_knowledge_revisions, agent_knowledge_chunks TO service_role;
    GRANT USAGE, SELECT ON SEQUENCE agent_knowledge_id_seq, agent_knowledge_revisions_id_seq, agent_knowledge_chunks_id_seq TO service_role;
  END IF;
END $$;

-- Publishing is atomic: no public request can ever retrieve half-rebuilt chunks.
-- Locks the document, validates language fields, rebuilds chunks and records a revision.
CREATE OR REPLACE FUNCTION agent_knowledge_publish(p_id bigint, p_actor bigint, p_expected_revision integer)
RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE d agent_knowledge%ROWTYPE;
DECLARE language text;
DECLARE heading text;
DECLARE body text;
DECLARE n integer;
DECLARE new_revision integer;
BEGIN
  SELECT * INTO d FROM agent_knowledge WHERE id=p_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Knowledge article not found' USING ERRCODE='22023'; END IF;
  IF d.revision <> p_expected_revision THEN RAISE EXCEPTION 'Knowledge article changed; refresh before publishing' USING ERRCODE='22023'; END IF;
  IF length(btrim(d.body_en)) < 30 AND length(btrim(d.body_id)) < 30 THEN
    RAISE EXCEPTION 'Enter at least 30 characters of content in one language' USING ERRCODE='22023';
  END IF;
  IF length(btrim(d.body_en)) BETWEEN 1 AND 29 OR length(btrim(d.body_id)) BETWEEN 1 AND 29 THEN
    RAISE EXCEPTION 'Each provided language needs at least 30 characters' USING ERRCODE='22023';
  END IF;
  DELETE FROM agent_knowledge_chunks WHERE document_id=p_id;
  FOR language IN SELECT unnest(ARRAY['en','id']) LOOP
    heading := CASE WHEN language='en' THEN d.title_en ELSE d.title_id END;
    body := CASE WHEN language='en' THEN d.body_en ELSE d.body_id END;
    IF length(btrim(body)) > 0 THEN
      -- Overlapping slices keep paragraph boundaries near chunk edges searchable.
      FOR n IN SELECT generate_series(0, greatest(0, ceil(length(body)::numeric / 1000)::integer - 1)) LOOP
        INSERT INTO agent_knowledge_chunks(document_id,locale,chunk_number,heading,content,category,source_url)
        VALUES(p_id,language,n,heading,substr(body, greatest(1,n*1000 - 129), 1130),d.category,d.source_url);
      END LOOP;
    END IF;
  END LOOP;
  new_revision := d.revision+1;
  UPDATE agent_knowledge SET status='published',revision=new_revision,published_revision=new_revision,updated_at=now(),updated_by=p_actor,published_at=now() WHERE id=p_id;
  INSERT INTO agent_knowledge_revisions(document_id,revision,snapshot,actor_id,action)
  VALUES(p_id,new_revision,to_jsonb(d) || jsonb_build_object('status','published','revision',new_revision),p_actor,'publish');
  RETURN new_revision;
END $$;
REVOKE ALL ON FUNCTION agent_knowledge_publish(bigint,bigint,integer) FROM PUBLIC;

-- Public agent calls this RPC only through the server's service-role credentials.
-- Returns published excerpts, not drafts, document metadata or private files.
CREATE OR REPLACE FUNCTION agent_search_knowledge(p_query text, p_locale text, p_limit integer DEFAULT 6)
RETURNS TABLE(id bigint, document_id bigint, title text, snippet text, category text, source_url text, language text, score real)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
WITH terms AS (
  SELECT DISTINCT w AS term FROM regexp_split_to_table(lower(left(coalesce(p_query,''),1000)), '[^[:alnum:]]+') AS w
  WHERE (length(w) BETWEEN 3 AND 36 OR w IN ('dg','bl','hs')) AND w NOT IN ('the','and','for','from','with','yang','untuk','dari','dengan','kami','anda','your','apa','bisa','how','can','this','that','have','ada')
  LIMIT 18
), query AS (
  SELECT CASE WHEN count(*)=0 THEN NULL::tsquery
    ELSE to_tsquery('simple',string_agg(quote_literal(term),' | ')) END AS q FROM terms
), ranked AS (
  SELECT c.id,c.document_id,c.heading AS title,c.content AS snippet,c.category,c.source_url,c.locale AS language,
   (ts_rank_cd(c.search_vector,q.q) + CASE WHEN c.locale=p_locale THEN 1 ELSE 0.10 END)::real AS score,
   row_number() OVER (PARTITION BY c.document_id ORDER BY ts_rank_cd(c.search_vector,q.q) DESC,c.id ASC) AS rn
  FROM agent_knowledge_chunks c JOIN agent_knowledge d ON d.id=c.document_id CROSS JOIN query q
  WHERE d.status='published' AND (c.locale=p_locale OR NOT EXISTS (
    SELECT 1 FROM agent_knowledge_chunks native WHERE native.document_id=c.document_id AND native.locale=p_locale
  )) AND q.q IS NOT NULL AND c.search_vector @@ q.q
)
SELECT ranked.id,ranked.document_id,ranked.title,left(ranked.snippet,1200),ranked.category,ranked.source_url,ranked.language,ranked.score
FROM ranked WHERE rn<=2 ORDER BY score DESC,id ASC LIMIT greatest(1,least(coalesce(p_limit,6),10));
$$;
REVOKE ALL ON FUNCTION agent_search_knowledge(text,text,integer) FROM PUBLIC;
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='anon') THEN
    REVOKE ALL ON FUNCTION agent_knowledge_publish(bigint,bigint,integer) FROM anon;
    REVOKE ALL ON FUNCTION agent_search_knowledge(text,text,integer) FROM anon;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='authenticated') THEN
    REVOKE ALL ON FUNCTION agent_knowledge_publish(bigint,bigint,integer) FROM authenticated;
    REVOKE ALL ON FUNCTION agent_search_knowledge(text,text,integer) FROM authenticated;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='service_role') THEN
    GRANT EXECUTE ON FUNCTION agent_knowledge_publish(bigint,bigint,integer) TO service_role;
    GRANT EXECUTE ON FUNCTION agent_search_knowledge(text,text,integer) TO service_role;
  END IF;
END $$;

-- Allow DOCX source uploads in the existing private VORA documents bucket.
-- Keep every previously allowed type and leave an unrestricted bucket untouched.
DO $$
DECLARE v_bucket constant text := 'vora-documents';
DECLARE v_mime constant text := 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';
BEGIN
  IF to_regclass('storage.buckets') IS NULL THEN
    RAISE NOTICE 'No Supabase Storage schema. Create a private documents bucket allowing PDF/DOCX before uploading knowledge.';
    RETURN;
  END IF;
  BEGIN
    UPDATE storage.buckets
      SET allowed_mime_types = (SELECT array_agg(DISTINCT t ORDER BY t) FROM unnest(allowed_mime_types || ARRAY[v_mime]) AS t)
      WHERE id=v_bucket AND allowed_mime_types IS NOT NULL;
  EXCEPTION WHEN undefined_column THEN
    RAISE NOTICE 'Update the private bucket MIME list manually to allow DOCX';
  END;
END $$;

-- ---------------------------------------------------------------------------
-- 0034_agent_ai_settings.sql
-- ---------------------------------------------------------------------------
-- VORA Virtual Agent: provider/model switcher and private API credentials.
-- API keys remain encrypted inside Supabase Vault; they are never stored in app tables.
CREATE SCHEMA IF NOT EXISTS vault;
CREATE EXTENSION IF NOT EXISTS supabase_vault WITH SCHEMA vault;

CREATE TABLE IF NOT EXISTS agent_ai_config (
  id smallint PRIMARY KEY DEFAULT 1 CHECK (id=1),
  provider text NOT NULL DEFAULT 'gemini' CHECK (provider IN ('gemini','openai')),
  model varchar(120) NOT NULL DEFAULT 'gemini-3.5-flash-lite',
  enabled boolean NOT NULL DEFAULT false,
  updated_by bigint REFERENCES users(id) ON DELETE SET NULL,
  updated_at timestamptz NOT NULL DEFAULT now()
);
INSERT INTO agent_ai_config(id) VALUES(1) ON CONFLICT(id) DO NOTHING;

CREATE TABLE IF NOT EXISTS agent_ai_credentials (
  provider text PRIMARY KEY CHECK (provider IN ('gemini','openai')),
  vault_secret_id uuid NOT NULL UNIQUE,
  key_hint varchar(12) NOT NULL DEFAULT '',
  updated_by bigint REFERENCES users(id) ON DELETE SET NULL,
  updated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE agent_ai_config ENABLE ROW LEVEL SECURITY;
ALTER TABLE agent_ai_credentials ENABLE ROW LEVEL SECURITY;
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='anon') THEN
    REVOKE ALL ON agent_ai_config,agent_ai_credentials FROM anon;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='authenticated') THEN
    REVOKE ALL ON agent_ai_config,agent_ai_credentials FROM authenticated;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='service_role') THEN
    GRANT SELECT,INSERT,UPDATE,DELETE ON agent_ai_config,agent_ai_credentials TO service_role;
  END IF;
END $$;

-- Restricted to the app server's service-role connection. Do not expose these to anon/authenticated.
CREATE OR REPLACE FUNCTION agent_ai_set_key(p_provider text,p_key text,p_actor bigint)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,vault,pg_temp AS $$
DECLARE v_id uuid;
BEGIN
  IF p_provider NOT IN ('gemini','openai') THEN RAISE EXCEPTION 'Invalid provider' USING ERRCODE='22023'; END IF;
  IF p_key IS NULL OR length(p_key) NOT BETWEEN 15 AND 400 OR p_key ~ '[[:space:][:cntrl:]]' THEN
    RAISE EXCEPTION 'Invalid API key' USING ERRCODE='22023';
  END IF;
  SELECT vault_secret_id INTO v_id FROM public.agent_ai_credentials WHERE provider=p_provider FOR UPDATE;
  IF v_id IS NULL THEN
    v_id := vault.create_secret(p_key,'vora_agent_'||p_provider,'VORA Virtual Agent provider credential');
    INSERT INTO public.agent_ai_credentials(provider,vault_secret_id,key_hint,updated_by)
    VALUES(p_provider,v_id,right(p_key,4),p_actor);
  ELSE
    PERFORM vault.update_secret(v_id,p_key);
    UPDATE public.agent_ai_credentials SET key_hint=right(p_key,4),updated_by=p_actor,updated_at=now() WHERE provider=p_provider;
  END IF;
END $$;

CREATE OR REPLACE FUNCTION agent_ai_remove_key(p_provider text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,vault,pg_temp AS $$
DECLARE v_id uuid;
BEGIN
  IF p_provider NOT IN ('gemini','openai') THEN RAISE EXCEPTION 'Invalid provider' USING ERRCODE='22023'; END IF;
  SELECT vault_secret_id INTO v_id FROM public.agent_ai_credentials WHERE provider=p_provider FOR UPDATE;
  IF v_id IS NOT NULL THEN
    DELETE FROM public.agent_ai_credentials WHERE provider=p_provider;
    DELETE FROM vault.secrets WHERE id=v_id;
    UPDATE public.agent_ai_config SET enabled=false,updated_at=now() WHERE id=1 AND provider=p_provider;
  END IF;
END $$;

-- The plaintext key exists only in the service-role RPC return to server-side code.
CREATE OR REPLACE FUNCTION agent_ai_get_key(p_provider text)
RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,vault,pg_temp AS $$
  SELECT v.decrypted_secret
  FROM public.agent_ai_credentials c JOIN vault.decrypted_secrets v ON v.id=c.vault_secret_id
  WHERE c.provider=p_provider AND p_provider IN ('gemini','openai') LIMIT 1;
$$;

CREATE OR REPLACE FUNCTION agent_ai_active()
RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,vault,pg_temp AS $$
  SELECT jsonb_build_object('provider',c.provider,'model',c.model,'api_key',v.decrypted_secret)
  FROM public.agent_ai_config c
  JOIN public.agent_ai_credentials k ON k.provider=c.provider
  JOIN vault.decrypted_secrets v ON v.id=k.vault_secret_id
  WHERE c.id=1 AND c.enabled=true AND length(v.decrypted_secret)>0 LIMIT 1;
$$;

REVOKE ALL ON FUNCTION agent_ai_set_key(text,text,bigint) FROM PUBLIC;
REVOKE ALL ON FUNCTION agent_ai_remove_key(text) FROM PUBLIC;
REVOKE ALL ON FUNCTION agent_ai_get_key(text) FROM PUBLIC;
REVOKE ALL ON FUNCTION agent_ai_active() FROM PUBLIC;
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='anon') THEN
    REVOKE ALL ON FUNCTION agent_ai_set_key(text,text,bigint) FROM anon;
    REVOKE ALL ON FUNCTION agent_ai_remove_key(text) FROM anon;
    REVOKE ALL ON FUNCTION agent_ai_get_key(text) FROM anon;
    REVOKE ALL ON FUNCTION agent_ai_active() FROM anon;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='authenticated') THEN
    REVOKE ALL ON FUNCTION agent_ai_set_key(text,text,bigint) FROM authenticated;
    REVOKE ALL ON FUNCTION agent_ai_remove_key(text) FROM authenticated;
    REVOKE ALL ON FUNCTION agent_ai_get_key(text) FROM authenticated;
    REVOKE ALL ON FUNCTION agent_ai_active() FROM authenticated;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='service_role') THEN
    GRANT EXECUTE ON FUNCTION agent_ai_set_key(text,text,bigint) TO service_role;
    GRANT EXECUTE ON FUNCTION agent_ai_remove_key(text) TO service_role;
    GRANT EXECUTE ON FUNCTION agent_ai_get_key(text) TO service_role;
    GRANT EXECUTE ON FUNCTION agent_ai_active() TO service_role;
  END IF;
END $$;

-- Seed articles are marked so re-running a seed never overrides admin edits.
ALTER TABLE agent_knowledge ADD COLUMN IF NOT EXISTS seed_key varchar(120);
CREATE UNIQUE INDEX IF NOT EXISTS agent_knowledge_seed_key_idx ON agent_knowledge(seed_key) WHERE seed_key IS NOT NULL;

-- ---------------------------------------------------------------------------
-- 0035_logistics_knowledge_seed.sql
-- ---------------------------------------------------------------------------
-- VORA logistics knowledge seed (verified general industry concepts, not claims about VORA's own capabilities).
-- Sources are internal editorial metadata only. Never show references/citations in visitor replies.
-- Idempotent: existing seed_key rows are NEVER overwritten, preserving subsequent admin edits.
-- Requires migration 0033 and 0034. Published chunks are built through the existing publishing RPC.
DO $vora_seed$
DECLARE v_id bigint;
BEGIN
  -- incoterms-overview
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('incoterms-overview', 'incoterms', 'Incoterms 2020: scope and rules', 'Incoterms 2020: fungsi dan pilihan', 'Incoterms® 2020 is the ICC''s current edition of eleven three-letter delivery terms for sales contracts. Seven rules may be used for any mode: EXW, FCA, CPT, CIP, DAP, DPU, DDP. Four are designed for sea and inland-waterway transport: FAS, FOB, CFR, CIF. The rule and a precise named place/port should be stated in the contract, for example “FCA Jakarta, Incoterms® 2020.” Each rule allocates tasks, transportation costs and the point where delivery/risk transfers between seller and buyer. Incoterms do not themselves determine title/ownership, payment method, cargo insurance for all rules, the full carriage contract, or tariff/permit requirements. Distinguish the party paying freight from the party bearing risk, especially under C terms. If the sales contract is not available, do not assume an Incoterm based on a shipment description.', 'Incoterms® 2020 adalah edisi terbaru aturan ICC berisi sebelas istilah penyerahan barang dalam kontrak jual-beli. Tujuh aturan untuk berbagai moda: EXW, FCA, CPT, CIP, DAP, DPU, DDP. Empat untuk angkutan laut/perairan pedalaman: FAS, FOB, CFR, CIF. Dalam kontrak perlu disebut aturan dan titik penyerahan secara spesifik, misalnya “FCA Jakarta, Incoterms® 2020”. Aturan ini membagi pekerjaan, biaya transportasi, dan titik perpindahan risiko antara penjual dan pembeli. Incoterms tidak otomatis menentukan kepemilikan barang, metode pembayaran, seluruh isi kontrak pengangkutan, atau perizinan ekspor-impor. Pihak yang membayar freight belum tentu memikul risiko sampai tujuan, terutama pada kelompok C. Jangan menebak Incoterms dari jenis pengiriman tanpa melihat kontrak jual-belinya.', 'https://iccwbo.org/business-solutions/incoterms-rules/incoterms-2020/')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- incoterms-exw-fca
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('incoterms-exw-fca', 'incoterms', 'EXW versus FCA', 'Perbedaan EXW dan FCA', 'Under EXW, the seller makes goods available at the named premises/place; the seller is not generally obligated to load the collecting vehicle or clear the export. This can create practical export-clearance problems for cross-border sales. Under FCA, the seller clears the goods for export when applicable and delivers them to the buyer-nominated carrier at the named place. Loading/unloading responsibility under FCA changes depending on whether delivery is at the seller''s premises or elsewhere. For containerized and multimodal shipments, FCA is often more suitable than FOB because delivery can be defined at a terminal or inland point. Confirm the exact named FCA place, pickup party, export documentation, and loading arrangements.', 'Pada EXW, penjual menyediakan barang di lokasi yang disebutkan. Secara umum penjual tidak berkewajiban memuat barang ke kendaraan penjemput maupun mengurus customs ekspor. Karena itu EXW bisa menyulitkan transaksi lintas negara. Pada FCA, penjual mengurus clearance ekspor bila berlaku lalu menyerahkan barang kepada carrier yang ditunjuk pembeli di titik yang disepakati. Pembagian tanggung jawab loading pada FCA bergantung pada apakah penyerahan dilakukan di lokasi penjual atau lokasi lain. Untuk container dan multimodal, FCA sering lebih sesuai daripada FOB karena penyerahannya bisa di terminal atau titik darat. Selalu pastikan lokasi FCA, pihak pickup, dokumen ekspor, dan tanggung jawab loading.', 'https://iccwbo.org/business-solutions/incoterms-rules/incoterms-2020/')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- incoterms-fob-cfr-cif
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('incoterms-fob-cfr-cif', 'incoterms', 'FOB, CFR and CIF for sea freight', 'FOB, CFR dan CIF untuk angkutan laut', 'FOB, CFR and CIF apply only to sea or inland-waterway transport. Under FOB, risk transfers when goods are placed on board the vessel at the named port of shipment; the buyer normally arranges and pays main carriage. Under CFR, the seller contracts and pays freight to the named destination port, but cargo risk transfers on board at the loading port, not at arrival. Under CIF, the seller also arranges cargo insurance at the rule''s minimum contractual coverage unless higher cover is agreed. FOB/CFR/CIF are not automatically suitable for container cargo delivered to a terminal before vessel loading; consider FCA/CPT/CIP for that situation. Port and carrier conditions still need verification.', 'FOB, CFR dan CIF digunakan untuk angkutan laut/perairan pedalaman. Pada FOB, risiko berpindah ketika barang berada di atas kapal di pelabuhan muat; main carriage umumnya diatur dan dibayar pembeli. Pada CFR, penjual membayar freight sampai pelabuhan tujuan, tetapi risiko sudah berpindah saat barang dimuat di kapal di pelabuhan asal, bukan ketika tiba. Pada CIF, penjual juga mengatur asuransi kargo dengan tingkat perlindungan minimum menurut aturan tersebut kecuali disepakati lebih tinggi. Untuk container yang diserahkan ke terminal sebelum dimuat ke kapal, FCA/CPT/CIP sering lebih tepat dibanding FOB/CFR/CIF. Detail pelabuhan dan ketentuan carrier tetap perlu dicek.', 'https://iccwbo.org/business-solutions/incoterms-rules/incoterms-2020/')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- incoterms-cpt-cip
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('incoterms-cpt-cip', 'incoterms', 'CPT versus CIP and risk transfer', 'CPT dan CIP serta perpindahan risiko', 'CPT and CIP can be used for any mode, including multimodal transport. Under CPT the seller pays carriage to the named destination, but risk generally transfers when goods are delivered to the first carrier. Under CIP the seller has the same carriage obligation and additionally procures insurance for the buyer''s benefit at the rule''s specified coverage standard. Paying transport to destination does not mean bearing cargo risk until destination. Under Incoterms 2020 the standard insurance requirement for CIP generally calls for more extensive coverage than CIF, unless the contract provides otherwise. Confirm named destinations and delivery points separately.', 'CPT dan CIP dapat digunakan untuk berbagai moda, termasuk multimodal. Pada CPT penjual membayar pengangkutan hingga tujuan yang disebutkan, tetapi risiko umumnya berpindah saat barang diserahkan kepada carrier pertama. CIP menambahkan kewajiban penjual untuk menyediakan asuransi kargo sesuai standar cakupan aturan tersebut. Membayar freight sampai tujuan tidak berarti menanggung risiko sampai tujuan. Dalam Incoterms 2020, kewajiban cakupan asuransi standar CIP umumnya lebih luas daripada CIF, kecuali para pihak menyepakati hal lain. Pastikan titik serah risiko dan tempat tujuan freight dibedakan.', 'https://iccwbo.org/business-solutions/incoterms-rules/incoterms-2020/')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- incoterms-dap-dpu-ddp
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('incoterms-dap-dpu-ddp', 'incoterms', 'DAP, DPU and DDP responsibilities', 'Tanggung jawab DAP, DPU dan DDP', 'DAP means the seller delivers the goods ready for unloading at the named destination; the buyer normally handles import clearance and import duties/taxes. Under DPU, the seller also unloads the goods at the named place; the unloading capability must therefore be confirmed. Under DDP, the seller is responsible for import clearance and applicable import duties/taxes in the destination country, which can be legally or operationally impossible if the seller is not eligible to act as importer. These terms do not guarantee that a forwarder can legally provide importer-of-record services. Confirm local law, permits, costs, unloading equipment and delivery conditions before quoting.', 'DAP berarti penjual menyerahkan barang siap dibongkar di tujuan yang disepakati; customs impor dan pungutan impor umumnya menjadi tanggung jawab pembeli. Pada DPU, penjual juga bertanggung jawab membongkar barang di tempat penyerahan, sehingga kemampuan unloading harus dipastikan. Pada DDP, penjual bertanggung jawab mengurus clearance impor serta bea/pajak impor yang berlaku di negara tujuan. DDP bisa tidak memungkinkan secara hukum atau operasional bila penjual tidak memenuhi persyaratan sebagai importir. Ketentuan ini tidak berarti forwarder otomatis bisa menjadi importer of record. Verifikasi aturan setempat, izin, biaya, peralatan bongkar dan kondisi delivery sebelum memberikan harga.', 'https://iccwbo.org/business-solutions/incoterms-rules/incoterms-2020/')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- incoterms-fas
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('incoterms-fas', 'incoterms', 'FAS Free Alongside Ship', 'FAS Free Alongside Ship', 'FAS is a sea/inland-waterway rule in which the seller delivers goods alongside the vessel nominated by the buyer at the named loading port. Risk transfers when the goods are placed alongside the vessel, not when they are later loaded on board. The buyer generally arranges sea carriage. FAS may be suitable for specific bulk or heavy cargo arrangements but is not interchangeable with FOB. Port access, terminal permissions, lifting plans and whether delivery can lawfully occur alongside the vessel must be verified.', 'FAS digunakan untuk angkutan laut/perairan pedalaman. Penjual menyerahkan barang di sisi kapal yang ditunjuk pembeli pada pelabuhan muat yang disepakati. Risiko berpindah ketika barang ditempatkan di sisi kapal, bukan ketika akhirnya berada di atas kapal. Pengangkutan laut umumnya diatur pembeli. FAS dapat relevan untuk komoditas curah atau kargo berat tertentu, tetapi tidak sama dengan FOB. Akses pelabuhan, izin terminal, rencana lifting dan kemungkinan penyerahan alongside harus dikonfirmasi.', 'https://iccwbo.org/business-solutions/incoterms-rules/incoterms-2020/')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- fcl-lcl
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('fcl-lcl', 'operations', 'FCL and LCL: practical differences', 'Perbedaan FCL dan LCL', 'FCL (full container load) generally means a container moves under one shipper''s booking/load arrangement; the container need not be filled to its limit. LCL (less than container load) combines cargo from multiple shipments at a consolidation facility. LCL often involves CFS receiving/handling, consolidation and deconsolidation fees at origin/destination; these should be included in a landed-cost comparison. For FCL, review container size, payload, commodity compatibility, equipment availability, detention/demurrage rules and loading feasibility. Neither FCL nor LCL guarantees a specific transit time or freight price.', 'FCL (full container load) umumnya berarti satu container dipakai untuk pengiriman berdasarkan satu pengaturan shipper, meskipun container tidak harus penuh. LCL (less than container load) menggabungkan kargo beberapa shipment di fasilitas konsolidasi. LCL dapat menimbulkan biaya CFS, handling, consolidation dan deconsolidation di origin/destination. Untuk FCL, periksa ukuran container, payload, jenis barang, ketersediaan equipment, ketentuan detention/demurrage dan kelayakan loading. Baik FCL maupun LCL tidak menjamin transit time atau harga tertentu.', 'https://fiata.org/resources/')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- freight-air
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('freight-air', 'operations', 'Air freight basics and chargeable weight', 'Dasar air freight dan chargeable weight', 'Air cargo charges may be based on the higher of actual gross weight and dimensional/volumetric weight, according to the airline or forwarder''s tariff. A commonly encountered air-freight divisor is 6,000 cm³ per kg, but it is not universal and must never be applied without checking the booked service''s tariff. Packing dimensions, pieces, stackability, ULD restrictions, commodity, security screening and destination handling matter. Check whether the quote covers terminal handling, fuel/security surcharges, pickup, customs, delivery and dangerous-goods acceptance. Do not guarantee airline space or departure without a confirmed booking.', 'Air freight dapat ditagih berdasarkan nilai yang lebih tinggi antara gross weight aktual dan volumetric/dimensional weight, sesuai tarif airline atau forwarder. Pembagi 6.000 cm³/kg sering digunakan untuk air freight, tetapi tidak berlaku universal dan harus dikonfirmasi pada service yang dipilih. Jumlah koli, dimensi kemasan, stackability, batas ULD, jenis barang, screening keamanan dan handling tujuan memengaruhi kelayakan. Cek apakah quotation sudah mencakup terminal handling, surcharge fuel/security, pickup, customs, delivery, serta approval DG. Space dan jadwal pesawat baru pasti setelah booking dikonfirmasi.', 'https://fiata.org/resources/')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- bl-hbl-mbl
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('bl-hbl-mbl', 'documentation', 'Master and House Bill of Lading', 'Master B/L dan House B/L', 'A Bill of Lading may serve as a receipt of goods, evidence of a carriage contract, and, where negotiable, a document of title. An ocean carrier may issue a Master B/L (MBL) while a freight forwarder/NVOCC issues a House B/L (HBL), depending on the service structure. Parties, cargo particulars, freight terms, routing, document-release requirements and destination agent should be checked for consistency. A non-negotiable sea waybill is different from a negotiable original B/L and typically does not require surrender of originals for cargo release. Actual release requirements depend on carrier and contract terms.', 'Bill of Lading dapat menjadi tanda penerimaan barang, bukti kontrak pengangkutan, dan untuk B/L negotiable juga dokumen hak atas barang. Carrier laut dapat menerbitkan Master B/L (MBL), sementara forwarder/NVOCC dapat menerbitkan House B/L (HBL), sesuai struktur layanan. Pastikan shipper/consignee, detail barang, freight term, routing, persyaratan release, dan destination agent konsisten. Sea waybill non-negotiable berbeda dengan original B/L negotiable dan biasanya tidak membutuhkan penyerahan original untuk release barang. Persyaratan aktual tetap mengikuti carrier dan kontrak.', 'https://fiata.org/resources/')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- awb-hawb-mawb
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('awb-hawb-mawb', 'documentation', 'Air Waybill, HAWB and MAWB', 'Air Waybill, HAWB dan MAWB', 'An Air Waybill (AWB) is generally a non-negotiable transport document and evidence of the air carriage contract. In consolidated air freight, an airline may issue a Master Air Waybill (MAWB) while a consolidator/forwarder issues a House Air Waybill (HAWB). Consignee, notify details, number of pieces, gross/chargeable weight, commodity description, airport codes and special handling should agree across the documents and manifest where applicable. AWB terminology does not mean that a shipment has already cleared customs or been released by the airline.', 'Air Waybill (AWB) umumnya merupakan dokumen pengangkutan non-negotiable dan bukti kontrak air carriage. Pada konsolidasi air freight, airline dapat menerbitkan Master AWB (MAWB), sementara consolidator/forwarder menerbitkan House AWB (HAWB). Periksa konsistensi consignee, notify party, jumlah koli, gross/chargeable weight, deskripsi barang, kode bandara dan special handling pada dokumen maupun manifest sesuai kebutuhan. AWB bukan bukti bahwa barang sudah customs cleared atau dapat langsung diambil.', 'https://fiata.org/resources/')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- invoice-packing-list
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('invoice-packing-list', 'documentation', 'Commercial Invoice and Packing List', 'Commercial Invoice dan Packing List', 'A commercial invoice normally identifies the seller/buyer, goods, quantities, unit and total values, currency, transaction terms and relevant shipment details. A packing list describes the physical packing: packages, marks, contents, gross/net weight, dimensions and often package-level breakdowns. These documents serve different purposes and should be consistent with declarations and transport records. Customs or the buyer may require additional information depending on jurisdiction and commodity. Never fabricate commodity values, HS codes, country of origin, or exporter/importer identities to complete a document.', 'Commercial Invoice umumnya berisi penjual/pembeli, barang, jumlah, harga per unit dan total, mata uang, ketentuan transaksi serta informasi shipment terkait. Packing List menjelaskan fisik kemasan: jumlah koli, marks, isi, berat gross/netto, dimensi, dan rincian per koli bila diperlukan. Fungsinya berbeda sehingga isinya harus konsisten dengan dokumen pengangkutan dan deklarasi. Bea Cukai atau pembeli bisa mensyaratkan informasi tambahan tergantung negara dan komoditas. Jangan mengarang nilai barang, HS Code, asal barang, atau identitas eksportir/importir untuk melengkapi dokumen.', 'https://www.wcoomd.org/en/topics/nomenclature/overview/harmonized_system_faq.aspx')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- vgm-solas
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('vgm-solas', 'documentation', 'Verified Gross Mass (SOLAS VGM)', 'Verified Gross Mass (VGM) SOLAS', 'For packed containers subject to SOLAS VGM rules, the shipper must provide the verified gross mass in time for the vessel stowage plan. Two permitted approaches are weighing the packed container, or summing all cargo/package/pallet/dunnage/securing material weights plus the container tare using a method approved by the relevant authority. Without VGM available to the master/terminal representative in time, a packed container cannot be loaded on an applicable vessel. VGM is the gross mass of the loaded container, not simply the cargo weight. National measurement, submission and cut-off requirements must be checked with the terminal and carrier.', 'Untuk packed container yang masuk cakupan aturan VGM SOLAS, shipper wajib memberikan verified gross mass tepat waktu agar dapat digunakan dalam stowage plan kapal. Metodenya: menimbang packed container secara langsung, atau menjumlah seluruh cargo, kemasan, pallet, dunnage, securing material serta berat tare container dengan metode yang disetujui otoritas setempat. Tanpa VGM yang tersedia tepat waktu untuk pihak kapal/terminal, container tidak boleh dimuat pada kapal yang tunduk pada aturan tersebut. VGM adalah gross mass container terisi, bukan hanya berat barang. Prosedur penimbangan, cut-off dan submission mengikuti ketentuan negara, terminal dan carrier.', 'https://www.imo.org/en/ourwork/safety/pages/verification-of-the-gross-mass.aspx')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- ocean-imdg-2026
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('ocean-imdg-2026', 'operations', 'Sea dangerous goods: IMDG Code', 'Dangerous goods laut: IMDG Code', 'The International Maritime Dangerous Goods (IMDG) Code governs many packaged dangerous goods movements by sea. As of 2026, the 2024 edition incorporating Amendment 42-24 is mandatory from 1 January 2026. Proper assessment depends on correct UN number, proper shipping name, hazard class/division, packing group where applicable, packaging, marking/labeling, stowage and segregation, declarations and carrier/terminal acceptance. A Safety Data Sheet (SDS) is useful input but is not a substitute for correct transport classification or a Dangerous Goods Declaration when required. Specific approvals, operator variations, and national rules must be verified; never assert a DG shipment is accepted without confirmation.', 'International Maritime Dangerous Goods (IMDG) Code mengatur banyak pengiriman dangerous goods dalam kemasan melalui laut. Pada 2026, edisi 2024 yang memuat Amendment 42-24 wajib berlaku sejak 1 Januari 2026. Penilaian membutuhkan UN number yang tepat, proper shipping name, hazard class/division, packing group jika berlaku, kemasan, mark/label, stowage/segregation, deklarasi dan acceptance carrier/terminal. Safety Data Sheet (SDS) membantu identifikasi tetapi tidak otomatis menggantikan klasifikasi transportasi maupun Dangerous Goods Declaration saat diwajibkan. Persetujuan khusus, operator variations dan aturan lokal tetap perlu diverifikasi; jangan menganggap DG otomatis diterima.', 'https://www.imo.org/en/publications/pages/imdg%20code.aspx')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- air-dg-iata-2026
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('air-dg-iata-2026', 'operations', 'Air dangerous goods: IATA DGR', 'Dangerous goods udara: IATA DGR', 'For dangerous goods by air, requirements are based on applicable ICAO Technical Instructions and airline/operator requirements, with IATA Dangerous Goods Regulations (DGR) providing widely used operational guidance. The IATA 67th edition applies in 2026. Eligibility depends on correct substance/battery classification, UN number, packing instruction, packaging, quantity limits, mark/label, documentation and airline/operator variations. Certain items may be prohibited on passenger aircraft but allowed on cargo aircraft only, or prohibited entirely. An SDS alone does not prove air acceptance. A trained DG specialist and airline must confirm the specific commodity before booking or quoting definitive DG handling.', 'Pengiriman dangerous goods melalui udara mengikuti ICAO Technical Instructions yang berlaku serta persyaratan operator/airline, dengan IATA Dangerous Goods Regulations (DGR) sebagai panduan operasional yang luas digunakan. Edisi IATA ke-67 berlaku pada 2026. Kelayakan bergantung pada klasifikasi barang/baterai, UN number, packing instruction, kemasan, batas quantity, mark/label, dokumen, dan operator variations. Barang tertentu dapat dilarang pada passenger aircraft tetapi diperbolehkan di cargo aircraft, atau dilarang sama sekali. SDS saja bukan bukti acceptance. DG specialist yang kompeten dan airline harus mengonfirmasi komoditas sebelum booking atau menyatakan DG diterima.', 'https://www.iata.org/en/publications/dgr/')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- lithium-battery-shipping
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('lithium-battery-shipping', 'operations', 'Lithium battery shipment screening', 'Pemeriksaan pengiriman baterai lithium', 'Lithium metal, lithium-ion and sodium-ion batteries may have different transport classifications and packaging requirements, and treatment depends on whether cells/batteries are shipped alone, packed with equipment, or contained in equipment. Watt-hour rating, lithium content, test-summary compliance, state of charge where relevant, package design, quantities, damage/defect status and the selected mode are critical. Do not infer acceptance from the fact that the goods are consumer electronics or from an SDS alone. Confirm the current IATA/ICAO air provisions or IMDG sea provisions, exact UN classification, packing instruction, operator approval and special provisions before commitment.', 'Baterai lithium metal, lithium-ion dan sodium-ion dapat memiliki klasifikasi pengangkutan serta persyaratan kemasan berbeda. Ketentuannya juga tergantung apakah baterai dikirim tersendiri, dikemas bersama peralatan, atau terpasang di dalam peralatan. Informasi penting antara lain Watt-hour, lithium content, pemenuhan test summary, state of charge bila relevan, jenis kemasan, quantity, status rusak/cacat dan moda yang digunakan. Jangan menganggap baterai aman dikirim hanya karena merupakan barang elektronik atau karena ada SDS. Konfirmasi klasifikasi UN, packing instruction, special provisions dan persetujuan operator pada aturan udara/laut yang berlaku.', 'https://www.iata.org/en/publications/dgr/')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- oog-breakbulk-project
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('oog-breakbulk-project', 'operations', 'OOG, breakbulk and heavy-lift', 'OOG, breakbulk dan heavy-lift', 'Out-of-gauge (OOG) cargo exceeds normal container envelope dimensions; it may still move on flat rack or open-top equipment if approved. Breakbulk cargo is carried as individually handled units rather than inside a standard container. Heavy-lift work requires weight/centre-of-gravity and engineered lifting/handling assessment; dimensions alone are insufficient. Quote feasibility needs package-wise dimensions, gross weight, centre of gravity where known, lifting/lashing points, packing drawings, port access, crane capacities, stowage, route restrictions and laycan. Carrier space and charter options are subject to technical and commercial approval. Do not promise vessel suitability without engineering review.', 'Out-of-gauge (OOG) adalah barang dengan dimensi yang melewati envelope container standar. Barang ini mungkin bisa memakai flat rack atau open-top jika disetujui carrier. Breakbulk adalah kargo yang ditangani per unit, bukan dimuat dalam container standar. Heavy-lift membutuhkan evaluasi berat, centre of gravity dan rencana lifting/handling yang direkayasa dengan benar. Data RFQ mencakup dimensi dan gross weight tiap package, CoG bila diketahui, lifting/lashing point, packing drawing, akses pelabuhan, kapasitas crane, stowage, batas rute dan laycan. Space/charter harus melalui persetujuan teknis dan komersial. Jangan menjanjikan kapal cocok tanpa review engineering.', 'https://www.imo.org/en/ourwork/safety/pages/cargosecuring-default.aspx')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- cargo-securing
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('cargo-securing', 'operations', 'Cargo securing and packing', 'Packing dan cargo securing', 'Cargo must be packed, blocked, braced and secured for the modes and forces encountered throughout its transport chain. A package that fits dimensionally can still be unsuitable because of floor-load limits, axle loading, weight distribution, lashing capacity, stacking strength, dangerous-goods segregation, movement or moisture exposure. The IMO/ILO/UNECE CTU Code provides non-mandatory international good-practice guidance for packing cargo transport units. Site-specific securing calculations, inspection and competent personnel may be needed. Do not provide an invented lashing count or crane sling arrangement without engineering data.', 'Kargo harus dikemas, diblok, diperkuat dan di-lashing sesuai gaya serta kondisi di sepanjang rantai transportasi. Barang yang muat secara dimensi tetap bisa tidak layak karena floor-load, axle load, distribusi berat, kapasitas lashing, kekuatan stacking, segregasi DG, gerakan, atau paparan kelembapan. IMO/ILO/UNECE CTU Code merupakan pedoman praktik internasional yang bersifat non-mandatory terkait packing cargo transport units. Perhitungan securing, inspeksi lapangan dan personel kompeten mungkin diperlukan. Jangan mengarang jumlah lashing atau konfigurasi sling crane tanpa data engineering.', 'https://www.imo.org/en/ourwork/safety/pages/ctu-code.aspx')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- hs-code-classification
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('hs-code-classification', 'customs', 'HS code and national tariff classification', 'HS Code dan klasifikasi tarif nasional', 'The Harmonized System (HS) is an internationally maintained nomenclature for classifying traded goods; six-digit HS headings/subheadings are internationally harmonized and countries may add national tariff digits. HS classification depends on objective product characteristics, materials, function and the relevant legal notes and General Rules for Interpretation. The product name alone is often insufficient. The final declaration must follow the destination/origin country''s current national tariff schedule and customs rulings where applicable. Never promise a definitive HS code, tariff rate or licensing status from a brief chat description. Request specifications, photos/datasheets and intended use, then seek customs verification.', 'Harmonized System (HS) adalah sistem klasifikasi barang perdagangan internasional. Enam digit pertama diharmonisasi secara internasional, sedangkan negara dapat menambahkan digit tarif nasional. Penentuan HS Code bergantung pada karakteristik objektif barang, bahan, fungsi, catatan hukum serta General Rules for Interpretation. Nama barang saja sering tidak cukup. Klasifikasi final mengikuti tarif nasional dan ketentuan Bea Cukai negara terkait. Jangan memastikan HS Code, tarif pajak/bea masuk atau status izin hanya berdasarkan deskripsi singkat chat. Minta spesifikasi, foto/datasheet dan fungsi barang lalu lakukan verifikasi customs.', 'https://www.wcoomd.org/en/topics/nomenclature/overview/harmonized_system_faq.aspx')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- customs-general
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('customs-general', 'customs', 'Customs clearance, documents and declarations', 'Customs clearance, dokumen dan deklarasi', 'Customs clearance is a legal procedure performed under the rules of the importing or exporting jurisdiction. Common inputs include invoice, packing list, transport document, importer/exporter information, commodity classification, country of origin and permits/certificates when relevant. Actual declarations, registration, risk channels, inspection, duties and timing vary by country and commodity. Electronic release or payment is not the same as physical cargo availability. VORA''s ability to act as customs broker, declarant or importer in a specific country must be confirmed. Never advise inaccurate declaration, misclassification or undervaluation.', 'Customs clearance adalah proses kepabeanan sesuai hukum negara impor/ekspor. Dokumen yang umum dipakai meliputi invoice, packing list, dokumen transport, identitas importir/eksportir, HS Code, negara asal, serta izin/sertifikat jika disyaratkan. Prosedur deklarasi, registrasi, jalur pemeriksaan, bea/pajak dan durasinya berbeda menurut negara serta komoditas. Barang sudah dibayar beanya atau keluar status release elektronik belum tentu secara fisik siap diambil. Kemampuan VORA sebagai customs broker, declarant atau importer pada negara tertentu harus dikonfirmasi. Jangan menyarankan deklarasi tidak benar, salah klasifikasi atau undervaluation.', 'https://www.wcoomd.org/en/topics/nomenclature/overview/harmonized_system_faq.aspx')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- lartas-permit
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('lartas-permit', 'customs', 'Restricted goods and import/export permits', 'Lartas dan izin impor/ekspor', 'Restricted or controlled goods may need prior permits, technical approvals, inspection, certifications or declarations beyond standard customs documents. Requirements depend on HS classification, actual product specifications, end use, origin, destination and effective regulations. A transport booking or bill of lading does not prove that the cargo has customs clearance or regulatory permission. For Indonesia, lartas and permits must be checked against the currently applicable official agency and customs systems. Do not guarantee importability or give an unverified exemption; ask for product details and escalate to a qualified clearance team.', 'Barang lartas atau regulated cargo dapat memerlukan izin awal, persetujuan teknis, pemeriksaan, sertifikasi atau deklarasi tambahan di luar dokumen customs biasa. Persyaratan mengikuti klasifikasi HS, spesifikasi dan fungsi barang, negara asal/tujuan serta regulasi yang sedang berlaku. Booking atau B/L bukan bukti barang boleh diimpor atau sudah mendapat izin. Untuk Indonesia, lartas dan perizinan harus dicek pada sistem resmi instansi dan kepabeanan yang relevan. Jangan menjanjikan bebas izin atau dapat diimpor tanpa verifikasi; kumpulkan data barang dan eskalasi ke tim clearance yang kompeten.', 'https://www.wcoomd.org/en/topics/nomenclature/overview/harmonized_system_faq.aspx')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- duties-tax-landed-cost
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('duties-tax-landed-cost', 'customs', 'Import duties, tax and landed cost', 'Bea masuk, pajak impor dan landed cost', 'Import landed cost may include the goods value, relevant freight and insurance, import duty, taxes, customs fees, port/terminal charges, brokerage and final delivery. Tax and duty treatment depends on product classification, customs valuation, origin, trade agreement eligibility and the importing country''s rules. Incoterms and commercial terms affect commercial cost allocation but cannot override customs law. Prefer itemized estimates with explicit assumptions rather than a single guaranteed percentage. Do not fabricate a tax rate or preferential tariff; verify official tariffs and supporting origin documents.', 'Landed cost impor dapat terdiri atas nilai barang, freight dan insurance yang relevan, bea masuk, pajak impor, biaya customs, port/terminal, brokerage serta delivery akhir. Bea/pajak bergantung pada HS Code, customs valuation, asal barang, kelayakan perjanjian dagang dan aturan negara impor. Incoterms mengatur pembagian biaya komersial tetapi tidak menggantikan hukum kepabeanan. Buat estimasi per komponen beserta asumsi, jangan langsung menjanjikan satu persentase total. Tarif pajak dan preferensi asal barang harus dicek pada ketentuan resmi dan dokumen pendukung.', 'https://www.wcoomd.org/en/topics/nomenclature/overview/harmonized_system_faq.aspx')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- demurrage-detention
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('demurrage-detention', 'operations', 'Demurrage, detention and storage', 'Demurrage, detention dan storage', 'Demurrage commonly refers to charges for keeping a container within a port/terminal beyond its agreed free time. Detention commonly refers to holding carrier equipment outside the terminal beyond free time. Terminal or warehouse storage can be an additional and separate charge. Definitions and billing arrangements vary by carrier, country, terminal and service contract. Charges can overlap and may change by container type or day band. To estimate exposure, request shipping line, container number/type, arrival/availability dates, free-time terms, current equipment status and terminal tariff; never invent a rate or free-time allowance.', 'Demurrage umumnya merupakan biaya karena container berada di area port/terminal melewati free time yang disepakati. Detention umumnya dikenakan bila equipment milik shipping line ditahan di luar terminal melewati free time. Storage terminal/gudang dapat menjadi biaya terpisah. Definisi dan ketentuan tagihannya berbeda menurut carrier, negara, terminal dan kontrak. Biaya dapat tumpang tindih dan berubah berdasarkan jenis container atau periode hari. Untuk menghitung risiko biaya, minta shipping line, nomor/jenis container, tanggal kedatangan/availability, free time, posisi equipment dan tarif terminal. Jangan mengarang tarif atau jatah free time.', 'https://fiata.org/resources/')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- shipment-timeline
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('shipment-timeline', 'operations', 'ETD, ETA, transit time and milestones', 'ETD, ETA, transit time dan milestone', 'ETD (estimated time of departure) and ETA (estimated time of arrival) are estimates, not guaranteed departure or delivery commitments. Ocean schedules can change due to rollover, transshipment, blank sailings, port congestion or weather; air schedules may change for capacity or operational reasons. Transit time normally measures transport travel between specified points and should not be confused with total door-to-door lead time, which also includes pickup, consolidation, customs, terminal processes and delivery. A reliable progress update distinguishes planned, booked, departed, arrived, customs-released and delivered status based on actual milestones, not guesses.', 'ETD (estimated time of departure) dan ETA (estimated time of arrival) adalah estimasi, bukan janji kapal/pesawat pasti berangkat atau barang pasti tiba pada jam tersebut. Jadwal laut dapat berubah karena rollover, transshipment, blank sailing, port congestion atau cuaca; jadwal udara juga bergantung kapasitas/operasional. Transit time biasanya mengukur waktu perjalanan antar titik tertentu, berbeda dari total door-to-door lead time yang juga mencakup pickup, konsolidasi, customs, terminal dan delivery. Update shipment sebaiknya membedakan planned, booked, departed, arrived, customs-released dan delivered berdasarkan milestone nyata, bukan tebakan.', 'https://fiata.org/resources/')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- freight-quote-scope
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('freight-quote-scope', 'operations', 'How to read a freight quotation', 'Cara membaca quotation freight', 'A useful freight quotation states the origin and destination points, scope (port-to-port, airport-to-airport, door-to-port or door-to-door), cargo assumptions, service mode, equipment, currency, inclusions/exclusions, surcharges, validity, free time if confirmed, and conditions. Freight alone is not necessarily the full landed cost. Local handling, customs, taxes, delivery, special equipment, documentation and DG/OOG charges may be excluded. If an item is not expressly included, ask before assuming. Pricing, routing, carrier schedule and availability must be reconfirmed at booking.', 'Quotation freight yang baik menjelaskan titik asal/tujuan, scope layanan (port-to-port, airport-to-airport, door-to-port atau door-to-door), asumsi kargo, moda, equipment, mata uang, biaya termasuk/tidak termasuk, surcharge, masa berlaku, free time jika sudah dikonfirmasi, dan syarat lainnya. Freight tidak selalu sama dengan seluruh landed cost. Local handling, customs, taxes, delivery, special equipment, documentation atau biaya DG/OOG mungkin terpisah. Jika suatu item tidak tertulis included, perlu ditanyakan. Harga, routing, jadwal carrier dan availability tetap harus dikonfirmasi lagi saat booking.', 'https://fiata.org/resources/')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- shipment-rfq-input
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('shipment-rfq-input', 'operations', 'Minimum information for a shipment RFQ', 'Data yang diperlukan untuk RFQ shipment', 'For an actionable shipping RFQ, first confirm origin and destination (address/port/airport), commodity and trade direction, pieces, package dimensions and gross weight, cargo readiness date, applicable Incoterm, and desired delivery scope. Add packing type, value/insurance request and any dangerous-goods, temperature-control or OOG/heavy-lift requirements. For heavy units ask for package-by-package drawings, centre of gravity, lifting points, lashing data and site access restrictions. Ask only for missing information in a natural sequence. Never issue a firm rate, tax assessment or space confirmation without a verified buying quotation and operational approval.', 'Untuk RFQ pengiriman yang bisa diproses, pastikan titik asal dan tujuan (alamat/pelabuhan/bandara), jenis barang dan arah perdagangan, jumlah koli, dimensi kemasan dan gross weight, cargo ready date, Incoterm serta scope delivery. Tambahkan jenis packing, nilai/asuransi jika diperlukan, dan kebutuhan DG, temperature control atau OOG/heavy-lift. Untuk unit berat minta drawing per package, centre of gravity, lifting point, data lashing dan pembatasan akses site. Tanyakan data yang belum ada secara bertahap dan natural. Jangan menerbitkan rate pasti, estimasi pajak final atau konfirmasi space tanpa buying quotation terverifikasi dan persetujuan operasional.', 'https://fiata.org/resources/')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- insurance-claims
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('insurance-claims', 'operations', 'Cargo insurance and freight claims', 'Asuransi kargo dan klaim pengiriman', 'Carrier liability and cargo insurance are different: a liability claim may have contractual limits and exclusions, while a cargo policy provides coverage according to its own terms, insured value, exclusions and deductibles. CIF and CIP involve specific seller insurance obligations under Incoterms 2020, but insurance is not automatically included under every Incoterm or freight quote. In a suspected loss/damage case, preserve photos, packing, transport documents, delivery/POD notations and timelines; notify relevant insurer/carrier promptly and follow their claim deadlines. Do not promise claim approval or reimbursement without policy and factual review.', 'Tanggung jawab carrier dan asuransi kargo adalah hal berbeda. Klaim liability carrier dapat dibatasi kontrak dan pengecualian, sedangkan polis asuransi memiliki syarat cakupan, insured value, pengecualian dan deductible sendiri. CIF dan CIP mengatur kewajiban asuransi tertentu pada penjual menurut Incoterms 2020, tetapi asuransi tidak otomatis termasuk di semua Incoterms atau freight quotation. Saat ada indikasi kehilangan/kerusakan, simpan foto, packing, dokumen transport, catatan pada POD dan kronologi; segera beri notifikasi ke carrier/asuransi sesuai tenggat polis/kontrak. Jangan menjamin klaim akan diterima atau dibayar tanpa review.', 'https://iccwbo.org/business-solutions/incoterms-rules/incoterms-2020/')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- warehouse-3pl
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('warehouse-3pl', 'operations', 'Warehousing, 3PL and fulfillment basics', 'Dasar warehousing, 3PL dan fulfillment', 'Warehousing typically covers storage, receipt, inventory control, stock counting, picking and dispatch. Third-party logistics (3PL) may combine warehouse operations with transport, order fulfillment, labeling/repacking and returns handling when contracted. A warehouse''s actual capabilities depend on its layout, racking and floor load ratings, fire protection, regulatory permissions, systems and service agreement. Temperature-controlled, bonded, DG and pharmaceutical warehousing need separate compliance checks. General descriptions of 3PL operations do not prove that VORA owns a warehouse or provides every special facility; confirm service availability with the team.', 'Warehousing umumnya mencakup penerimaan barang, penyimpanan, inventory control, stock opname, picking dan dispatch. Third-party logistics (3PL) dapat menggabungkan warehouse dengan transportasi, fulfillment order, labeling/repacking dan retur sesuai kontrak. Kemampuan gudang bergantung pada layout, kapasitas floor load dan racking, proteksi kebakaran, izin, sistem dan service agreement. Gudang temperature-controlled, bonded, DG dan pharmaceutical memerlukan verifikasi kepatuhan khusus. Penjelasan umum 3PL bukan bukti bahwa VORA memiliki gudang sendiri atau seluruh fasilitas khusus tersebut; ketersediaannya harus dikonfirmasi tim.', 'https://www.imo.org/en/ourwork/safety/pages/ctu-code.aspx')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- reefer-cold-chain
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('reefer-cold-chain', 'operations', 'Reefer shipping and temperature-sensitive cargo', 'Reefer dan pengiriman temperature-sensitive', 'Reefer containers and cold-chain services are specified by cargo temperature requirements, packaging, permissible temperature range, ventilation/humidity needs, pre-cooling requirements and monitoring arrangements. A reefer can maintain a set temperature under suitable operating conditions but is not a substitute for correctly preparing cargo or for a controlled-temperature process before stuffing. The shipper must give accurate product requirements and carrier/terminal approval is needed for equipment and routing. Do not guarantee a specific temperature, product shelf life or reefer equipment availability without verified requirements and booking.', 'Reefer dan cold-chain memerlukan informasi target suhu, toleransi rentang suhu, jenis kemasan, kebutuhan ventilasi/kelembapan, pre-cooling serta metode monitoring. Reefer dapat mempertahankan set temperature dalam kondisi operasi yang sesuai, tetapi bukan pengganti penyiapan produk secara benar maupun proses temperature control sebelum stuffing. Shipper perlu memberikan spesifikasi barang yang akurat. Equipment dan routing harus disetujui carrier/terminal. Jangan menjamin suhu tertentu, umur simpan produk atau ketersediaan reefer tanpa requirement terverifikasi dan booking.', 'https://www.imo.org/en/ourwork/safety/pages/ctu-code.aspx')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- cfs-lcl-handling
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('cfs-lcl-handling', 'operations', 'CFS, consolidation and deconsolidation', 'CFS, consolidation dan deconsolidation', 'A Container Freight Station (CFS) can receive LCL cargo, measure and inspect packages, consolidate multiple shipments into a container, or unpack and sort them at destination. Cargo acceptance, warehouse cut-off, stuffing/unstuffing, palletization, storage, destination delivery order and local fees vary by consolidator and service contract. The LCL freight rate alone may omit origin or destination CFS charges. Cargo dimensions, stacking and packaging should be verified at the point of receipt. Ask which CFS, handling terms and free-storage arrangements apply rather than assuming a universal tariff.', 'Container Freight Station (CFS) dapat menerima LCL, menimbang/mengukur koli, mengonsolidasikan beberapa shipment ke container, atau membuka dan memilah barang di tujuan. Ketentuan receiving, warehouse cut-off, stuffing/unstuffing, palletisasi, storage, delivery order serta local charges berbeda menurut consolidator dan kontrak. Tarif LCL ocean freight saja mungkin belum mencakup biaya CFS origin/destination. Dimensi, stacking dan packing harus diverifikasi saat receiving. Tanyakan CFS, ketentuan handling dan free storage yang berlaku, jangan menggunakan tarif universal.', 'https://fiata.org/resources/')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- fiata-documents
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('fiata-documents', 'documentation', 'FIATA transport and forwarder documents', 'Dokumen forwarder FIATA', 'FIATA maintains standardized forwarder documents including the Forwarders Certificate of Receipt (FCR), Forwarders Certificate of Transport (FCT), Warehouse Receipt (FWR), negotiable FIATA Multimodal Transport Bill of Lading (FBL), and non-negotiable FIATA Multimodal Transport Waybill (FWB). These have different legal and practical uses; an FCR is not the same as a negotiable transport bill. Actual issuance may depend on authorization, terms and applicable rules. Do not claim VORA can issue a FIATA-branded form or has special authorization unless documented internally.', 'FIATA menyediakan dokumen standar forwarder seperti Forwarders Certificate of Receipt (FCR), Forwarders Certificate of Transport (FCT), Warehouse Receipt (FWR), negotiable FIATA Multimodal Transport Bill of Lading (FBL), dan non-negotiable FIATA Multimodal Transport Waybill (FWB). Fungsi hukum/operasionalnya berbeda; FCR bukan pengganti negotiable transport bill. Penerbitan dokumen tertentu bergantung otorisasi, syarat dan ketentuan yang berlaku. Jangan mengklaim VORA berwenang menerbitkan formulir berlogo FIATA atau memiliki otorisasi khusus tanpa bukti internal.', 'https://fiata.org/resources/')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- oversize-route-survey
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('oversize-route-survey', 'operations', 'Route survey and permits for oversized cargo', 'Route survey dan izin oversize cargo', 'Oversized, overweight and heavy-lift inland movements can require a route survey covering road/bridge limits, turning radii, gradients, overhead obstructions, axle load distribution, police/escort requirements and site access. Trailer selection must match payload, dimensional envelope and approved axle configurations; transport feasibility cannot be inferred from total tonnage alone. The required permits vary by jurisdiction. Before quoting a final trucking or rigging solution, confirm package drawings, pickup/delivery site conditions, exact route, permits, equipment and contractor engineering acceptance.', 'Pergerakan kargo oversize/overweight di darat bisa membutuhkan route survey untuk memeriksa batas jalan/jembatan, radius putar, kemiringan, hambatan overhead, distribusi axle load, escort dan akses site. Pemilihan trailer harus sesuai payload, dimensi, konfigurasi axle yang diizinkan dan rute; kelayakan tidak bisa ditentukan dari tonase saja. Izin berbeda menurut wilayah. Sebelum final trucking atau rigging quotation, periksa drawing, kondisi lokasi pickup/delivery, rute, perizinan, equipment serta persetujuan engineering kontraktor.', 'https://www.imo.org/en/ourwork/safety/pages/cargosecuring-default.aspx')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- tracking-pod
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('tracking-pod', 'operations', 'Shipment tracking, delivery order and POD', 'Tracking shipment, delivery order dan POD', 'A shipment reference (booking, B/L, AWB or carrier tracking number) enables status investigation, but an AI assistant without a live carrier/operations integration cannot confirm the current location or arrival status. Delivery Order (D/O) is a cargo-release instruction used in some transport and terminal workflows, subject to carrier and customs requirements. Proof of Delivery (POD) records delivery/receipt and may capture exceptions or damage; it does not automatically resolve all claims or discrepancies. Ask customers to provide the tracking reference through an authorized channel and refer live status checks to the operations team.', 'Referensi booking, B/L, AWB atau tracking carrier membantu pencarian status, tetapi agent AI tanpa koneksi live ke carrier/operations tidak bisa memastikan lokasi atau tanggal tiba terkini. Delivery Order (D/O) adalah instruksi release cargo pada alur carrier/terminal tertentu dengan syarat customs dan dokumen yang berlaku. Proof of Delivery (POD) mencatat penerimaan/delivery dan dapat memuat catatan selisih/kerusakan; POD tidak otomatis menutup semua potensi klaim. Minta customer menyampaikan referensi melalui kanal resmi, kemudian arahkan pemeriksaan status real-time kepada tim operasional.', 'https://fiata.org/resources/')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- valuation-origin
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('valuation-origin', 'customs', 'Customs valuation, origin and preference', 'Customs valuation, origin dan fasilitas tarif', 'Customs valuation, non-preferential origin and preferential tariff eligibility are distinct questions. Invoice value alone may require adjustments under the importing jurisdiction''s valuation rules. Origin preference under a trade agreement usually requires the product to satisfy applicable rules of origin plus valid supporting documents; shipment from a country does not automatically prove originating status. Duties, tax rates and origin forms vary by jurisdiction and trade agreement. Avoid guaranteeing preferential duty or duty-free treatment without classification, production/origin evidence and current customs confirmation.', 'Customs valuation, negara asal non-preferensi dan fasilitas tarif preferensi adalah tiga persoalan berbeda. Nilai invoice mungkin memerlukan penyesuaian sesuai aturan customs valuation negara impor. Fasilitas asal barang dari perjanjian dagang umumnya mensyaratkan rules of origin serta dokumen pendukung yang sah; barang dikirim dari suatu negara tidak otomatis berarti berstatus originating dari negara tersebut. Tarif bea/pajak dan formulir asal barang berbeda menurut negara/perjanjian. Jangan menjamin tarif preferensi atau bebas bea tanpa HS classification, bukti produksi/asal dan verifikasi customs terkini.', 'https://www.wcoomd.org/en/topics/nomenclature/overview/harmonized_system_faq.aspx')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- special-handling-acceptance
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('special-handling-acceptance', 'operations', 'Special cargo acceptance is case-specific', 'Persetujuan special cargo harus per kasus', 'Dangerous goods, perishables, live animals, high-value cargo, oversized machinery, batteries and temperature-sensitive shipments often need a carrier-specific acceptance review. General service categories or website descriptions are not a guarantee of legal eligibility, equipment, space, insurance or acceptance. Ask for the correct commodity name, actual dimensions/weight, packaging, SDS and UN details if applicable, special handling requirements, origin/destination, shipment date, and relevant permits. State explicitly which facts require confirmation by the team and carrier before making a commitment.', 'Dangerous goods, perishable, live animals, high-value cargo, mesin oversize, baterai dan temperature-sensitive cargo sering memerlukan acceptance review dari carrier terkait. Kategori layanan umum atau deskripsi website tidak menjamin kelayakan hukum, equipment, space, insurance maupun penerimaan. Minta nama barang yang benar, dimensi/berat aktual, packing, SDS dan data UN jika berlaku, persyaratan handling, origin/destination, tanggal shipment serta izin terkait. Jelaskan bagian yang masih harus dikonfirmasi tim dan carrier sebelum ada komitmen.', 'https://fiata.org/resources/')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- rfq-communication
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('rfq-communication', 'operations', 'Accurate, useful customer communication', 'Komunikasi customer logistics yang akurat', 'When a visitor asks whether a shipment is possible, distinguish technical feasibility, regulatory eligibility, carrier acceptance and confirmed availability. Give a direct provisional answer when there is sufficient general knowledge, then request the most useful missing detail. Never create fictitious quotations, transit guarantees, tracking events, permit results or carrier bookings. A customer-facing answer should sound natural in the visitor''s language, avoid jargon overload, not expose internal source URLs or citations, and clearly say when VORA''s team must confirm a specific service.', 'Saat pengunjung bertanya apakah shipment bisa ditangani, bedakan kelayakan teknis, izin/regulasi, acceptance carrier dan availability yang sudah dikonfirmasi. Berikan jawaban awal secara langsung jika informasi umum cukup, kemudian tanyakan data paling relevan yang belum ada. Jangan membuat quotation palsu, jaminan transit time, peristiwa tracking, hasil izin atau booking carrier fiktif. Jawaban customer harus natural sesuai bahasanya, tidak dipenuhi jargon atau sumber rujukan/sitasi internal, serta menjelaskan bila service spesifik perlu dikonfirmasi tim VORA.', 'https://fiata.org/resources/')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
END $vora_seed$;

-- ---------------------------------------------------------------------------
-- 0036_agent_logistics_special_cargo.sql
-- ---------------------------------------------------------------------------
-- VORA Agent supplemental logistics knowledge: risk, DG, reefer, OOG, customs, licenses and costs.
-- Authoritative references are retained only as internal metadata. Never reveal citations or source URLs to customers.
-- Run after migrations 0033, 0034 and 0035. Idempotent; existing documents are never overwritten.
-- Regulations, carrier acceptance, taxes and permits can change; live official verification remains mandatory.
DO $vora_safety_seed$
DECLARE v_id bigint;
BEGIN
  -- risk-dg-classification
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('risk-dg-classification', 'operations', 'DG identification and classification', 'Identifikasi dan klasifikasi Dangerous Goods', 'Dangerous Goods (DG) identification is substance-specific, not based on a generic product label. Request exact product identity, SDS including Section 14 where available, applicable UN number, proper shipping name, class/division, packing group where assigned, net quantity, packaging type, and mode. SDS can be incomplete or outdated and is not conclusive carrier approval. Check current IMDG for sea and ICAO/IATA DGR for air, plus operator variations. DG bookings require an RFQ and qualified acceptance review.', 'Identifikasi Dangerous Goods (DG) harus berdasarkan produk yang spesifik, bukan nama dagang umum. Minta identitas produk, SDS termasuk Section 14 bila tersedia, UN number, proper shipping name, class/division, packing group jika berlaku, jumlah neto, jenis kemasan dan moda. SDS bisa tidak lengkap atau sudah usang dan bukan bukti persetujuan carrier. Validasi IMDG untuk laut serta ICAO/IATA DGR untuk udara beserta aturan operator. Arahkan booking DG ke Request Quote untuk review.', 'https://www.imo.org/en/publications/pages/imdg%20code.aspx')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- risk-charcoal-2026
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('risk-charcoal-2026', 'operations', 'Charcoal sea freight: IMDG 42-24 UN 1361', 'Charcoal laut: IMDG 42-24 UN 1361', 'As of 1 January 2026, IMDG Amendment 42-24 is mandatory for sea transport. Charcoal of animal or vegetable origin, including many coconut-shell and wood charcoals, falls under UN 1361 CARBON, animal or vegetable origin, hazard Class 4.2; Special Provision 978 applies. Requirements can include production/conditioning history, temperature controls, approved packaging, marking, declaration, and container packing restrictions. This is NOT an automatic acceptance by any line. Seek SDS, composition/process, dates, packing photos, origin and destination, then submit an RFQ for carrier/DG review. Do not call this an ordinary non-DG FCL shipment.', 'Sejak 1 Januari 2026, IMDG Amendment 42-24 wajib untuk pengiriman laut. Charcoal asal hewani atau nabati, termasuk banyak jenis arang batok kelapa dan kayu, masuk UN 1361 CARBON, animal or vegetable origin, Class 4.2; Special Provision 978 berlaku. Persyaratannya dapat mencakup riwayat produksi/conditioning, kontrol temperatur, kemasan approved, marking, deklarasi dan ketentuan stuffing. Ini bukan jaminan diterima shipping line. Minta SDS, komposisi/proses, tanggal produksi/packing, foto kemasan, origin dan tujuan, lalu arahkan ke Request Quote untuk review DG dan carrier. Jangan menyebutnya FCL non-DG biasa.', 'https://www.hapag-lloyd.com/en/services-information/news/2025/12/new-imdg-regulation--mandatory-dangerous-goods-declaration-for-c.html')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- risk-activated-carbon
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('risk-activated-carbon', 'operations', 'Activated carbon differs from charcoal', 'Activated carbon berbeda dari charcoal', 'Activated carbon and charcoal are not interchangeable DG descriptions. IMDG Amendment 42-24 includes the UN 1362 CARBON, ACTIVATED entry and Special Provision 979, with distinct conditions under which some materials may be exempt. Steam-activated and chemically activated products can have different treatment. Ask for manufacturing method, composition, SDS and relevant assessment; do not automatically assign UN 1361 or assume non-DG status. Route the shipment to Request Quote for classification and carrier acceptance.', 'Activated carbon dan charcoal bukan deskripsi DG yang bisa disamakan. IMDG Amendment 42-24 memuat UN 1362 CARBON, ACTIVATED dan Special Provision 979, dengan kondisi tertentu yang dapat memberikan pengecualian bagi material spesifik. Perlakuan activated carbon dari proses steam dan chemical dapat berbeda. Minta metode produksi, komposisi, SDS dan hasil penilaian terkait; jangan otomatis menetapkan UN 1361 atau menganggap non-DG. Arahkan Request Quote untuk pemeriksaan klasifikasi dan acceptance carrier.', 'https://www.imo.org/en/publications/pages/imdg%20code.aspx')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- risk-lithium-battery
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('risk-lithium-battery', 'operations', 'Lithium batteries: air and ocean acceptance', 'Baterai lithium: penerimaan udara dan laut', 'Lithium-ion, lithium-metal, sodium-ion and equipment containing batteries require product-specific transport assessment. Relevant factors include chemistry, Wh or lithium content, whether batteries are standalone, packed with or contained in equipment, condition, UN classification, testing documentation, state of charge where applicable, packaging and carrier restrictions. Damaged or recalled batteries pose additional restrictions and must not be assumed shippable. Ask for battery specification sheets and packing details; route RFQ for airline or ocean carrier approval.', 'Baterai lithium-ion, lithium-metal, sodium-ion dan perangkat yang mengandung baterai perlu pemeriksaan khusus. Informasi relevan meliputi kimia baterai, Wh atau lithium content, baterai standalone/packed with/contained in equipment, kondisinya, klasifikasi UN, dokumen pengujian, state of charge bila berlaku, kemasan dan pembatasan carrier. Baterai rusak atau recalled punya pembatasan tambahan dan tidak boleh diasumsikan bisa dikirim. Minta spesifikasi baterai serta kemasan, lalu Request Quote untuk approval carrier.', 'https://www.iata.org/en/programs/cargo/dangerous-goods')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- risk-chemicals
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('risk-chemicals', 'operations', 'Chemicals, solvents, paints and adhesives', 'Bahan kimia, solvent, cat dan adhesive', 'Solvents, coatings, paints, adhesives and cleaners may be flammable, corrosive, toxic, environmentally hazardous or non-regulated depending on formulation. Do not assign a DG class solely from a commercial product name. Request an up-to-date SDS, flash point where relevant, composition, UN/packing group information, quantity, packaging and intended transport mode. Carrier, terminal and storage acceptance are subject to formal review. Direct the customer to Request Quote.', 'Solvent, coating, cat, perekat dan bahan pembersih dapat bersifat flammable, corrosive, toxic, berbahaya bagi lingkungan atau non-regulated tergantung formulasi. Jangan menentukan DG class hanya dari nama dagang. Minta SDS terbaru, flash point bila relevan, komposisi, informasi UN/packing group, jumlah, kemasan dan moda. Acceptance carrier, terminal dan gudang harus direview. Arahkan customer ke Request Quote.', 'https://www.imo.org/en/publications/pages/imdg%20code.aspx')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- risk-gases-aerosol
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('risk-gases-aerosol', 'operations', 'Gas cylinders and aerosol handling', 'Penanganan gas cylinder dan aerosol', 'Compressed/liquefied gases and aerosols can be DG with pressure-related risks. Classifications, pressure, composition, fill state, valves, caps, packaging and stowage conditions vary. Never assume empty gas cylinders are automatically non-DG without evidence of proper depressurization and cleaning as applicable. Obtain SDS, cylinder specifications and photos before requesting carrier approval through RFQ.', 'Gas bertekanan/gas cair dan aerosol dapat termasuk DG dengan risiko tekanan. Klasifikasi, tekanan, komposisi, kondisi isi, valve, cap, packing dan stowage berbeda menurut produknya. Tabung yang disebut kosong tidak otomatis non-DG tanpa bukti depressurization/pembersihan bila relevan. Minta SDS, spesifikasi tabung dan foto sebelum permintaan approval carrier melalui RFQ.', 'https://www.iata.org/en/programs/cargo/dangerous-goods')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- risk-dry-ice
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('risk-dry-ice', 'operations', 'Dry ice / UN 1845 in transport', 'Dry ice / UN 1845 dalam pengiriman', 'Dry ice (solid carbon dioxide, UN 1845) may be used to cool perishables, but creates asphyxiation and pressure risks. Airline limits, ventilation, package marking, net dry-ice mass and documentation depend on the current rules and operator. Do not confuse refrigerant classification with the classification of the product inside the package. Obtain dry-ice quantity, packaging and cargo details; submit Request Quote for a compliant handling plan.', 'Dry ice (karbon dioksida padat, UN 1845) sering dipakai untuk menjaga suhu produk, tetapi memiliki risiko asphyxiation dan tekanan. Batas airline, ventilasi, marking, berat neto dry ice dan dokumen mengikuti aturan serta operator yang berlaku. Klasifikasi refrigerant tidak otomatis sama dengan barang di dalam kemasan. Minta jumlah dry ice, spesifikasi packing dan detail cargo, lalu Request Quote untuk penanganan yang sesuai.', 'https://www.iata.org/en/programs/cargo/dangerous-goods')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- risk-dg-warehouse
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('risk-dg-warehouse', 'operations', 'Dangerous goods storage and segregation', 'Penyimpanan dan segregasi Dangerous Goods', 'DG storage suitability depends on hazard classification, permitted quantities, fire protection, ventilation, segregation, spill containment, local licences and facility operations. A general warehouse is not automatically authorized for all DG classes. Ask for SDS, quantities, storage duration, pallet/rack configuration and environmental conditions. Do not promise that VORA owns a DG-licensed facility; request a formal capability and pricing review.', 'Kelayakan gudang DG bergantung pada klasifikasi bahaya, kuantitas yang diizinkan, fire protection, ventilasi, segregasi, spill containment, izin lokal dan prosedur operasional. Gudang umum tidak otomatis cocok untuk semua kelas DG. Minta SDS, kuantitas, durasi penyimpanan, konfigurasi pallet/rack dan kondisi lingkungan. Jangan mengklaim VORA memiliki gudang berizin DG tanpa konfirmasi; arahkan penilaian capability dan biaya lewat Request Quote.', 'https://www.imo.org/en/publications/pages/imdg%20code.aspx')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- risk-dg-shipper-docs
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('risk-dg-shipper-docs', 'documentation', 'DG booking documentation and declarations', 'Dokumen booking dan deklarasi DG', 'DG shipment documents may include an appropriate transport dangerous goods declaration, applicable SDS, container or vehicle packing certificate, shipping instructions, certificates and carrier-specific acceptance forms. Requirements differ by mode, UN entry, quantity, packaging and jurisdictions. Trained and authorized parties must prepare/verify declarations; an AI response is not a transport compliance certification. Collect available files through the formal RFQ process.', 'Dokumen shipment DG dapat mencakup dangerous goods declaration yang benar, SDS bila diperlukan, container/vehicle packing certificate, shipping instruction, sertifikat dan form acceptance spesifik carrier. Syarat berbeda menurut moda, UN entry, jumlah, packing dan negara. Pihak yang kompeten/berwenang harus menyiapkan dan memverifikasi deklarasi; jawaban AI bukan sertifikasi kepatuhan. Kumpulkan dokumen yang tersedia lewat proses RFQ resmi.', 'https://www.imo.org/en/publications/pages/imdg%20code.aspx')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- risk-dg-surcharge
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('risk-dg-surcharge', 'operations', 'DG freight and surcharges are case-specific', 'Freight dan surcharge DG bergantung kasus', 'DG freight may include hazardous cargo acceptance, DG premium, terminal handling, special stowage, survey, safety handling, inland DG trucking, packaging and documentation costs. No fixed percentage or surcharge applies universally. Get actual carrier quotation and list inclusions/exclusions, currency, validity and free time. Direct the request to RFQ rather than guessing a DG premium.', 'Freight DG dapat memiliki biaya acceptance, DG premium, terminal handling, special stowage, survey, safety handling, trucking DG, kemasan dan dokumen. Tidak ada persentase atau surcharge tunggal yang berlaku universal. Minta quotation aktual carrier dan cek inclusions/exclusions, mata uang, validitas dan free time. Arahkan RFQ, jangan menebak premium DG.', 'https://fiata.com/')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- risk-dg-air-2026
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('risk-dg-air-2026', 'operations', 'Air DG reference: IATA DGR 67th edition (2026)', 'Referensi DG udara: IATA DGR edisi 67 (2026)', 'For shipments in 2026, IATA DGR 67th edition and relevant ICAO Technical Instructions, including addenda and operator/state variations, are important references for air DG. Flight/cargo airline restrictions may be stricter than the general rule. An SDS alone does not prove airline acceptance. Ask for correct classification, UN/PI information, quantity per package and packaging certification. Route acceptance and quotation to a specialist.', 'Untuk pengiriman tahun 2026, IATA DGR edisi 67 dan ICAO Technical Instructions yang berlaku, termasuk addendum serta operator/state variations, menjadi rujukan DG udara. Pembatasan airline bisa lebih ketat daripada aturan umum. SDS saja tidak membuktikan airline menerima kargo. Minta klasifikasi, UN/PI, jumlah per kemasan dan sertifikasi packing yang relevan. Arahkan acceptance dan quotation ke spesialis.', 'https://www.iata.org/en/programs/cargo/dangerous-goods')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- special-oog-dimensions
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('special-oog-dimensions', 'operations', 'Out-of-gauge (OOG) dimensional review', 'Review dimensi Out-of-Gauge (OOG)', 'OOG cargo exceeds one or more internal dimensions/limits of a standard container or equipment specification. A flat rack/open top, breakbulk or alternative method may be appropriate only after detailed measurements and load engineering. Request packed length x width x height, gross weight, overhang, CoG, lifting points and photographs/drawings for each piece. Carrier approval and port/road feasibility are not automatic. Direct to Request Quote.', 'Kargo OOG melampaui dimensi atau batas tertentu pada container standar/peralatan. Flat rack/open top, breakbulk atau metode lain baru dapat ditentukan setelah pengukuran dan kajian muatan. Minta panjang x lebar x tinggi saat sudah dipacking, gross weight, overhang, CoG, lifting point serta foto/drawing per piece. Persetujuan carrier dan kelayakan akses pelabuhan/jalan tidak otomatis. Arahkan Request Quote.', 'https://voraworld.id/en/request-quote')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- special-flat-rack
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('special-flat-rack', 'operations', 'Flat rack: securing and equipment acceptance', 'Flat rack: securing dan persetujuan equipment', 'Flat racks can carry cargo exceeding standard container side or height dimensions, subject to equipment capacity, allowable concentrated loads, overhang, lashing and carrier stowage. Nominal payload is not enough to establish suitability. Provide drawings, weight distribution, centre of gravity and proposed securing before planning. Rates and special equipment availability require confirmation by RFQ.', 'Flat rack dapat digunakan untuk kargo yang melebihi sisi/tinggi container standar, dengan batas kapasitas, concentrated load, overhang, lashing dan stowage carrier. Payload nominal saja belum membuktikan kesesuaian. Sertakan drawing, distribusi berat, center of gravity dan rencana securing. Tarif dan availability special equipment harus diverifikasi lewat RFQ.', 'https://voraworld.id/en/request-quote')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- special-open-top
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('special-open-top', 'operations', 'Open top container: top-loading and overheight', 'Open top: top-loading dan muatan overheight', 'Open-top containers can be useful for top loading and certain overheight cargo, subject to door opening, payload, roof/bow constraints, tarpaulin covering and carrier approval. Overheight is not automatically acceptable on every vessel or lane. Ask dimensions, crane lift plan, packing, weather exposure limitations and stowage restrictions. Direct the case to Request Quote.', 'Open top dapat digunakan untuk top-loading atau sebagian muatan overheight, bergantung bukaan pintu, payload, struktur bow/roof, penutup terpal dan persetujuan carrier. Muatan overheight belum tentu diterima pada semua vessel atau rute. Minta dimensi, rencana crane lift, packing, batas paparan cuaca dan ketentuan stowage. Arahkan Request Quote.', 'https://voraworld.id/en/request-quote')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- special-breakbulk
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('special-breakbulk', 'operations', 'Breakbulk versus containerized transport', 'Breakbulk dibanding transport container', 'Breakbulk cargo is shipped as individual pieces instead of standard container units. Suitable vessel/route selection depends on pieces, lifting weights, dimensions, cargo readiness, lashing, underdeck/on-deck suitability and port cranes. It is not the same as chartering a whole vessel. Request a packing list with dimensions/weight per piece and intended loading/discharge ports, then quote after vendor review.', 'Breakbulk mengangkut barang sebagai piece tersendiri, bukan dalam unit container standar. Pemilihan vessel/rute bergantung jumlah piece, lifting weight, dimensi, kesiapan kargo, lashing, kebutuhan underdeck/on-deck dan crane pelabuhan. Breakbulk tidak sama dengan charter seluruh kapal. Minta packing list berisi dimensi/berat per piece dan port muat/bongkar, lalu quotation setelah review vendor.', 'https://voraworld.id/en/request-quote')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- special-heavy-lift
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('special-heavy-lift', 'operations', 'Heavy-lift: engineering and safe lifting requirements', 'Heavy-lift: engineering dan kebutuhan lifting aman', 'Heavy-lift feasibility depends on gross lift weight including lifting gear, centre of gravity, lifting points, sling angles, spreader beams, tandem lift feasibility, crane configuration, ground bearing pressure and lifting radius. A crane rated capacity at one radius does not guarantee suitability at the actual radius. Ask certified weights, drawings, rigging/lifting plans and site constraints. Direct to RFQ for engineered evaluation.', 'Kelayakan heavy-lift bergantung berat angkat termasuk gear, center of gravity, lifting point, sudut sling, spreader beam, kemungkinan tandem lift, konfigurasi crane, ground bearing pressure dan radius angkat. Kapasitas nominal crane pada satu radius belum tentu berlaku pada radius aktual. Minta berat terverifikasi, drawing, rigging/lifting plan dan kendala lokasi. Arahkan RFQ untuk kajian engineering.', 'https://voraworld.id/en/request-quote')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- special-transformer
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('special-transformer', 'operations', 'Power transformers and industrial machinery shipping', 'Pengiriman power transformer dan machinery industri', 'Power transformers and large machinery often require a multi-piece cargo survey, main tank/accessory segregation, packed weights, CoG, lifting/lashing points, preservation measures and transport vibration limits. Oil content and related safety documentation may affect classification or handling. Route surveys, port lifting, heavy transport and weather protection must be verified. Do not assert a vessel can carry the unit before engineering review; invite a detailed RFQ.', 'Power transformer dan mesin berukuran besar sering memerlukan survey per piece, pemisahan main tank/accessories, berat packing, CoG, lifting/lashing point, proteksi preservation dan batas getaran. Kandungan oil dan dokumen keselamatan dapat memengaruhi klasifikasi/handling. Route survey, pengangkatan di pelabuhan, heavy transport dan perlindungan cuaca harus dicek. Jangan memastikan vessel bisa mengangkut sebelum kajian engineering; arahkan RFQ lengkap.', 'https://voraworld.id/en/request-quote')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- special-road-survey
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('special-road-survey', 'operations', 'Project cargo road and port route survey', 'Route survey jalan dan pelabuhan project cargo', 'A heavy or oversized cargo road survey considers axle loads, turning radius, bridges, overhead obstructions, road permits, gradients, overhead wires, escort requirements and traffic restrictions. Port-side constraints include gate clearance, quay load limits, crane reach and storage space. Road travel distance alone cannot confirm delivery feasibility. RFQ should include origin/destination addresses, packed cargo drawings, axle distribution where known and required schedule.', 'Route survey heavy/oversize memeriksa axle load, turning radius, jembatan, halangan ketinggian, izin jalan, tanjakan, kabel udara, kebutuhan escort dan pembatasan lalu lintas. Kendala di pelabuhan meliputi clearance gate, batas beban quay, jangkauan crane dan ruang penyimpanan. Jarak jalan saja tidak menentukan kelayakan. RFQ perlu alamat origin/tujuan, drawing cargo saat packing, distribusi axle bila ada dan jadwal.', 'https://voraworld.id/en/request-quote')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- special-lashing
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('special-lashing', 'operations', 'Cargo lashing, securing and centre of gravity', 'Lashing, securing dan center of gravity kargo', 'Securing arrangements depend on cargo shape, weight, centre of gravity, friction, acceleration, vessel/stowage position and securing hardware capacity. Load diagrams and a qualified lashing plan are essential for complex project cargo. Never infer sufficient lashing from the number of chains alone. Obtain approved drawings, packing/transport base and handling restrictions before providing a special handling quote.', 'Skema securing dipengaruhi bentuk, berat, center of gravity, friksi, akselerasi, posisi stowage serta kapasitas perangkat lashing. Load diagram dan lashing plan dari pihak kompeten diperlukan untuk project cargo kompleks. Jumlah rantai saja tidak membuktikan securing cukup. Minta drawing terverifikasi, transport base/packing dan pembatasan handling sebelum quotation khusus.', 'https://voraworld.id/en/request-quote')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- special-roro-charter
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('special-roro-charter', 'operations', 'RoRo and charter feasibility', 'Kelayakan RoRo dan charter vessel', 'RoRo requires suitable rolling cargo, ramp load limits, vessel dimensions, terminal access and securing plans. Charter vessel feasibility depends on laycan, vessel market, port restrictions, cargo weight/volume, draft and contractual terms. A full charter differs commercially from a single breakbulk slot. Collect cargo specification, port pair, readiness and schedule flexibility, then Request Quote. Never promise availability.', 'RoRo memerlukan muatan rolling yang sesuai, batas ramp, ukuran kapal, akses terminal dan rencana securing. Kelayakan charter vessel bergantung laycan, pasar kapal, batas pelabuhan, volume/berat cargo, draft dan ketentuan kontrak. Full charter berbeda dari booking slot breakbulk. Kumpulkan spesifikasi cargo, port asal/tujuan, readiness dan fleksibilitas jadwal, lalu Request Quote. Jangan menjanjikan availability.', 'https://voraworld.id/en/request-quote')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- special-fragile-high-value
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('special-fragile-high-value', 'operations', 'Fragile, sensitive and high-value cargo', 'Kargo fragile, sensitif dan high-value', 'Fragile electronics, calibrated machinery, artworks and high-value products may require shock/tilt indicators, vibration limits, humidity control, custom crates, security, survey and special insurance. Packaging suitability cannot be determined from dimensions alone. Request declared value, handling constraints, packing drawings and pickup/delivery conditions, then arrange an RFQ and specialist assessment.', 'Elektronik sensitif, mesin kalibrasi, karya seni dan barang high-value dapat memerlukan shock/tilt indicator, batas getaran, kontrol kelembapan, crate khusus, security, survey dan asuransi tambahan. Kesesuaian packing tidak cukup dinilai dari dimensi. Minta nilai barang, batas handling, gambar kemasan dan kondisi pickup/delivery, lalu RFQ serta review specialist.', 'https://voraworld.id/en/request-quote')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- reefer-rfq
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('reefer-rfq', 'operations', 'Reefer and cold-chain RFQ inputs', 'Data RFQ untuk reefer dan cold chain', 'Reefer shipments require exact commodity, quantity, packing, origin/destination, pickup date, target carrying temperature (setpoint), allowable excursion range, ventilation/humidity requirements and container size. The refrigeration unit maintains temperature but is generally not meant to rapidly pre-cool hot cargo. Temperature capability and equipment availability depend on actual equipment. Send details via Request Quote for feasibility, PTI and pricing.', 'Pengiriman reefer membutuhkan komoditas spesifik, jumlah, packing, origin/tujuan, tanggal pickup, target suhu (setpoint), batas toleransi, kebutuhan ventilasi/kelembapan dan ukuran container. Mesin reefer menjaga suhu dan umumnya bukan untuk mendinginkan cepat kargo yang masih panas. Kemampuan suhu dan ketersediaan equipment bergantung unit aktual. Kirim data lewat Request Quote untuk feasibility, PTI dan harga.', 'https://www.maersk.com/support/faqs/reefer-container-temperature-range')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- reefer-pti
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('reefer-pti', 'operations', 'Reefer pre-trip inspection (PTI)', 'Pre-trip inspection (PTI) container reefer', 'A pre-trip inspection (PTI) helps establish that reefer machinery and relevant components function before cargo loading. The booking should specify required carrying temperature, ventilation, humidity, commodity, stuffing place and timing. PTI does not by itself guarantee uninterrupted cold-chain temperatures throughout the journey. Confirm provider-specific procedures and available equipment through the RFQ process.', 'Pre-trip inspection (PTI) membantu memastikan mesin reefer dan komponen terkait berfungsi sebelum stuffing. Booking sebaiknya menyebut carrying temperature, ventilasi, kelembapan, komoditas, lokasi dan waktu stuffing. PTI sendiri tidak menjamin suhu selalu terjaga sepanjang perjalanan. Prosedur dan equipment harus dicek ke penyedia melalui RFQ.', 'https://www.maersk.com/support/faqs/reefer-container-temperature-range')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- reefer-electricity
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('reefer-electricity', 'operations', 'Reefer power supply and monitoring', 'Pasokan listrik dan monitoring reefer', 'Reefer cargo can require terminal plug-in electricity, suitable inland gensets, compatible electrical connections, temperature logging and a contingency plan for delays or power failures. Power availability must be checked across trucking, port, vessel and destination handoffs. A temperature setpoint alone is not proof the shipment will hold specification. Discuss power arrangements and monitoring with the operations team via RFQ.', 'Kargo reefer bisa membutuhkan listrik plug-in di terminal, genset saat trucking, koneksi kelistrikan yang sesuai, temperature logger dan rencana cadangan saat delay atau gangguan listrik. Ketersediaan daya perlu dicek dari trucking, pelabuhan, vessel hingga serah terima tujuan. Setpoint saja bukan jaminan suhu selalu sesuai. Diskusikan skema power dan monitoring melalui RFQ.', 'https://www.maersk.com/support/faqs/reefer-container-temperature-range')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- reefer-fresh-produce
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('reefer-fresh-produce', 'operations', 'Fresh produce ventilation and humidity', 'Buah dan sayur segar: ventilasi dan kelembapan', 'Fresh produce may continue respiration during transport and can require crop-specific ventilation, humidity and ripening management in addition to temperature control. Different commodities have incompatible storage requirements and should not automatically be consolidated. Ask cultivar/commodity, harvest condition, desired transit duration, packaging, setpoint, ventilation and phytosanitary needs. Use Request Quote for cold-chain assessment.', 'Produk buah/sayur segar dapat tetap berespirasi selama pengiriman dan memerlukan ventilasi, kelembapan serta pengelolaan pematangan di samping suhu. Setiap komoditas memiliki syarat berbeda dan tidak otomatis cocok dikonsolidasikan. Minta jenis komoditas, kondisi panen, target transit, kemasan, setpoint, ventilasi dan kebutuhan phytosanitary. Gunakan Request Quote untuk penilaian cold chain.', 'https://www.maersk.com/support/faqs/reefer-container-temperature-range')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- reefer-pharma
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('reefer-pharma', 'operations', 'Temperature-sensitive pharmaceuticals', 'Produk farmasi yang sensitif suhu', 'Pharmaceutical cold-chain cargo may need validated packaging, qualified handling processes, temperature mapping, data loggers, documented excursion responses and regulatory permits. Carrier handling does not automatically establish compliance with product-specific GDP requirements. Do not promise suitability for vaccines or medicines without qualified specialist review. Request Quote with exact temperature profile, pack-out, shipment quantity and route.', 'Kargo farmasi cold chain dapat membutuhkan validated packaging, proses handling yang qualified, temperature mapping, data logger, respons excursion terdokumentasi serta izin regulator. Handling carrier tidak otomatis membuktikan kepatuhan GDP produk. Jangan menjanjikan kelayakan vaksin/obat tanpa review specialist. Request Quote harus memuat profil suhu, pack-out, jumlah dan rute.', 'https://www.iata.org/en/programs/cargo/dangerous-goods')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- reefer-frozen-food
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('reefer-frozen-food', 'operations', 'Frozen foods and thawing risk', 'Frozen food dan risiko pencairan', 'Frozen food transport requires a defined product-specific temperature profile, preconditioned cargo, adequate airflow, acceptable excursion times and a contingency plan. Temperature requirements must come from the shipper/product standard, not an arbitrary generic reefer setpoint. Ask packing, storage history, readiness, route, transit requirement and logging need. Route to Request Quote to assess equipment and handling.', 'Pengiriman frozen food membutuhkan profil suhu sesuai produknya, cargo sudah pada kondisi yang diperlukan saat loading, airflow memadai, batas excursion dan contingency plan. Persyaratan suhu harus berasal dari standar produk/shipper, bukan angka setpoint yang ditebak. Minta packing, riwayat penyimpanan, readiness, rute, kebutuhan transit dan logging. Arahkan Request Quote untuk penilaian equipment dan handling.', 'https://www.maersk.com/support/faqs/reefer-container-temperature-range')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- customs-hs-classification
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('customs-hs-classification', 'customs', 'HS classification and BTKI validation', 'Klasifikasi HS Code dan validasi BTKI', 'HS code classification must follow the actual goods description, composition, function, technical specifications and applicable tariff nomenclature; a commercial name alone is insufficient. Import duty, taxes, licensing and preferential eligibility may differ by classification and origin. For Indonesia, use current BTKI/INSW references and consult customs professionals for ambiguous goods. AI cannot issue a binding tariff ruling.', 'Klasifikasi HS Code harus berdasarkan deskripsi barang, komposisi, fungsi, spesifikasi teknis dan nomenklatur tarif yang berlaku; nama dagang saja tidak cukup. Bea masuk, pajak, lartas dan preferensi tarif dapat berbeda menurut klasifikasi dan origin. Untuk Indonesia cek BTKI/INSW terbaru dan konsultasikan barang ambigu ke ahli kepabeanan. AI tidak dapat mengeluarkan penetapan tarif yang mengikat.', 'https://www.insw.go.id/intr')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- customs-lartas-intr
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('customs-lartas-intr', 'customs', 'Indonesia Lartas: live check via INSW INTR', 'Lartas Indonesia: cek terkini via INSW INTR', 'Indonesia export/import restrictions (Lartas) and required licences are commodity and HS-code specific. Use the Indonesia National Trade Repository (INTR) within INSW to check import/export regulations, then verify current ministry rules, any border/post-border handling and permit validity. A historic shipping experience or old invoice is not sufficient evidence that a permit remains valid. Ask for exact HS, specifications and direction of trade; refer Request Quote for case assessment.', 'Larangan/pembatasan (Lartas) ekspor-impor Indonesia bergantung komoditas dan HS Code. Periksa regulasi ekspor/impor melalui INTR pada INSW, lalu validasi aturan kementerian terbaru, perlakuan border/post-border dan masa berlaku izin. Pengalaman shipment lama atau invoice lama bukan bukti izin masih berlaku. Minta HS Code, spesifikasi barang dan arah perdagangan lalu arahkan Request Quote untuk review.', 'https://www.insw.go.id/intr')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- customs-import-pib
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('customs-import-pib', 'customs', 'Indonesia import: PIB and customs release', 'Impor Indonesia: PIB dan persetujuan pengeluaran', 'Indonesia imports generally require a customs declaration (PIB/BC 2.0 for relevant import-for-use procedures), supporting documents, accurate tariff and customs valuation, import restrictions checks, and applicable duty/tax payment or facilities. The electronic filing flow and examination outcome depend on the applicable customs system and regime. SPPB is a release approval in relevant procedures, not the same as a shipping line delivery order. Never guarantee customs release date; ask importer, HS, invoice, packing list, transport documents and permits.', 'Impor Indonesia umumnya memerlukan pemberitahuan pabean (PIB/BC 2.0 pada prosedur impor untuk dipakai yang relevan), dokumen pendukung, klasifikasi tarif dan nilai pabean yang benar, cek lartas, serta pembayaran/fasilitas bea-pajak yang berlaku. Proses elektronik dan pemeriksaan mengikuti sistem/rezim kepabeanan terkait. SPPB merupakan persetujuan pengeluaran pada prosedur terkait, berbeda dari delivery order shipping line. Jangan menjamin tanggal release; minta data importir, HS, invoice, packing list, dokumen transport dan izin.', 'https://www.beacukai.go.id/')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- customs-export-peb
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('customs-export-peb', 'customs', 'Indonesia export: PEB BC 3.0 and NPE', 'Ekspor Indonesia: PEB BC 3.0 dan NPE', 'For Indonesian export procedures where required, exporters/PPJK prepare supporting documents, meet applicable export restrictions, lodge the PEB (BC 3.0) and receive the relevant customs response, including NPE when requirements are met. Some commodities may have export duties or sector-specific requirements. Exact flow can change by export regime and regulation. Do not imply that an invoice or booking alone is equivalent to export clearance. Request Quote for export documentation assistance.', 'Untuk prosedur ekspor Indonesia yang relevan, eksportir/PPJK menyiapkan dokumen pendukung, memenuhi lartas, mengajukan PEB (BC 3.0) dan menerima respons kepabeanan, termasuk NPE ketika persyaratan terpenuhi. Sebagian komoditas dapat dikenai bea keluar atau ketentuan sektoral. Alur bergantung rezim dan regulasi yang berlaku. Invoice atau booking saja bukan persetujuan ekspor. Arahkan Request Quote untuk bantuan dokumen dan clearance.', 'https://www.beacukai.go.id/')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- customs-oss-permits
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('customs-oss-permits', 'customs', 'OSS business permits versus commodity licences', 'Izin usaha OSS dan izin komoditas', 'Business licensing (such as NIB and relevant OSS sector approvals) and per-shipment commodity restrictions serve different purposes. An NIB does not automatically satisfy every import/export product licence or destination-country requirement. Validate the importer/exporter profile, HS code, sector rules, required permits and validity through current official systems. For a real shipment, request documents and route to Request Quote.', 'Izin usaha seperti NIB/OSS dan perizinan komoditas per shipment memiliki fungsi berbeda. NIB tidak otomatis memenuhi seluruh izin impor/ekspor produk atau persyaratan negara tujuan. Periksa profil importir/eksportir, HS Code, aturan sektoral, izin yang wajib dan masa berlakunya melalui sistem resmi terkini. Untuk kasus nyata, minta dokumen dan arahkan Request Quote.', 'https://www.insw.go.id/intr')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- customs-used-machinery
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('customs-used-machinery', 'customs', 'Used machines and goods: import restrictions', 'Mesin dan barang bekas: pembatasan impor', 'Import of used machinery, used goods or certain non-new products into Indonesia may face prohibitions, conditions, technical assessment or permit requirements under changing trade rules. Do not assume that an item can be imported because a similar item previously cleared. Check year/model, condition, technical specifications, HS and current regulations. Request Quote for a compliance feasibility check before shipment dispatch.', 'Impor mesin bekas, barang bekas atau produk tidak baru tertentu ke Indonesia bisa terkena larangan, persyaratan, penilaian teknis atau izin sesuai ketentuan perdagangan yang berubah. Jangan menganggap barang pasti bisa diimpor hanya karena barang serupa pernah lolos. Cek tahun/model, kondisi, spesifikasi teknis, HS dan regulasi terbaru. Request Quote untuk kajian kelayakan sebelum barang dikirim.', 'https://www.insw.go.id/intr')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- customs-destination-country
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('customs-destination-country', 'customs', 'Destination-country importer and export control checks', 'Pemeriksaan importir negara tujuan dan kontrol ekspor', 'Customs and regulatory obligations exist at both origin and destination. Destination import licences, product safety rules, quarantine, sanctions/export controls, end-user restrictions and importer-of-record eligibility may determine if a shipment can proceed. Incoterms such as DDP do not remove these legal requirements. Ask for destination country, product specifications, parties and HS where known; direct to Request Quote for local verification.', 'Kewajiban customs dan regulasi berlaku di origin maupun negara tujuan. Izin impor tujuan, aturan keamanan produk, karantina, sanctions/export controls, pembatasan end-user dan syarat importer of record bisa menentukan kelayakan. Incoterms seperti DDP tidak menghapus kewajiban hukum. Minta negara tujuan, spesifikasi barang, pihak terkait dan HS bila ada; arahkan Request Quote untuk verifikasi lokal.', 'https://iccwbo.org/business-solutions/incoterms-rules/incoterms-2020/')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- customs-quarantine
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('customs-quarantine', 'customs', 'Quarantine and phytosanitary or health certificates', 'Karantina dan sertifikat phytosanitary/health', 'Plant, animal, food, seed and other regulated products can require quarantine inspection, phytosanitary or health certificates, treatment, import permits or destination registrations. Exact requirements depend on species, form, HS code, country pairs and intended use. Never assume that all food cargo requires the same document. Obtain product specification and origin/destination, then Request Quote for current requirement checking.', 'Produk tumbuhan, hewan, pangan, benih dan komoditas tertentu dapat memerlukan pemeriksaan karantina, sertifikat phytosanitary/health, treatment, izin impor atau registrasi negara tujuan. Syarat bergantung spesies, bentuk produk, HS, negara asal/tujuan dan tujuan penggunaan. Jangan menyamaratakan semua pangan membutuhkan dokumen sama. Minta spesifikasi barang dan origin/tujuan lalu Request Quote untuk cek persyaratan terkini.', 'https://www.insw.go.id/intr')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- customs-cert-origin
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('customs-cert-origin', 'documentation', 'Certificate of origin and preferential duty', 'Certificate of Origin dan preferensi bea masuk', 'A Certificate of Origin (COO) may support preferential tariffs only when the goods meet applicable rules of origin and the importing country accepts the relevant form or proof. Not every COO automatically grants duty relief. The agreement, HS code, origin criteria, direct consignment and documentary requirements must be checked. Obtain shipper and importer details plus product/manufacturing information via Request Quote.', 'Certificate of Origin (COO) dapat mendukung tarif preferensi jika barang memenuhi rules of origin dan negara impor menerima bentuk proof yang relevan. COO tidak otomatis memberikan pembebasan/pengurangan bea masuk. Perlu cek skema perjanjian, HS Code, kriteria asal, direct consignment serta persyaratan dokumen. Kumpulkan data shipper/importir dan informasi produksi lewat Request Quote.', 'https://www.insw.go.id/intr')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- customs-valuation
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('customs-valuation', 'customs', 'Customs value and tax estimation principles', 'Prinsip nilai pabean dan estimasi pajak', 'Customs value may require adjustments to commercial invoice prices according to applicable valuation law, transport, insurance and related costs. Duty and import tax depend on HS, country of origin, tariff preferences, customs value and current tax law. Never produce definitive Indonesian import tax rates without validating the current tariff and transaction. For cost estimation, distinguish indicative assumptions from verified charges and refer to Request Quote.', 'Nilai pabean dapat membutuhkan penyesuaian harga invoice sesuai aturan penilaian, transport, asuransi dan biaya terkait. Bea masuk serta pajak impor bergantung HS, origin, preferensi tarif, nilai pabean dan aturan pajak terbaru. Jangan memberikan angka tarif pajak impor definitif tanpa verifikasi tarif dan transaksi. Untuk estimasi pisahkan asumsi indikatif dari biaya terkonfirmasi dan arahkan Request Quote.', 'https://www.insw.go.id/intr')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- customs-customs-inspection
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('customs-customs-inspection', 'customs', 'Customs examination, delay and release', 'Pemeriksaan pabean, delay dan release', 'Customs may select shipments for document review, scanning, physical examination, samples or additional clarification depending on risk and regime. Additional handling, storage or waiting costs may result. An inspection selection does not automatically mean a violation. Never promise a fixed clearance time. Ask for declaration status, case references and requested documents; the operations team should review through a formal inquiry.', 'Bea Cukai dapat memilih pemeriksaan dokumen, scanning, pemeriksaan fisik, sampling atau klarifikasi tambahan sesuai risiko dan rezim. Bisa timbul biaya handling, storage atau tunggu tambahan. Penetapan pemeriksaan bukan otomatis pelanggaran. Jangan menjamin lama clearance tertentu. Minta status deklarasi, referensi kasus dan dokumen yang diminta untuk review tim operasional lewat inquiry resmi.', 'https://www.beacukai.go.id/')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- customs-reimport-return
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('customs-reimport-return', 'customs', 'Re-import, return and re-export need case assessment', 'Re-impor, retur dan re-ekspor perlu kajian kasus', 'Re-import of previously exported goods, return shipments and re-export from customs-controlled locations are separate procedures with regime-specific declarations and evidence. Eligibility for duty/tax facilities, the need for prior export documents and authorizations vary by facts and legal requirements. A submitted but unregistered import declaration may require different treatment from an accepted declaration. Do not prescribe one universal procedure; route to Request Quote for review of status and documents.', 'Re-impor barang yang sebelumnya diekspor, retur dan re-ekspor dari lokasi dalam pengawasan pabean memiliki prosedur berbeda dengan deklarasi dan pembuktian yang spesifik. Kelayakan fasilitas bea/pajak, kebutuhan dokumen ekspor lama serta izin bergantung fakta dan aturan. PIB yang disubmit tetapi belum mendapat nomor pendaftaran dapat membutuhkan penanganan berbeda dari PIB yang sudah diterima. Jangan menetapkan satu prosedur universal; arahkan Request Quote untuk review status dan dokumen.', 'https://www.beacukai.go.id/')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- customs-compliance
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('customs-compliance', 'customs', 'Restricted, prohibited and controlled cargo', 'Barang dibatasi, dilarang atau dikendalikan', 'Goods subject to sanctions, export controls, restricted-party screening, import prohibitions or destination permits must be cleared by compliance specialists. A forwarder cannot bypass a restriction by using another route or changing the stated commodity. Any request to conceal cargo identity, misdeclare value or evade controls must be refused. For legitimate shipments, obtain accurate declarations and refer to Request Quote for a lawful feasibility assessment.', 'Barang terkait sanctions, export controls, screening pihak terbatas, larangan impor atau izin tujuan harus ditelaah spesialis compliance. Forwarder tidak dapat menghindari pembatasan dengan mengganti rute atau menyamarkan komoditas. Permintaan menyembunyikan identitas cargo, salah deklarasi nilai atau mengakali aturan harus ditolak. Untuk pengiriman legal, kumpulkan deklarasi akurat dan arahkan Request Quote untuk kajian kepatuhan.', 'https://www.insw.go.id/intr')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- cost-components-overview
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('cost-components-overview', 'operations', 'Freight quotation: total landed logistics cost', 'Quotation freight: komponen total biaya logistics', 'An end-to-end freight quote can contain pickup/trucking, origin handling, customs/brokerage, packaging, main freight, carrier surcharges, terminal/port charges, destination handling, import customs, taxes where included, delivery, cargo insurance and additional handling. Scope depends on mode, Incoterm, route and contract. Separate fixed quoted costs from variable pass-through charges and exclusions. Do not generate a VORA price without an approved rate; use Request Quote.', 'Quotation freight end-to-end dapat terdiri dari pickup/trucking, origin handling, customs/brokerage, packing, main freight, surcharge carrier, biaya terminal/pelabuhan, destination handling, customs impor, pajak bila termasuk, delivery, cargo insurance dan special handling. Cakupan tergantung moda, Incoterm, rute dan kontrak. Pisahkan biaya tetap yang dikutip, biaya variabel/pass-through dan exclusions. Jangan membuat tarif VORA tanpa rate yang disetujui; gunakan Request Quote.', 'https://fiata.com/')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- cost-ocean-main
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('cost-ocean-main', 'operations', 'Ocean freight base rate and carrier surcharges', 'Ocean freight base rate dan surcharge carrier', 'Ocean quotations may include ocean base freight and carrier-related surcharges (for example bunker, peak-season, security, equipment or congestion charges), depending on current tariff and booking. Do not assume the names or amounts are universal or fixed. Compare validity, inclusions, transit/routing, cancellation and equipment terms. Request Quote for current applicable selling rate.', 'Quotation ocean freight dapat memuat base freight dan surcharge carrier (misalnya bunker, peak season, security, equipment atau congestion), sesuai tarif dan booking yang berlaku. Nama serta nominal surcharge tidak universal atau tetap. Bandingkan validitas, inclusions, transit/routing, cancellation dan ketentuan equipment. Gunakan Request Quote untuk selling rate aktual.', 'https://fiata.com/')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- cost-origin-local
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('cost-origin-local', 'operations', 'Origin local charges and export handling', 'Origin local charges dan handling ekspor', 'Possible origin costs include trucking, empty pickup, stuffing, CFS (for LCL), terminal handling, VGM, BL/documentation, export clearance, inspection and special equipment fees. Actual billing party and applicability vary by port, service and Incoterm. Clarify whether quotes are ex-works, port-to-port or door-to-door and identify charges excluded from the freight line. Request Quote for a detailed breakdown.', 'Origin cost dapat meliputi trucking, empty pickup, stuffing, CFS (LCL), terminal handling, VGM, BL/documentation, clearance ekspor, pemeriksaan dan biaya equipment khusus. Pihak penagih dan keberlakuan biaya bervariasi menurut pelabuhan, layanan dan Incoterm. Jelaskan apakah penawaran ex-works, port-to-port atau door-to-door serta biaya yang dikecualikan dari freight. Request Quote untuk breakdown.', 'https://fiata.com/')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- cost-destination-local
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('cost-destination-local', 'operations', 'Destination local charges and final delivery', 'Destination local charges dan final delivery', 'Possible destination charges include terminal handling, D/O or release processing, CFS/deconsolidation, customs clearance, inspections, warehouse/storage, import delivery, equipment and other local charges. The consignee may face charges not included in origin prepaid freight. Exact amounts depend on the destination agent, line, terminal and release conditions. Always state whether destination charges are included or excluded in a quote.', 'Destination cost dapat mencakup terminal handling, D/O atau release, CFS/deconsolidation, clearance impor, pemeriksaan, warehouse/storage, delivery, equipment dan local charges lain. Consignee bisa memiliki biaya yang tidak termasuk freight prepaid di origin. Nominal mengikuti agent tujuan, shipping line, terminal dan syarat release. Quotation harus menyebut destination charges termasuk atau tidak.', 'https://fiata.com/')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- cost-demurrage-detention
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('cost-demurrage-detention', 'operations', 'Demurrage, detention and terminal storage', 'Demurrage, detention dan storage terminal', 'Demurrage generally concerns container equipment remaining in the terminal beyond allowed free time; detention generally concerns equipment held outside terminal/depot beyond its free time. Terminal storage is a separate possible terminal charge; some carrier tariffs combine demurrage/detention or use different definitions. Starting event, calendar-day rules, holidays, tiers and free-time length must be verified with the actual carrier and terminal. Never infer a universal daily amount.', 'Demurrage umumnya terkait penggunaan container di terminal melampaui free time; detention terkait penggunaan equipment di luar terminal/depot setelah free time. Storage terminal bisa menjadi biaya terpisah; sebagian carrier menggabungkan demurrage/detention atau menggunakan definisi sendiri. Awal perhitungan, hari kalender, hari libur, tier dan lamanya free time harus dicek pada carrier/terminal aktual. Jangan menebak tarif harian universal.', 'https://fiata.com/')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- cost-dg-special
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('cost-dg-special', 'operations', 'Special handling / DG / OOG additional costs', 'Biaya tambahan DG, OOG dan special handling', 'Special cargo may incur DG approval/premium, surveyor, controlled storage, escort, special equipment, lifting/rigging, lashing, special stowage, power supply, reefer monitoring or additional insurance. Some costs depend on engineering plans or port inspections and cannot be responsibly quoted from commodity name alone. RFQ should capture dimensions, weights, packing, hazards, readiness and special constraints.', 'Kargo khusus dapat menimbulkan DG approval/premium, surveyor, gudang khusus, escort, equipment, lifting/rigging, lashing, special stowage, listrik, reefer monitoring atau asuransi tambahan. Sebagian biaya baru dapat dihitung dari engineering plan atau inspeksi pelabuhan dan tidak cukup dari nama komoditas. RFQ harus memuat dimensi, berat, packing, hazard, readiness serta kendala handling.', 'https://voraworld.id/en/request-quote')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- cost-air-chargeable
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('cost-air-chargeable', 'operations', 'Air freight chargeable weight and surcharges', 'Chargeable weight dan surcharge air freight', 'Air cargo is typically charged on the greater of actual gross weight and volumetric weight under the carrier tariff. A common industry illustration is length x width x height in centimetres divided by 6000, but the divisor and rounding rules vary by carrier and product. Security, fuel, screening, terminal, DG, handling and documentation charges may apply. Final billable weight and price require airline rate confirmation via Request Quote.', 'Air freight umumnya menggunakan nilai terbesar antara gross weight aktual dan volumetric weight sesuai tarif carrier. Ilustrasi umum adalah P x L x T dalam cm dibagi 6000, tetapi divisor dan aturan pembulatan dapat berbeda menurut airline/service. Biaya security, fuel, screening, terminal, DG, handling dan dokumentasi dapat berlaku. Chargeable weight dan harga final harus dikonfirmasi dari airline melalui Request Quote.', 'https://fiata.com/')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- cost-sea-lcl-wm
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('cost-sea-lcl-wm', 'operations', 'LCL W/M charging and CFS charges', 'Perhitungan LCL W/M dan biaya CFS', 'LCL ocean freight often uses W/M (weight or measurement), comparing cargo weight in metric tonnes with volume in CBM and charging according to the agreed tariff minimum and rounding rules. CFS, handling, documentation and origin/destination local charges may be additional. The billing method can differ by lane and provider. Request accurate package count, dimensions, gross weights and port pair before quoting.', 'LCL sea freight sering menggunakan W/M (weight or measurement), yaitu membandingkan berat dalam metric ton dengan volume CBM sesuai minimum dan aturan pembulatan tarif. CFS, handling, dokumen serta origin/destination local charges dapat ditagih terpisah. Dasar billing bisa berbeda menurut rute dan penyedia. Minta jumlah koli, dimensi, gross weight dan port asal/tujuan sebelum quotation.', 'https://fiata.com/')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- cost-fcl-trucking
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('cost-fcl-trucking', 'operations', 'FCL trucking, container movement and waiting', 'Trucking FCL, pergerakan container dan biaya tunggu', 'FCL inland costs may include trucking, tolls, fuel, chassis, empty pickup/return, seal, loading/unloading, standby, driver overtime, restricted road access and special permit requirements. Waiting-time definitions and container detention risk depend on booking milestones and contract. A rate quoted only for a road distance may omit material costs. Ask exact loading/delivery address, truck access, container type, weight and schedule.', 'Biaya trucking FCL dapat meliputi angkutan, tol, BBM, chassis, pengambilan/pengembalian empty, seal, loading/unloading, standby, overtime, pembatasan jalan dan izin khusus. Definisi waiting dan risiko detention bergantung milestone serta kontrak. Rate berdasarkan jarak saja bisa mengecualikan biaya material. Minta alamat muat/bongkar, akses truk, jenis container, berat dan jadwal.', 'https://voraworld.id/en/request-quote')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- cost-warehousing
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('cost-warehousing', 'operations', 'Warehousing and fulfillment charging models', 'Model biaya warehousing dan fulfillment', 'Warehousing prices may be calculated per pallet position/day, m2, m3, bin, item, inbound/outbound transaction, pick line, pack, labeling, inventory count, storage duration and value-added services. Minimum charges, overtime, special storage, insurance and shrinkage liability require contract review. DG or temperature-controlled storage needs separate technical and legal assessment. Ask inventory dimensions, SKU count, throughput and service levels for RFQ.', 'Biaya warehousing dapat dihitung per posisi pallet/hari, m2, m3, bin, item, transaksi inbound/outbound, pick line, pack, labeling, stock count, durasi atau layanan tambahan. Minimum charge, overtime, storage khusus, insurance dan tanggung jawab selisih stok harus diperiksa dalam kontrak. Gudang DG atau suhu terkendali butuh penilaian teknis/legal terpisah. Minta ukuran inventory, jumlah SKU, throughput dan SLA untuk RFQ.', 'https://voraworld.id/en/request-quote')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- cost-insurance
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('cost-insurance', 'operations', 'Cargo insurance versus carrier liability', 'Cargo insurance dibanding carrier liability', 'Cargo insurance is separate from the carrier/forwarder legal liability and policy coverage varies by insured risks, exclusions, deductibles, commodities, voyage and declaration value. An Incoterm does not automatically mean comprehensive insurance is included. Higher-risk goods may require underwriting approval and packing standards. Confirm coverage, insured value and claims process in an RFQ rather than implying all-risk protection.', 'Cargo insurance berbeda dari tanggung jawab hukum carrier/forwarder. Cakupan polis mengikuti risiko pertanggungan, pengecualian, deductible, komoditas, perjalanan dan nilai deklarasi. Incoterm tidak otomatis berarti asuransi komprehensif sudah termasuk. Barang berisiko dapat memerlukan approval underwriting dan standar packing. Pastikan cakupan, insured value dan proses klaim lewat RFQ, jangan menjanjikan all-risk otomatis.', 'https://iccwbo.org/business-solutions/incoterms-rules/incoterms-2020/')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- cost-rates-validity
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('cost-rates-validity', 'operations', 'Rate validity, currency and exclusions', 'Validitas tarif, mata uang dan pengecualian', 'A freight rate is only valid under its stated dates, cargo assumptions, equipment, port pair, service level, currency, payment terms and carrier conditions. Spot rates can change before booking acceptance. Exchange rates, taxes, terminal charges, DG premiums and free time must be explicitly addressed. An AI assistant cannot issue an approved VORA selling rate or guarantee an ETA; Request Quote for a written offer.', 'Freight rate berlaku mengikuti tanggal, asumsi cargo, equipment, port pair, SLA, mata uang, termin pembayaran dan syarat carrier yang tercantum. Spot rate dapat berubah sebelum booking diterima. Kurs, pajak, terminal charges, premium DG dan free time perlu dinyatakan jelas. AI tidak boleh mengeluarkan selling rate resmi VORA atau menjamin ETA; Request Quote untuk penawaran tertulis.', 'https://fiata.com/')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- cost-customs-fees
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('cost-customs-fees', 'operations', 'Customs brokerage fees versus government duties', 'Jasa customs brokerage dibanding pungutan negara', 'Brokerage/service fees and government import duties, taxes, export duties or other statutory levies are separate items. Charges for customs inspections, surveys, storage or late documentation may also be distinct. Values depend on HS code, declared value, origin, preferential rules and current regulation. Quotes should say who pays each cost and whether taxes are estimated or pass-through.', 'Biaya jasa customs brokerage berbeda dari bea masuk, pajak impor, bea keluar atau pungutan resmi lain. Biaya pemeriksaan, survey, storage dan keterlambatan dokumen dapat terpisah. Nominal bergantung HS Code, nilai deklarasi, origin, tarif preferensi dan regulasi terbaru. Quotation perlu jelas menyebut siapa menanggung setiap biaya dan mana pajak estimasi atau pass-through.', 'https://www.insw.go.id/intr')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- docs-invoice-packing
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('docs-invoice-packing', 'documentation', 'Commercial invoice and packing list essentials', 'Isi penting commercial invoice dan packing list', 'A commercial invoice describes seller/buyer, commodities, quantities, values, currency and sale terms. A packing list normally provides package count, packing types, gross/net weights and dimensions. Cargo descriptions across documents, booking and customs must be consistent without fabricating quantities or values. Some commodities require technical datasheets, certificates or special declarations. Ask for complete accurate documents rather than making them up.', 'Commercial invoice umumnya memuat seller/buyer, komoditas, kuantitas, nilai, mata uang dan ketentuan penjualan. Packing list berisi jumlah koli, jenis kemasan, gross/net weight dan dimensi. Deskripsi barang pada dokumen, booking serta deklarasi pabean harus konsisten tanpa mengarang jumlah/nilai. Komoditas tertentu butuh datasheet, sertifikat atau deklarasi khusus. Minta dokumen akurat dan lengkap, jangan membuat data sendiri.', 'https://www.beacukai.go.id/')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- docs-bl-awb
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('docs-bl-awb', 'documentation', 'Bill of Lading, Sea Waybill and Air Waybill', 'Bill of Lading, Sea Waybill dan Air Waybill', 'A sea Bill of Lading can function as evidence of carriage and may be a document of title depending on form and terms; a sea waybill generally supports non-negotiable cargo release. Air Waybill is usually a non-negotiable air carriage document. Master and house documents can have different issuers and consignee fields. Release procedure, originals, telex release and carrier terms must be confirmed per shipment.', 'Bill of Lading laut dapat menjadi bukti pengangkutan dan dalam bentuk tertentu berfungsi sebagai document of title; sea waybill umumnya digunakan untuk release non-negotiable. Air Waybill biasanya bukan negotiable title document. Dokumen master dan house dapat berbeda penerbit serta data consignee. Prosedur release, original BL, telex release dan ketentuan carrier harus dikonfirmasi tiap shipment.', 'https://fiata.com/')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- docs-vgm
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('docs-vgm', 'documentation', 'SOLAS Verified Gross Mass (VGM)', 'SOLAS Verified Gross Mass (VGM)', 'For packed export containers subject to SOLAS, a verified gross mass (VGM) is required before loading onto a ship. It can be established using approved weighing methods subject to local regulation; it includes the container tare plus all cargo and packing material. VGM is not equal to cargo gross weight alone. Ask for packed container details, verified weight process, deadline and responsible shipper. Carrier/terminal cutoffs must be checked.', 'Untuk container ekspor yang tunduk pada SOLAS, Verified Gross Mass (VGM) dibutuhkan sebelum dimuat ke kapal. Perhitungannya dapat memakai metode timbang yang disetujui sesuai ketentuan lokal, mencakup tare container ditambah muatan dan material packing. VGM berbeda dari gross weight cargo saja. Minta data container, metode verifikasi berat, deadline dan pihak shipper yang bertanggung jawab. Cutoff carrier/terminal harus dicek.', 'https://www.imo.org/en/mediacentre/hottopics/pages/container-default.aspx')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- docs-wood-packaging
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('docs-wood-packaging', 'documentation', 'Wood packaging / ISPM 15 and fumigation', 'Kemasan kayu / ISPM 15 dan fumigasi', 'International wooden packaging may be subject to phytosanitary standards such as ISPM 15, depending on packing material and trade lane. Correct treatment and official marking may be required; fumigation is not automatically mandatory for every wood-containing shipment. Check the destination-country requirements and pallet/crate details. For project cargo, packaging and export compliance should be reviewed before pickup.', 'Kemasan kayu internasional dapat terkena standar fitosanitari seperti ISPM 15, bergantung jenis packing dan rute. Treatment serta marking yang benar dapat dipersyaratkan; fumigasi tidak otomatis wajib untuk setiap shipment dengan kayu. Periksa persyaratan negara tujuan dan detail pallet/crate. Untuk project cargo, kesiapan packing serta ekspor perlu dicek sebelum pickup.', 'https://www.insw.go.id/intr')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- docs-cutoff
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('docs-cutoff', 'operations', 'CY/CFS cutoff, SI cutoff and booking timelines', 'CY/CFS cutoff, SI cutoff dan jadwal booking', 'Ocean shipments may have different documentation (SI), verified gross mass (VGM), cargo gate-in (CY), CFS delivery and DG approval cutoffs. Missing one cutoff can result in rolling to another vessel and extra charges. Cutoffs are sailing-, carrier- and terminal-specific, not universal rules. Obtain booking confirmation, vessel/voyage and cargo readiness before making an operational commitment.', 'Shipment laut dapat memiliki cutoff terpisah untuk Shipping Instruction (SI), VGM, gate-in container (CY), penyerahan LCL di CFS dan approval DG. Terlewat salah satu cutoff dapat membuat cargo roll ke kapal berikutnya dan menambah biaya. Cutoff bergantung sailing, carrier dan terminal, bukan aturan universal. Minta booking confirmation, vessel/voyage dan kesiapan cargo sebelum komitmen operasional.', 'https://fiata.com/')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- docs-rfq-minimum
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('docs-rfq-minimum', 'faq', 'Minimum information for freight RFQ', 'Data minimum untuk permintaan quotation freight', 'For a meaningful quotation request collect origin and destination (addresses or ports), shipment mode, commodity and intended use, number of packages or containers, dimensions/weight, readiness date, Incoterms where known, packing condition and special handling needs. For DG add SDS/UN details; for reefer add setpoint; for OOG add per-piece drawings; for regulated goods add HS and permit information where available. Ask only one or two questions at a time in chat, then guide to Request Quote.', 'Untuk quotation yang relevan minta origin dan tujuan (alamat atau port), moda, komoditas serta penggunaan, jumlah koli/container, dimensi/berat, ready date, Incoterm bila ada, kondisi packing dan kebutuhan special handling. Untuk DG tambah SDS/UN; reefer tambah setpoint; OOG tambah drawing per piece; barang lartas tambah HS/izin yang tersedia. Dalam chat tanyakan satu atau dua hal dulu, lalu arahkan Request Quote.', 'https://voraworld.id/en/request-quote')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- docs-no-fabrication
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('docs-no-fabrication', 'faq', 'No invented rates, permits, approvals or capabilities', 'Larangan mengarang tarif, izin, approval dan capability', 'VORA Virtual Agent can explain the shipping process and collect requirements but cannot issue approved freight rates, carrier space confirmation, dangerous goods acceptance, customs permits, shipment booking, real-time tracking or guarantees. References in internal knowledge are for staff verification only, not for customer-facing citations. For uncertain operational or legal situations, state what needs checking and offer an actionable Request Quote button.', 'VORA Virtual Agent boleh menjelaskan proses shipping dan mengumpulkan kebutuhan, tetapi tidak dapat memberikan freight rate resmi, kepastian slot carrier, acceptance DG, izin customs, konfirmasi booking, tracking real-time atau jaminan. Referensi knowledge adalah untuk validasi internal, bukan ditampilkan sebagai sitasi di jawaban customer. Untuk situasi operasional/legal yang belum pasti, jelaskan aspek yang harus dicek dan tampilkan tombol Request Quote.', 'https://voraworld.id/en/request-quote')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- docs-quick-escalation
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('docs-quick-escalation', 'faq', 'When to escalate to Request Quote', 'Kapan harus diarahkan ke Request Quote', 'Always encourage a formal RFQ for dangerous goods and charcoal, lithium batteries, reefer/cold-chain and perishable cargo, OOG/heavy-lift/breakbulk/charter, high-value or fragile items, live permits and restricted products, unusual packaging, and any actual customer rate/availability question. Avoid generic blanket acceptance. Offer concise next questions and a clearly clickable first-party Request Quote action; do not print a raw URL.', 'Selalu arahkan RFQ resmi untuk DG dan charcoal, baterai lithium, reefer/cold chain serta perishable, OOG/heavy-lift/breakbulk/charter, high-value/fragile, izin/lartas barang, packing tidak standar dan pertanyaan tarif/availability aktual. Jangan menyatakan acceptance secara umum. Ajukan pertanyaan lanjutan yang ringkas dan tampilkan tombol Request Quote yang bisa diklik, bukan path URL mentah.', 'https://voraworld.id/en/request-quote')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- operations-cargo-inspection
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('operations-cargo-inspection', 'operations', 'Cargo survey, packaging and photos', 'Cargo survey, packing dan foto', 'Cargo readiness for high-value, breakbulk, DG or sensitive shipments may need surveys, verified weights/dimensions, photographs, packaging tests and evidence of lashing/lifting points. Visual appearance alone cannot prove engineering suitability or customs classification. Document deviations and any damage before handling and maintain clear chain of custody. Ask the shipper for available photos/drawings and propose RFQ for assessment.', 'Kesiapan cargo high-value, breakbulk, DG atau sensitif dapat memerlukan survey, verifikasi berat/dimensi, foto, pengujian packing serta bukti lashing/lifting point. Penampilan visual saja tidak membuktikan kelayakan engineering atau klasifikasi customs. Catat penyimpangan/kerusakan sebelum handling dan jaga chain of custody. Minta foto/drawing yang ada, lalu RFQ untuk penilaian.', 'https://voraworld.id/en/request-quote')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- operations-shipment-tracking
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('operations-shipment-tracking', 'operations', 'Tracking milestones and ETA limitations', 'Milestone tracking dan keterbatasan ETA', 'Freight tracking may include pickup, CFS/terminal receipt, departure, transshipment, arrival, customs release and final delivery. ETD/ETA are estimates subject to schedule changes, weather, congestion and customs. VORA Virtual Agent has no automatic access to real-time carrier tracking or shipment numbers unless a verified tool integration is provided. Never fabricate a vessel position or status. For shipment-specific updates, contact the VORA team.', 'Tracking freight dapat memuat pickup, penerimaan CFS/terminal, departure, transshipment, arrival, customs release hingga delivery. ETD/ETA merupakan estimasi yang bisa berubah akibat schedule, cuaca, congestion dan customs. VORA Virtual Agent tidak otomatis punya akses tracking carrier real-time atau nomor shipment tanpa integrasi terverifikasi. Jangan mengarang posisi kapal atau status. Untuk update shipment tertentu, arahkan ke tim VORA.', 'https://voraworld.id/en/request-quote')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
  -- operations-cargo-claims
  v_id := NULL;
  INSERT INTO public.agent_knowledge(seed_key,category,title_en,title_id,body_en,body_id,source_url)
  VALUES('operations-cargo-claims', 'operations', 'Cargo damage and logistics claims basics', 'Dasar claim kerusakan cargo', 'For damage or shortage complaints, preserve packaging and evidence, record dates and parties, note the delivery receipt status, take clear photos, and notify the relevant carrier/forwarder/insurer promptly under applicable contract timelines. Liability and coverage cannot be determined from a chat description. Advise submitting complete documents through the customer service channel instead of accepting liability or promising compensation.', 'Jika ada kerusakan/selisih barang, simpan kemasan dan bukti, catat tanggal serta pihak, periksa status bukti serah terima, ambil foto jelas dan beri notifikasi ke carrier/forwarder/asuransi sesuai batas waktu kontrak. Liability dan cakupan tidak dapat diputuskan dari chat saja. Arahkan dokumen lengkap ke customer service, jangan langsung mengakui tanggung jawab atau menjanjikan kompensasi.', 'https://voraworld.id/en/request-quote')
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  IF v_id IS NOT NULL THEN PERFORM public.agent_knowledge_publish(v_id,NULL,1); END IF;
END $vora_safety_seed$;

-- ---------------------------------------------------------------------------
-- 0037_agent_salutations.sql
-- ---------------------------------------------------------------------------
-- VORA Virtual Agent: visitor-selected form of address, stored on private session only.
-- Never infer gender or marital status from names or contact records.
ALTER TABLE public.agent_sessions
  ADD COLUMN IF NOT EXISTS visitor_salutation varchar(8);

DO $$ BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint WHERE conname = 'agent_sessions_visitor_salutation_check'
      AND conrelid = 'public.agent_sessions'::regclass
  ) THEN
    ALTER TABLE public.agent_sessions ADD CONSTRAINT agent_sessions_visitor_salutation_check
      CHECK (visitor_salutation IS NULL OR visitor_salutation IN ('bapak','ibu','mr','ms','mrs','name'));
  END IF;
END $$;

-- ---------------------------------------------------------------------------
-- 0038_agent_salutation_kak.sql
-- ---------------------------------------------------------------------------
-- VORA Virtual Agent: add the Indonesian form of address "Kak" to the visitor salutation choices.
-- Replaces the check from 0037 with a superset, so every row written before stays valid.
ALTER TABLE public.agent_sessions
  DROP CONSTRAINT IF EXISTS agent_sessions_visitor_salutation_check;

ALTER TABLE public.agent_sessions
  ADD CONSTRAINT agent_sessions_visitor_salutation_check
  CHECK (visitor_salutation IS NULL OR visitor_salutation IN ('bapak','ibu','kak','mr','ms','mrs','name'));

